  ui_story_5051_50510101_11_dialog_content = "(한 사람의 인생을 이렇게 망쳐놓고...\n잘도 뻔뻔하게 「가문의 날」 따위 이름으로 연회를 벌여?!)",
  ui_story_5051_50510101_12_dialog_content = "(...걱정 말아요. 가서 그 녀석과 싸우진 않을 테니까요.)",
  ui_story_5051_50510101_13_dialog_content = "(어쩌면... 이번이 마지막 희망일지도 모르죠.\n반드시 <color=#FFB400>「그걸」</color> 가지고 돌아올게요.)",
  ui_story_5051_50510101_14_dialog_content = "(항상 제게 했던 약속을 지킨 것처럼... 저도 꼭 약속을 지킬게요.)",
