  ui_story_5051_50510101_18_dialog_content = "-",
  ui_story_5051_50510101_19_dialog_content = "-",
  ui_story_5051_50510101_20_dialog_content = "「친애하는 PlayerName, 조만간 북방의 사절이 백야성을 찾는다.」",
  ui_story_5051_50510101_21_dialog_content = "「연회에 초대받은 그대에게 좋은 동행자가 될 것이라 생각한다.」",
  ui_story_5051_50510101_22_dialog_content = "「움브라톤의 교외에서 사절을 기다리도록 해라.」",
