  ui_story_5051_50510101_X23_dialog_content = "(편지에서 말씀하신 「사절」이란 사람은 대체 어딜 간 거야?)",
  ui_story_5051_50510101_23_dialog_content = "-",
  ui_story_5051_50510101_24_dialog_content = "<size=30>저기...</size>",
  ui_story_5051_50510101_25_dialog_content = "(그나저나 「가문의 날」 초대장이 왔을 땐 정말 깜짝 놀랐다니까.\n그런 거창한 연회에 참석하는 건 처음이고...)",
  ui_story_5051_50510101_26_dialog_content = "(이 예복으로 괜찮을까? 이상하진 않겠지?)",
  ui_story_5051_50510101_27_dialog_content = "-",
  ui_story_5051_50510101_28_dialog_content = "-",
  ui_story_5051_50510101_29_dialog_content = "(휴, 이럴 때 카렌이 있어줬으면 좋았을 텐데.)",
  ui_story_5051_50510101_30_dialog_content = "(근데 요즘 어디 간 건지 모르겠네. 전혀 연락도 안 되고.)",
  ui_story_5051_50510101_31_dialog_content = "저기... 잠깐만...",
  ui_story_5051_50510101_32_dialog_content = "(아, 맞다. 예복 말고 선물도 까먹으면 안 되지! 이걸로 괜찮겠지?)",
  ui_story_5051_50510101_33_dialog_content = "저기...!",
  ui_story_5051_50510101_34_dialog_content = "으아악! 바, 바바, 바바 야가?! 네가 왜 여기 있어?!",
  ui_story_5051_50510101_35_dialog_content = "으앗!",
  ui_story_5051_50510101_36_dialog_content = "미, 미안해.",
  ui_story_5051_50510101_37_dialog_content = "어? 혹시 바바 야가의 또 다른 인격... <color=#FFB400>미아</color>?",
  ui_story_5051_50510101_38_dialog_content = "응, 나야.",
  ui_story_5051_50510101_39_dialog_content = "정확히는 내가 이 몸의 주인이지만...",
  ui_story_5051_50510101_40_dialog_content = "난 바바 야가처럼 강하지 않아서, 자신을 잘 제어할 수 없어...\n그래서 여러 가지 일을 그 애가 대신 해 주고 있어...",
  ui_story_5051_50510101_41_dialog_content = "미안해. 놀라게 해버려서...",
  ui_story_5051_50510101_42_dialog_content = "괜찮아. 그래서 무슨 일이야?",
  ui_story_5051_50510101_X42_dialog_content = "저기, PlayerName 네가 「솔라드 가문의 날」 연회에 참석한다고 들었어.",
  ui_story_5051_50510101_X43_dialog_content = "나도... 데려가 줄 수 있을까?",
  ui_story_5051_50510101_X44_dialog_content = "널 데려가라고? 괜찮긴 한데, 왜 갑자기 그 연회에 가고 싶어진 건데?",
  ui_story_5051_50510101_X45_dialog_content = "음... 요즘 치료를 받으면서 병세가 많이 좋아졌거든.",
  ui_story_5051_50510101_43_dialog_content = "음... 요즘 치료를 받으면서 병세가 많이 좋아졌거든.",
  ui_story_5051_50510101_44_dialog_content = "그랬더니... 생각이 났어...",
  ui_story_5051_50510101_45_dialog_content = "뭐가?",
  ui_story_5051_50510101_46_dialog_content = "난 <color=#FFB400>카렌의 언니</color>야.",
  ui_story_5051_50510101_47_dialog_content = "카렌의 언니?!",
  ui_story_5051_50510101_48_dialog_content = "백야성 공주는 한 명 아니었어?",
  ui_story_5051_50510101_49_dialog_content = "그리고 넌 카렌이랑... 아니, 자세히 보니까 진짜 좀 닮긴 했네.",
  ui_story_5051_50510101_50_dialog_content = "믿기 힘들지?",
