  ui_story_5051_50510101_93_dialog_content = "아니지, 북방을 나온 뒤로부터 보이는 모든 게 다 재미있었다니까요~",
  ui_story_5051_50510101_94_dialog_content = "그래서 정신없이 보다 보니... 길을 잃어버렸지 뭐예요, 헤헷!",
  ui_story_5051_50510101_95_dialog_content = "그래도 괜찮아요. 제 귀여운 수정구슬만 있으면 항상 길을 찾을 수 있거든요!",
