  ui_story_5051_50510101_97_dialog_content = "그래도 여행이란 건 원래 우여곡절과 자극이 넘치는 거니까요!\n예리아 선생님이 그러셨어요!",
  ui_story_5051_50510101_98_dialog_content = "그래서 방금 어디까지 얘기했었죠? 아, 움브라톤!",
  ui_story_5051_50510101_99_dialog_content = "움브라톤은 길이 복잡하지만 사실은 「입지」를 무척 신경 쓴 설계예요.",
  ui_story_5051_50510101_X99_dialog_content = "이걸 아는 사람들은 모두 금전운이 좋은 곳에 가게를 차린다고 해요!",
  ui_story_5051_50510101_100_dialog_content = "아, 「입지」에 대한 이야기는 지나가던 여행자가 말해준 거예요.",
  ui_story_5051_50510101_101_dialog_content = "기회가 되면 그쪽 지식도 꼭 공부해 보고 싶네요... 앗, 이 날아다니는 건 뭐죠?!",
  ui_story_5051_50510101_102_dialog_content = "저기...",
  ui_story_5051_50510101_103_dialog_content = "넌 누구야?",
  ui_story_5051_50510101_104_dialog_content = "앗, 미안해요! 자기소개를 잊었네요!",
  ui_story_5051_50510101_105_dialog_content = "전 <color=#FFB400>쟈키니</color>라고 해요. 북방에서 파견한 사절이 바로 저예요!",
  ui_story_5051_50510101_106_dialog_content = "-",
  ui_story_5051_50510101_107_dialog_content = "<size=45>...어떻게 이렇게까지 늦을 수가 있어?!</size>",
  ui_story_5051_50510101_X107_dialog_content = "헤, 헤헷, 그래도 주인공은 마지막에 등장한다는 말도 있잖아요!",
  ui_story_5051_50510101_X108_dialog_content = "크흠, 여러분, 안녕하세요!",
  ui_story_5051_50510101_X109_dialog_content = "오늘 밤 우리는 한자리에 모여.",
  ui_story_5051_50510101_X110_dialog_content = "일 년에 한 번 있는 성찬에 참가합니다.",
  ui_story_5051_50510101_X111_dialog_content = "그 무엇과도 비할 수 없는 탐식을 하죠.",
  ui_story_5051_50510101_X112_dialog_content = "하지만 육식은 항상 질리기 마련이에요.",
  ui_story_5051_50510101_X113_dialog_content = "좋은 술도 언젠가는 다 마시고 바닥나죠.",
  ui_story_5051_50510101_X114_dialog_content = "담소를 나누는 틈에 분위기를 좀 바꿔보는 건 어떨까요?",
  ui_story_5051_50510101_X115_dialog_content = "오락 프로그램이 주는 재미를 느껴 보세요.",
  ui_story_5051_50510101_108_dialog_content = "-",
  ui_story_5051_50510101_109_dialog_content = "이어서 저희 키팅 성가대가──",
  ui_story_5051_50510101_110_dialog_content = "여러분께 노래 한 곡을 선보이겠습니다.",
  ui_story_5051_50510101_111_dialog_content = "제목은 《백야의 송가》입니다.",
  ui_story_5051_50510101_112_dialog_content = "즐겁게 감상해 주세요!",
  ui_story_5051_50510101_113_dialog_content = "별들과 함께 하늘로 떠오르는 태양~♪",
  ui_story_5051_50510101_114_dialog_content = "석양이 비추는 숭고한 왕좌~♪",
  ui_story_5051_50510101_115_dialog_content = "몸을 방패로 삼고~♪",
  ui_story_5051_50510101_116_dialog_content = "자신을 창으로 삼네~♪",
  ui_story_5051_50510101_117_dialog_content = "고귀한 영광은 신앙의 증거~♪",
  ui_story_5051_50510101_118_dialog_content = "울림의 빛이 어둠을 쫓네~♪",
  ui_story_5051_50510101_119_dialog_content = "영원히 떨어지지 않는 하늘의 성~♪",
  ui_story_5051_50510101_120_dialog_content = "모두 마음에 새기자~♪",
  ui_story_5051_50510101_121_dialog_content = "모두 마땅히 찬양해~♪",
  ui_story_5051_50510101_122_dialog_content = "그림자는 지나가고~♪",
  ui_story_5051_50510101_123_dialog_content = "영원한 태양이 오리라~♪",
  ui_story_5051_50510101_124_dialog_content = "만물은 백야 아래에, 감사합니다.",
  ui_story_5051_50510101_125_dialog_content = "우와~ 대단해~ 정말 좋은 노래였어~",
