  ui_story_5051_50510101_143_dialog_content = "-",
  ui_story_5051_50510101_144_dialog_content = "-",
  ui_story_5051_50510101_145_dialog_content = "하지만 그 재앙이 사람들에게 남긴 상처는 여전히 처음처럼 선명해요.",
  ui_story_5051_50510101_146_dialog_content = "대재앙의 경험자...아니, 생존자는 설령 막강한 사천사라 해도\n그 상처와 아픔을 극복할 순 없는 걸까요...",
  ui_story_5051_50510101_147_dialog_content = "어머 어머, 이리돈~ 자, 웃어~",
  ui_story_5051_50510101_148_dialog_content = "안 그래도 볼거리 없는 연회잖아.",
  ui_story_5051_50510101_149_dialog_content = "더 즐기지 않으면 손해야~",
  ui_story_5051_50510101_150_dialog_content = "「솔라드 가문의 날」은 원래 솔라드 가문의 공적을 기리는 기념일이었죠.",
  ui_story_5051_50510101_151_dialog_content = "그리고 <color=#FFB400>12년 전</color>의 오늘, 지금의 성주님께서 일련의 위기를 제압하고\n다시 한번 솔라드 가문의 힘을 보여주셨습니다.",
  ui_story_5051_50510101_152_dialog_content = "하지만 어둠의 위기 이후로 「가문의 날」의 규모는 축소되고 말았죠.",
  ui_story_5051_50510101_153_dialog_content = "전에는 대규모 퍼레이드나 놀거리도 있었던 기억이 나네요.",
  ui_story_5051_50510101_154_dialog_content = "음, 그랬던 것 같기도 하고? 기억이 잘 안 나네~",
  ui_story_5051_50510101_155_dialog_content = "다만 「가문의 날」 행사를 축소해선 안 된다는 불만이 매년 나온 건 기억 나~",
  ui_story_5051_50510101_156_dialog_content = "다들 뭐라고 했더라... 아, 그렇지.",
  ui_story_5051_50510101_157_dialog_content = "「성주님께 직접 경의와 충성을 표명할 수 있는 자리를\n백야성의 청년들과 유능한 인재들에게 주어야 한다」라나 뭐라나~",
  ui_story_5051_50510101_158_dialog_content = "그래서 이렇게 간단한 연회라도 유지하고 있는 것이겠죠.",
  ui_story_5051_50510101_159_dialog_content = "전 성주님의 간소화 방침에 찬성해요.\n재정이나 인력의 부담 측면을 고려했을 때 매우 타당한 조치예요.",
  ui_story_5051_50510101_160_dialog_content = "다만 이런 기념일은 확실히 평소 바쁘게 일하는 사람들에게 휴식의 기회를 주기도 해요.",
  ui_story_5051_50510101_161_dialog_content = "가십거리를 들을 기회도 있고 말이야~",
  ui_story_5051_50510101_162_dialog_content = "전 그건 됐어요.",
  ui_story_5051_50510101_163_dialog_content = "이제 슬슬 들어가도 되겠지?",
  ui_story_5051_50510101_164_dialog_content = "물론 되죠!",
  ui_story_5051_50510101_165_dialog_content = "근데 왜 노래가 끝날 때까지 입구에서 기다린 건데요?",
  ui_story_5051_50510101_166_dialog_content = "노래하는 동안 안이 엄청 조용했잖아.\n그럴 때 갑자기 들어가면 너무 눈에 띄고 실례니까.",
  ui_story_5051_50510101_167_dialog_content = "네? 그런 규칙도 있나요?",
  ui_story_5051_50510101_168_dialog_content = "마, 맞아... 공연 중에 소리를 내는 건 실례야...",
  ui_story_5051_50510101_169_dialog_content = "...미아. 네가 나한테 네가 카렌의 언니라고 말했을 때 그 옷을 입었으면...",
  ui_story_5051_50510101_170_dialog_content = "분명히 즉시 조금의 의심도 없이 백 퍼센트 네 말을 믿었을걸.",
  ui_story_5051_50510101_171_dialog_content = "지금 넌 어떻게 봐도 백야성의 공주 같아!",
  ui_story_5051_50510101_172_dialog_content = "그, 그냥 평범한 드레스일 뿐인걸...\n연회에 참석하려면 적합한 옷차림을 해야 하니까...",
  ui_story_5051_50510101_173_dialog_content = "한 번, 두 번, 세 번... 당신 그 얘기 벌써 세 번째라구요!",
  ui_story_5051_50510101_174_dialog_content = "여자애를 계속 빤히 쳐다보면 안 되죠.",
  ui_story_5051_50510101_175_dialog_content = "나, 난 그냥 진짜 그렇게 생각해서 한 말이야.",
  ui_story_5051_50510101_176_dialog_content = "못 믿겠어요. 아까 콜로서스에서 보라색 옷 입은 여자애한테도\n연회에 데리고 간다고 했었잖아요?",
  ui_story_5051_50510101_177_dialog_content = "근데 왜 또 파트너가 바뀐 거죠?",
  ui_story_5051_50510101_178_dialog_content = "아... 지금 눈앞에 있는 이 하얀 드레스의 미아가 바로\n아까 콜로서스에서 만났던 보라색 드레스의 미아야!",
  ui_story_5051_50510101_179_dialog_content = "정말요?! 전혀 다른 사람으로 보이는데요?! 무슨 특수한 루미나틱스 같은 건가요?",
  ui_story_5051_50510101_180_dialog_content = "으, 으앗? 왜 갑자기 가까이 오는 건데...?",
  ui_story_5051_50510101_181_dialog_content = "너도 나랑 똑같잖아! 게다가 오는 내내 같이 있었는데도 몰랐어?!",
  ui_story_5051_50510101_182_dialog_content = "아, 아하하하... 백야성의 경치를 보느라 그랬죠~",
  ui_story_5051_50510101_183_dialog_content = "저기, 우리 이제 들어가야 하지 않을까...?",
  ui_story_5051_50510101_184_dialog_content = "크흠, 그, 그래.",
  ui_story_5051_50510101_185_dialog_content = "그럼 가지고 온 선물을 준비하자. 다들 선물은 잘 챙겼지?",
  ui_story_5051_50510101_186_dialog_content = "물론이죠! 전 북방의 여왕 폐하의 사절이니까요.\n유일무이한 선물을 가져 왔다구요~",
  ui_story_5051_50510101_187_dialog_content = "가져오긴 했는데...",
  ui_story_5051_50510101_188_dialog_content = "(민들레 꿀 한 병으로는 너무 성의 없어 보일까?)",
  ui_story_5051_50510101_189_dialog_content = "(올해 채취한 것 중에 가장 품질이 좋은 꿀이지만...\n이런 대저택에는 역시 안 어울리겠지.)",
  ui_story_5051_50510101_190_dialog_content = "그 꿀 정말 맛있어 보여. 홍차에 넣어보고 싶어.",
  ui_story_5051_50510101_191_dialog_content = "어쩌면 백야성 귀족들 사이에서 새로운 유행이 될지도 몰라.",
  ui_story_5051_50510101_192_dialog_content = "(미아가 내 생각을 알아챈 건가?! 자연스럽게 날 위로하고 있잖아!)",
  ui_story_5051_50510101_193_dialog_content = "소, 솔라드 씨도 마음에 들어 하셨으면 좋겠는데...\n자, 난 준비됐어. 그럼 가자!",
  ui_story_5051_50510101_194_dialog_content = "「솔라드 가문의 날」 연회에 오신 것을 환영합니다.",
  ui_story_5051_50510101_195_dialog_content = "초대장을 보여 주시기 바랍니다. 그리고 이쪽에 성함을 작성해 주십시오.",
  ui_story_5051_50510101_196_dialog_content = "초대장, 초대장... 여기요! 서명도 했어요!",
  ui_story_5051_50510101_197_dialog_content = "북방에서 오신 사절분이셨군요. 확인했습니다.",
  ui_story_5051_50510101_198_dialog_content = "그리고 안전한 연회를 위해 애완동물 관리에 유의를 부탁드리겠습니다.",
  ui_story_5051_50510101_199_dialog_content = "물론이죠~ 위스퍼는 아주 얌전하다구요. 그렇지?",
  ui_story_5051_50510101_200_dialog_content = "쉬익──",
  ui_story_5051_50510101_X200_dialog_content = "아무쪼록 오늘밤 연회를 즐겨 주시기 바랍니다.",
  ui_story_5051_50510101_X201_dialog_content = "당연히 그래야죠~ 고마워요!",
  ui_story_5051_50510101_201_dialog_content = "여기 제 초대장이요.",
  ui_story_5051_50510101_202_dialog_content = "헤븐즈 밸리의 PlayerName 님이셨군요. 존함은 익히 들었습니다.",
  ui_story_5051_50510101_203_dialog_content = "바쁘신 와중에도 「솔라드 가문의 날」 연회에 참석해 주셔서 감사합니다.\n부디 오늘 밤 연회를 마음껏 즐겨 주십시오.",
  ui_story_5051_50510101_204_dialog_content = "불편하신 점이 있으시다면 연회장 내의 시종들에게 언제든지 말씀해 주십시오.\n저희가 반드시 최고의 서비스를 제공하겠습니다.",
  ui_story_5051_50510101_205_dialog_content = "엣? 왠지 저보다 대우가 훨씬 좋은 것 같은데요?!",
  ui_story_5051_50510101_206_dialog_content = "당연하지! 난 이래 봬도 최후의 아이테르라고!",
  ui_story_5051_50510101_207_dialog_content = "(내가 이렇게 대우받는 사람이었나?!)",
  ui_story_5051_50510101_208_dialog_content = "뒤에 계신 숙녀분? 초대장을 볼 수 있을까요?",
  ui_story_5051_50510101_209_dialog_content = "!",
  ui_story_5051_50510101_210_dialog_content = "(미아는 나랑 쟈키니한테는 평범하게 이야기할 수 있지만,\n낯선 사람을 만나면 금방 숨어버려.)",
  ui_story_5051_50510101_211_dialog_content = "(특히 솔라드 가문 저택에 들어온 뒤부터는 이곳 사람들을 무서워하는 것 같아.)",
  ui_story_5051_50510101_212_dialog_content = "아, 이쪽은 제 친구예요!",
  ui_story_5051_50510101_213_dialog_content = "그러셨군요, PlayerName 님의 친구라면 초대장은 필요 없습니다.",
  ui_story_5051_50510101_214_dialog_content = "안으로 드시지요.",
  ui_story_5051_50510101_215_dialog_content = "(으음... 저런 느끼한 멘트라니, 역시 상류층 사교계의 언어란 저런 건가?)",
  ui_story_5051_50510101_216_dialog_content = "고마워, PlayerName...",
  ui_story_5051_50510101_217_dialog_content = "별일 아닌데 뭐! 내가 있으니까 무서워하지 마.",
  ui_story_5051_50510101_218_dialog_content = "쳇~ 다들 PlayerName 씨만 치켜세우고 말이에요.\n북방에서 보낸 사절의 존재감이 이렇게 희박한 거였나요?",
  ui_story_5051_50510101_219_dialog_content = "당신이 북방의 사절 쟈키니 양이군요?",
  ui_story_5051_50510101_220_dialog_content = "맞아요! 제가 바로 북방의 베들레헴 여왕 폐하의 칙명을 받은\n북방의 신임 사절 쟈키니예요!",
  ui_story_5051_50510101_221_dialog_content = "역시 그랬군요. 소문대로 아름다운 붉은 머리시군요.\n전임 사절분과 많이 닮으셨네요.",
  ui_story_5051_50510101_222_dialog_content = "전임 사절 <color=#FFB400>보아즈</color> 님을 아시나요? 후후! 그분이 바로 우리 엄마예요!",
  ui_story_5051_50510101_223_dialog_content = "그렇군요...",
  ui_story_5051_50510101_224_dialog_content = "안녕하십니까, 저는 백야성의 칼렙이라고 합니다.\n당신과 마찬가지로 솔라드 전하를 뵈러 왔습니다.",
  ui_story_5051_50510101_225_dialog_content = "당신을 모실 영광을 제게 허락해 주시겠습니까?",
  ui_story_5051_50510101_226_dialog_content = "그건...",
  ui_story_5051_50510101_227_dialog_content = "당신 어머니 보아즈 씨에 대해서도 이야기를 나눠볼 수도 있고 말이지요.",
  ui_story_5051_50510101_228_dialog_content = "정말요?! 그거 좋죠!",
  ui_story_5051_50510101_X225_dialog_content = "뭘 어떻게 모시는데요? 쉽게 좀 말씀해 주실 수 있나요...?",
  ui_story_5051_50510101_X226_dialog_content = "하하하... 한마디로 말해 성주님께서 당신의 영접을 제게 맡기셨다는 뜻입니다.",
  ui_story_5051_50510101_X227_dialog_content = "성주님이 절 맞이하려고 직접 사람을 보내셨다구요?!",
  ui_story_5051_50510101_X228_dialog_content = "헤헤~ 그럼 그렇지! 이래야 북방의 사절 체면이 서죠!",
  ui_story_5051_50510101_X229_dialog_content = "알겠어요. 그럼 같이 온 친구들한테 먼저 좀 말해둘게요!",
  ui_story_5051_50510101_229_dialog_content = "헤헤~ PlayerName 씨! 전 같이 성주님을 알현해 줄 사람이 생겼다구요.\n그럼 바이바이~",
  ui_story_5051_50510101_230_dialog_content = "어? 어디 가는 거야?\n...눈 깜짝할 사이에 가버렸잖아.",
  ui_story_5051_50510101_231_dialog_content = "쟈키니도 정말, 베들레헴 씨가 나랑 가라고 특별히 편지까지 쓰셨는데,\n도착하자마자 다른 사람을 따라가 버리고 말이야.",
  ui_story_5051_50510101_X231_dialog_content = "(휴, 됐어. 애초에 여기 온 것도 초대를 거절하기 미안해서 온 거였으니까.)",
  ui_story_5051_50510101_X232_dialog_content = "(하지만 미아는 가족과 만날 수 있다는 희망을 나한테 걸었어.\n난 그 믿음에 부응해야만 해. 지금은 그것만 생각하자.)",
  ui_story_5051_50510101_X233_dialog_content = "미아, 괜찮아?",
  ui_story_5051_50510101_232_dialog_content = "나, 난... 으음...",
  ui_story_5051_50510101_233_dialog_content = "(이런... 온통 백야성 귀족들 투성이라 미아도 슬슬 한계인 것 같네...)",
  ui_story_5051_50510101_234_dialog_content = "휴게실이라도 가서 잠깐 쉴까?",
  ui_story_5051_50510101_235_dialog_content = "하지만... 카렌, 아직 카렌을 못 봤어...",
  ui_story_5051_50510101_236_dialog_content = "괜찮아! 먼저 쉬고 있어. 내가 꼭 카렌을 데려와 줄게!",
  ui_story_5051_50510101_237_dialog_content = "PlayerName...",
  ui_story_5051_50510101_238_dialog_content = "문을 나가서 왼쪽으로 가면 응접실이 있어...",
  ui_story_5051_50510101_239_dialog_content = "-",
  ui_story_5051_50510101_240_dialog_content = "-",
  ui_story_5051_50510101_241_dialog_content = "-",
  ui_story_5051_50510101_X238_dialog_content = "거기 문이 세 개 있을 텐데, 응접실 입구에는... 흰 꽃병 두 개가 놓여 있어...",
  ui_story_5051_50510101_X239_dialog_content = "카렌은 어렸을 때 실수로 그 문틀에 긁힌 적이 있었어...",
  ui_story_5051_50510101_X240_dialog_content = "나가서 왼쪽으로... 진짜네, 여기 문이 세 개 있어.",
  ui_story_5051_50510101_X241_dialog_content = "하얀 꽃병 두 개가 놓여 있는 건... 맨 왼쪽 문이네.",
  ui_story_5051_50510101_X242_dialog_content = "찾았어. 여기가 응접실이구나!",
  ui_story_5051_50510101_X243_dialog_content = "(문틀 안쪽에 희미한 자국이 있어. 미아가 한 말이랑 똑같잖아.)",
  ui_story_5051_50510101_242_dialog_content = "(미아는 여길 아주 잘 알고 있네. 꼭 전에 와본 적 있는 것처럼 말이야.)",
  ui_story_5051_50510101_243_dialog_content = "(역시 미아는 정말로 백야성의 공주님인 걸까...?)",
  ui_story_5051_50510201_1_dialog_content = "현재 《백야의 송가》까지 식순은 순조롭게 진행되고 있습니다.",
  ui_story_5051_50510201_2_dialog_content = "이후의 식순은 가무 위주로 진행됩니다.\n모두 고위층의 재능 있는 청년들이 기예을 선보일 것입니다.",
  ui_story_5051_50510201_3_dialog_content = "많은 내빈들이 전하께서도 꼭 연회장에 오셔서 공연을 감상하시길\n간절히 바라고 있답니다.",
  ui_story_5051_50510201_4_dialog_content = "그리고 그중에는 공연 순서의 조정을 바라는 목소리도 있더군요.",
  ui_story_5051_50510201_5_dialog_content = "「아들의 독주 공연을 피날레 순서로 잡아 달라」...\n「딸의 무용 공연에는 세트장이 필요하니 공연 시간을 미뤄달라」...",
  ui_story_5051_50510201_6_dialog_content = "그러한 요구들은 제가 이미 「적절하게」 처리했습니다.\n한번 확인해 주시지요.",
  ui_story_5051_50510201_7_dialog_content = "되었다. 나는 그대를 믿는다.",
  ui_story_5051_50510201_8_dialog_content = "-",
  ui_story_5051_50510201_9_dialog_content = "...「가문의 날」을 주관하는 것은 원래 카렌이 맡아야 할 일이었지.",
  ui_story_5051_50510201_10_dialog_content = "허나 그 아이는 최근 몇 년간 계속 이날을 피하고 있다.",
  ui_story_5051_50510201_11_dialog_content = "제게 있어 오늘은 어머님의 기일일 뿐입니다.",
  ui_story_5051_50510201_12_dialog_content = "전 어머님의 임종을 곁에서 지키지 못했으니, 오늘도 성에 머물지 않겠습니다.",
  ui_story_5051_50510201_13_dialog_content = "-",
  ui_story_5051_50510201_14_dialog_content = "모녀가 함께 보낸 날들은 많지 않으나,\n제 어미를 잃은 아픔은 지금까지도 이어지고 있군.",
  ui_story_5051_50510201_15_dialog_content = "카렌 전하가 아직 어린애라고 생각하시는 건가요?",
  ui_story_5051_50510201_16_dialog_content = "아니, 정반대다. 그것은 내 젊은 날의 경망함이 빚은 과오이니 말이야.",
  ui_story_5051_50510201_17_dialog_content = "지금에 와서 본다면 자업자득이겠지.",
  ui_story_5051_50510201_18_dialog_content = "자신을 탓하지 마세요.",
  ui_story_5051_50510201_19_dialog_content = "우리는 신도 성인도 아니에요.\n전하께서는 인간의 몸으로 위대한 공적을 남기셨어요.",
  ui_story_5051_50510201_20_dialog_content = "그 과정의 공과는 지금의 백야성만 보더라도 확연히 알 수 있어요.",
  ui_story_5051_50510201_21_dialog_content = "전하께서 없으셨다면, 아무리 훌륭한 가이드라 해도\n백야성의 절경을 선보일 순 없었을 거예요.",
  ui_story_5051_50510201_22_dialog_content = "지당한 말이로군, 미즈 블랑!",
  ui_story_5051_50510201_23_dialog_content = "아니, 그 모습이라면 「미즈 로트」라고 불러야 하나?",
  ui_story_5051_50510201_24_dialog_content = "아우토 공작님, 평안하신지요.\n오늘은 성주 전하의 공적을 축하하고 기리는 연회 날입니다.",
  ui_story_5051_50510201_25_dialog_content = "저처럼 보잘것없는 조연은 마음 내키시는 대로 불러주세요.",
  ui_story_5051_50510201_26_dialog_content = "보잘것없는 조연? 하하하, 농담이 늘었군. 「나이트워치 미즈 로트」.",
  ui_story_5051_50510201_27_dialog_content = "솔라드 영주, 인사가 늦었소.\n옛이야기를 나누는 데 방해가 된 것은 아닌지 모르겠군.",
  ui_story_5051_50510201_28_dialog_content = "연회 날 번잡한 예의 따위는 신경 쓰지 않아도 된다.\n마음껏 즐기면 되는 것이다.",
  ui_story_5051_50510201_29_dialog_content = "그럴 수야 없지 않은가.\n오늘의 의미는 백야성을 위한 성주의 위대한 공헌을 기리는 데 있으니 말이야.",
  ui_story_5051_50510201_30_dialog_content = "그저 성주 곁에 있는 이들이 그 점을 이해하지 못하는 점이 애석할 따름이군.",
  ui_story_5051_50510201_31_dialog_content = "이른바 절대자의 외로움이란 말인가.",
  ui_story_5051_50510201_32_dialog_content = "아우토 공작도 마찬가지 아니던가.",
  ui_story_5051_50510201_33_dialog_content = "오랜 세월 트로이 가문과 원로원을 위해 많은 「희생」을 치르지 않았나.",
  ui_story_5051_50510201_34_dialog_content = "성주께 비할 바는 아니지.",
  ui_story_5051_50510201_35_dialog_content = "참, 여흥이 끝나고 나면 아들놈이 무대에 올라 축사를 하는데,\n성주께서도 자리를 빛내 준다면 좋겠군.",
  ui_story_5051_50510201_36_dialog_content = "그것참 안타깝게 되었네. 조금 뒤에 귀빈과 접견이 예정되어 있어서 말이야.",
  ui_story_5051_50510201_37_dialog_content = "그대의 양자는 재능이 출중하니, 분명히 다른 손님들이 그 「장기 자랑」에 박수를 보낼 것이네.",
  ui_story_5051_50510201_38_dialog_content = "나 하나 빠지는 정도는 괜찮겠지.",
  ui_story_5051_50510201_39_dialog_content = "전하, 하인의 보고를 받았습니다. 귀빈이 연회장에 도착하셨다고 합니다.",
  ui_story_5051_50510201_40_dialog_content = "말을 꺼내기가 무섭게 오다니 참으로 공교롭지 않은가.\n그럼 연회를 마음껏 즐겨주게, 아우토 공작.",
  ui_story_5051_50510201_41_dialog_content = "알겠네.",
  ui_story_5051_50510201_42_dialog_content = "...그러니까 드래곤은 아주 신기한 생물이라구요~",
  ui_story_5051_50510201_43_dialog_content = "작은 건 손바닥 크기인데, 큰 건 콜로서스만하다니까요!",
  ui_story_5051_50510201_44_dialog_content = "그러고 보니까 드래곤이랑 콜로서스는 좀 비슷한데요.\n설마 무슨 관계라도 있는 걸까요?",
  ui_story_5051_50510201_45_dialog_content = "크흠, 쟈키니 양.",
  ui_story_5051_50510201_46_dialog_content = "네? 왜 그러세요?",
  ui_story_5051_50510201_47_dialog_content = "전임 사절이었던 보아즈 씨는 위대한 점술사였다고 들었습니다.",
  ui_story_5051_50510201_48_dialog_content = "전 북방의 점술에 관심이 많습니다만, 당신도 그쪽 지식을 가지고 있습니까?",
  ui_story_5051_50510201_49_dialog_content = "당연하죠~ 알기만 하는 게 아니라 아주 프로페셔널한...",
  ui_story_5051_50510201_50_dialog_content = "으... 아무튼 저도 점술사예요.",
  ui_story_5051_50510201_51_dialog_content = "북방의 여왕 폐하께서 특별히 절 사절로 보내신 건\n「<color=#FFB400>영원한 기억의 수정</color>」에 거울 호수의 물을 붓기 위해서예요.",
  ui_story_5051_50510201_52_dialog_content = "「영원한 기억의 수정」에 대해서는 저도 들어본 적 있습니다.",
  ui_story_5051_50510201_53_dialog_content = "그런데 왜 그 수정에 거울 호수의 물을 부어야 하죠?",
  ui_story_5051_50510201_54_dialog_content = "그 수정은 루미나 보존에 쓰는 게 아니었습니까...?",
  ui_story_5051_50510201_55_dialog_content = "안녕하세요, 쟈키니 양. 드디어 찾았네요.",
  ui_story_5051_50510201_56_dialog_content = "아, 안녕하세요!",
  ui_story_5051_50510201_57_dialog_content = "<size=30>칼렙 씨, 저분은 누군가요?</size>",
  ui_story_5051_50510201_58_dialog_content = "오랜만입니다, 미즈 블랑.",
  ui_story_5051_50510201_59_dialog_content = "오랜만이에요. 「가문의 날」 연회에서 뵙는 건 처음이네요.\n참석해 주셔서 정말 감사해요.",
  ui_story_5051_50510201_60_dialog_content = "이쪽은 미즈 블랑입니다. 성주님의 조수라고 알고 계시면 됩니다.",
  ui_story_5051_50510201_61_dialog_content = "그렇군요...",
  ui_story_5051_50510201_62_dialog_content = "쟈키니 양, 전하께서는 이미 응접실에서 기다리고 계십니다. 절 따라오세요.",
  ui_story_5051_50510201_63_dialog_content = "아, 안녕하세요!\n전 여왕 폐하께서 새로 임명하신 북방의 사절 쟈키니라고 해요!",
  ui_story_5051_50510201_64_dialog_content = "지난번 북방의 사절이 백야성을 방문한 건 12년 전이었죠.",
  ui_story_5051_50510201_65_dialog_content = "이번에 전 여왕님의 명으로 「영원한 기억의 수정」에 <color=#FFB400>거울 호수의 물</color>을 채우러 왔어요.",
  ui_story_5051_50510201_66_dialog_content = "방문에 감사하지, 북방의 사절이여.",
  ui_story_5051_50510201_67_dialog_content = "그 건은 이미 여왕의 편지를 통해 알고 있었다.\n사명을 위해 먼 길을 오느라 수고가 많았다.",
  ui_story_5051_50510201_68_dialog_content = "천만에요! 이게 제 일이니까요!",
  ui_story_5051_50510201_69_dialog_content = "미즈 로트, 「영원한 기억의 수정」을 가져오도록.",
  ui_story_5051_50510201_70_dialog_content = "알겠습니다.",
  ui_story_5051_50510201_71_dialog_content = "......",
  ui_story_5051_50510201_72_dialog_content = "내가 미즈 로트에게 내린 명은 북방의 사절을 불러오라는 것이었을 터인데.",
  ui_story_5051_50510201_73_dialog_content = "설마 연회 자리에서 북방의 사절과 친구라도 된 것인가? 칼렙.",
  ui_story_5051_50510201_74_dialog_content = "정말 죄송합니다, 전하.",
  ui_story_5051_50510201_75_dialog_content = "전 그저 <color=#FFB400>누이의 유품</color>에 대한 일이라면,\n유족인 제가 피할 이유는 없다고 생각했을 뿐입니다.",
  ui_story_5051_50510201_76_dialog_content = "전하께서 제 존재를 그렇게까지 꺼리실 줄은 몰랐습니다만.",
  ui_story_5051_50510201_77_dialog_content = "(누이의 유품? 유족? 꺼려? ...뭐가 어떻게 된 거야?!\n왜 이런 어색한 분위기냐구!)",
  ui_story_5051_50510201_78_dialog_content = "(PlayerName 씨, 미아 씨... 제가 잘못했어요...)",
  ui_story_5051_50510201_X78_dialog_content = "(엄마 이야기에 정신이 팔려서 당신들이랑 떨어지는 게 아니었는데...\n누가 여기서 저 좀 꺼내줘요!)",
  ui_story_5051_50510201_79_dialog_content = "전하, 칼렙 씨는 제가 데려왔습니다.",
  ui_story_5051_50510201_80_dialog_content = "전하를 뵙고 싶다고 하시더군요.\n전하의 일정이 이미 잡혀 있는 걸 감안해서 제가 동행을 권유했습니다.",
  ui_story_5051_50510201_81_dialog_content = "칼렙 씨는 가족으로서 전하의 일정에 있어 우선시해야 할 분이라고 생각했습니다.",
  ui_story_5051_50510201_82_dialog_content = "미즈 로트... 그대는 영리함이 과한 면이 있단 말이지.",
  ui_story_5051_50510201_83_dialog_content = "칭찬 감사합니다.",
  ui_story_5051_50510201_84_dialog_content = "「영원한 기억의 수정」은 여기 있습니다. 그럼 잘 부탁드립니다.",
  ui_story_5051_50510201_85_dialog_content = "알겠어요. 맡겨주세요!",
  ui_story_5051_50510201_86_dialog_content = "(사, 살았다! 고마워요, 블랑 씨~)",
  ui_story_5051_50510201_87_dialog_content = "칼렙 씨, 이건 어떤 귀빈분이 가져오신 움브라톤의 명주입니다.\n한 잔 받으세요.",
  ui_story_5051_50510201_88_dialog_content = "마음을 달래고 진정시키는 작용이 있다고 하더군요. 음미해 주시지요.",
  ui_story_5051_50510201_89_dialog_content = "...고맙습니다.",
  ui_story_5051_50510201_90_dialog_content = "칼렙, 그대가 이번에 온 것은 설마 「영원한 기억의 수정」 때문인가?",
  ui_story_5051_50510201_91_dialog_content = "이 수정은 북방의 여왕이 우리 부부에게 보낸 <color=#FFB400>기록장치</color>다.",
  ui_story_5051_50510201_92_dialog_content = "12년 전, 확실히 내 아내, 즉 그대의 누이가 직접 이 수정을 가동했었지.",
  ui_story_5051_50510201_93_dialog_content = "허나 안에 보존되어 있는 것은 당시의 일부 기억에 불과하다.",
  ui_story_5051_50510201_94_dialog_content = "-",
  ui_story_5051_50510201_95_dialog_content = "설령 여왕이 수정을 돌려달라고 한들, 나는 전혀 원망하지 않을 것이다.",
  ui_story_5051_50510201_96_dialog_content = "...전하에게 있어 아내와 딸에 대한 추억은 그렇게나 무가치한 겁니까?",
  ui_story_5051_50510201_97_dialog_content = "여, 여왕 폐하도 수정을 돌려달라고 하신 적은 없어요!",
  ui_story_5051_50510201_98_dialog_content = "안의 세계는 이미 이걸 가동한 사람의 루미나에 의해서 움직이고 있으니까요.\n여왕 폐하께서 다시 가져가셔 봤자 아무 쓸모도 없어요!",
  ui_story_5051_50510201_99_dialog_content = "안의 세계라니요?",
  ui_story_5051_50510201_100_dialog_content = "네, 「영원한 기억의 수정」은 그냥 단순한 기록장치가 아니에요~",
  ui_story_5051_50510201_101_dialog_content = "이 안에는 <color=#FFB400>진짜 세계</color>가 저장되어 있거든요!",
  ui_story_5051_50510201_102_dialog_content = "그게 대체 무슨 말씀입니까?",
  ui_story_5051_50510201_103_dialog_content = "으흠~ 역시 칼렙 씨는 이 수정에 대해 잘 모르시는 모양이네요.",
  ui_story_5051_50510201_104_dialog_content = "그럼 제가 사용법을 알려드릴게요!",
  ui_story_5051_50510201_105_dialog_content = "먼저 「영원한 기억의 수정」에는 거울 호수의 물이 충분히 들어 있어야 해요.",
  ui_story_5051_50510201_106_dialog_content = "그리고 사용자가 자신의 루미나를 주입하면 수정을 가동할 수 있어요.",
  ui_story_5051_50510201_107_dialog_content = "그러면 수정이 자동으로 일정한 범위 안에서 <color=#FFB400>하루 동안 있었던 모든 일</color>을\n자동으로 기록해 주는 거예요.",
  ui_story_5051_50510201_108_dialog_content = "그 기록은 모두 수정 속에 보존되고, 기록 속 가상의 세계는 복원을 통해 계속 재생할 수 있어요.",
  ui_story_5051_50510201_109_dialog_content = "처음 가동한 사람이 다시 루미나를 주입하면 수정 속으로 들어갈 수 있고,\n그렇게 복원된 세계를 직접 체험할 수 있는 거예요!",
  ui_story_5051_50510201_110_dialog_content = "그게 바로 「영원한 기억의 수정」의 비밀이랍니다~",
  ui_story_5051_50510201_111_dialog_content = "다만 「영원한 기억의 수정」은 아주 취약해요...",
  ui_story_5051_50510201_112_dialog_content = "안에 들어간 사람은 기본적으로 모습이 보이지 않게 되는데요.\n중요한 건 안의 사람이나 물건과 접촉하면 안 된다는 거예요.",
  ui_story_5051_50510201_113_dialog_content = "<size=42>안 그랬다간 정해진 과거를 바꿔버려서...\n상상을 초월하는 재난을 초래할 수 있거든요!</size>",
  ui_story_5051_50510201_114_dialog_content = "그게 바로 북방의 불가사의한 비술이었군요...",
  ui_story_5051_50510201_115_dialog_content = "<size=30>그렇게 복잡할 줄이야...</size>",
  ui_story_5051_50510201_116_dialog_content = "휴~ 다 됐어요. 거울 호수의 물을 채웠어요!",
  ui_story_5051_50510201_117_dialog_content = "자, 받으세요, 성주님.",
  ui_story_5051_50510201_118_dialog_content = "이제 언제든지 가동할 수 있을 거예요~",
  ui_story_5051_50510201_119_dialog_content = "수고가 많았네, 북방의 사절이여.",
  ui_story_5051_50510201_120_dialog_content = "...허나 애석하게도 수정을 가동한 이는 이미 세상을 떠났네.",
  ui_story_5051_50510201_121_dialog_content = "-",
  ui_story_5051_50510201_122_dialog_content = "-",
  ui_story_5051_50510201_123_dialog_content = "아마 그것을 다시 열 수 있는 이는 없을 것이다.",
  ui_story_5051_50510201_124_dialog_content = "아...",
  ui_story_5051_50510201_125_dialog_content = "괘, 괜찮아요! 북방의 점술사인 제가 있잖아요!\n분명히 다른 방법을 찾을 수 있을 거예요!",
  ui_story_5051_50510201_126_dialog_content = "어디 보자... 사용법과 주문은~",
  ui_story_5051_50510201_127_dialog_content = "......",
  ui_story_5051_50510201_128_dialog_content = "어디 보자... 사용법과 주문은...",
  ui_story_5051_50510201_129_dialog_content = "조슈아, 「영원한 기억의 수정」 사용법은 함께 배우자고 약속했잖아?",
  ui_story_5051_50510201_130_dialog_content = "그대가 배움을 좋아하는 건 알지만, 늘 이렇게 앞서가 버리면 나도 외롭다고.",
  ui_story_5051_50510201_131_dialog_content = "어머, 내가 당신을 외롭게 만들 때도 있는 거였군요.",
  ui_story_5051_50510201_132_dialog_content = "외로움은 항상 내 몫인 줄 알았는데 말이에요.",
  ui_story_5051_50510201_133_dialog_content = "사과할게. 정무에 바빠서 그대와 아이들에게 소홀한 점은 늘 미안하게 생각해.",
  ui_story_5051_50510201_134_dialog_content = "후훗, 농담이었어요~",
  ui_story_5051_50510201_135_dialog_content = "당신이 바쁜 덕에 사람들이 이렇게 평화로운 나날을 보내고,\n다양한 감정을 느낄 수 있는 거니까요.",
  ui_story_5051_50510201_136_dialog_content = "행복, 즐거움, 기쁨... 그리고 외로움도 말이죠.",
  ui_story_5051_50510201_137_dialog_content = "하지만 이젠 북방의 여왕이 준 선물이 있잖아요.",
  ui_story_5051_50510201_138_dialog_content = "외로울 땐 수정 속 세계로 들어가기만 하면 당신을 만날 수 있는걸요.",
  ui_story_5051_50510201_139_dialog_content = "조슈아...",
  ui_story_5051_50510201_140_dialog_content = "그러니까 수정은 내가 가동할게요. 괜찮죠?",
  ui_story_5051_50510201_141_dialog_content = "물론, 그대가 즐거울 수만 있다면야.",
  ui_story_5051_50510201_142_dialog_content = "그나저나 「영원한 기억의 수정」엔 어느 하루를 기록할 생각이지?",
  ui_story_5051_50510201_143_dialog_content = "<color=#FFB400>베로니카</color>의 생일? 카렌의 연주회? 아니면...",
  ui_story_5051_50510201_144_dialog_content = "지금은 비밀이에요~",
  ui_story_5051_50510201_145_dialog_content = "부탁할게, 그냥 말해줘. 그런 중요한 날에 내 흑역사를 또 만들고 싶진 않아.",
  ui_story_5051_50510201_146_dialog_content = "어머, 우리 위대하신 성주님도 흑역사를 만드실 때가 있나요?",
  ui_story_5051_50510201_147_dialog_content = "...전에 실수로 카렌의 장난감을 밟아 부쉈을 때라거나 말이지.",
  ui_story_5051_50510201_148_dialog_content = "그땐 카렌이 아무 반응도 없어서 마음에 두지 않았는데,\n나중에 방에 숨어서 한참 울었을 줄은 몰랐어...",
  ui_story_5051_50510201_149_dialog_content = "아, 그랬죠. 그땐 당신이 새 장난감을 안고 무서운 표정으로\n방 앞에서 서성거리느라 하인들이 잔뜩 겁먹었었잖아요.",
  ui_story_5051_50510201_150_dialog_content = "그리고 또 있나요?",
  ui_story_5051_50510201_151_dialog_content = "...베로니카가 준 장미 화환을 응접실에 두고 온 적도 있었고.",
  ui_story_5051_50510201_152_dialog_content = "그때는 내빈 접견에 바빴을 뿐인데, 그 아이는 내가 선물이\n마음에 들지 않아서 버렸다고 오해해 버렸었지...",
  ui_story_5051_50510201_153_dialog_content = "당신은 그 뒤에 명을 내려서 장미꽃을 잔뜩 심었죠.",
  ui_story_5051_50510201_154_dialog_content = "하지만 그 후로 그 아이는 훈련에 열중하기 시작해서,\n다시는 화환을 만들지 않았지만요...",
  ui_story_5051_50510201_155_dialog_content = "휴...",
  ui_story_5051_50510201_156_dialog_content = "내 사랑 다니엘, 그런 건 흑역사가 아니에요.",
  ui_story_5051_50510201_157_dialog_content = "이 세상은 너무나도 복잡하고, 우리가 직접 하거나 볼 수 있는 건 한계가 있어요.",
  ui_story_5051_50510201_158_dialog_content = "그래서 난 「영원한 기억의 수정」이 아주 좋은 기회라고 생각해요...\n우리의 모든 걸 남김없이 기록할 기회 말이에요.",
  ui_story_5051_50510201_159_dialog_content = "추억은 언제나 단편적이지만, 진실된 우리의 모습은\n이 수정 안에 영원히 보존될 거예요.",
  ui_story_5051_50510201_160_dialog_content = "좋거나 나쁜 일도, 옳거나 그른 일도 말이죠...\n언젠가 우리와 아이들이 헤매고 망설이고 있을 때──",
  ui_story_5051_50510201_161_dialog_content = "수정 속의 세계에서 분명히 <color=#FFB400>진실한 답</color>을 찾을 수 있을 거예요.",
  ui_story_5051_50510201_162_dialog_content = "<color=#e8d9bb>딸그락!</color>",
  ui_story_5051_50510201_163_dialog_content = "......",
  ui_story_5051_50510201_164_dialog_content = "숨어있는 자는 속히 나와라.",
  ui_story_5051_50510201_165_dialog_content = "아, 저, 저예요! PlayerName입니다! 죄송해요, 아하하...",
  ui_story_5051_50510201_166_dialog_content = "그러니까 정리하자면...",
  ui_story_5051_50510201_167_dialog_content = "당신은 전하께 선물을 드리러 왔다가 본의 아니게 응접실로 들어왔고...",
  ui_story_5051_50510201_168_dialog_content = "갑자기 전하와 사람들이 들어오자 무의식적으로 숨어버려서,\n인사할 기회를 놓치고 말았다는 거군요.",
  ui_story_5051_50510201_169_dialog_content = "그래서 커튼 뒤에 숨어서 지금까지 계속 엿듣고 있었던 거네요.",
  ui_story_5051_50510201_170_dialog_content = "제 말이 맞나요?",
  ui_story_5051_50510201_171_dialog_content = "네, 맞아요. 죄송해요...",
  ui_story_5051_50510201_172_dialog_content = "(정확히는 미아가 무의식적으로 숨어서 나도 같이 숨은 거지만...)",
  ui_story_5051_50510201_173_dialog_content = "(아직 혼란스러워하는 미아를 갑자기 솔라드 씨랑\n만나게 하는 건 확실히 좀 성급한 것 같아.)",
  ui_story_5051_50510201_174_dialog_content = "젊은이여, 우선 그대의 호의에 감사하지.",
  ui_story_5051_50510201_175_dialog_content = "그러나 타인의 말을 엿듣는 것은 떳떳한 자가 할 소행이 아니다.",
  ui_story_5051_50510201_176_dialog_content = "앞으로는 이러한 일이 없도록 하라.",
  ui_story_5051_50510201_177_dialog_content = "네, 감사합니다...",
  ui_story_5051_50510201_178_dialog_content = "-",
  ui_story_5051_50510201_179_dialog_content = "-",
  ui_story_5051_50510201_180_dialog_content = "-",
  ui_story_5051_50510201_X177_dialog_content = "그럼 한 가지만 더 물어볼게요.",
  ui_story_5051_50510201_X178_dialog_content = "식탁보 밑에 숨어 있는 생쥐는 당신 친구인가요?",
  ui_story_5051_50510201_X179_dialog_content = "만약 아니라면 제가 쫓아낼 테니까요.",
  ui_story_5051_50510201_181_dialog_content = "으아아앗! 치, 친구예요!",
  ui_story_5051_50510201_182_dialog_content = "밖으로 나와도 돼, 미아. 다들 좋은 사람들이니까. 무서워할 거 없어.",
  ui_story_5051_50510201_183_dialog_content = "자, 잠깐만... PlayerName... 내 베일이 안 보여...",
  ui_story_5051_50510201_184_dialog_content = "백야성 귀족? 잠깐, 그 얼굴...",
  ui_story_5051_50510201_185_dialog_content = "어머...",
  ui_story_5051_50510201_186_dialog_content = "......",
  ui_story_5051_50510201_187_dialog_content = "미즈 로트, 이 또한 그대가 준비한 「깜짝 선물」인가?",
  ui_story_5051_50510201_188_dialog_content = "...되었네, 그것보다 우선 내 일정부터 조정하도록.",
  ui_story_5051_50510201_189_dialog_content = "정말 죄송합니다. 제가 미처 살피지 못했습니다.\n우선 향후 일정을 모두 취소하고 오겠습니다.",
  ui_story_5051_50510201_190_dialog_content = "-",
  ui_story_5051_50510201_191_dialog_content = "이거랑... 이거... 그리고 이렇게 합치면... 됐어요!",
  ui_story_5051_50510201_192_dialog_content = "찾았어요! 주문을 알아냈어요!",
  ui_story_5051_50510201_193_dialog_content = "북방의 사절이여, 이제 되었네.\n그대와 PlayerName 두 사람은 가서 계속 연회를 즐기도록 하게.",
  ui_story_5051_50510201_194_dialog_content = "지금부터는 우리 세 사람이 따로 나눌 이야기가 있으니...",
  ui_story_5051_50510201_195_dialog_content = "크, 크흠... 쟈키니, 그럼 일단 나갈까... 쟈키니?",
  ui_story_5051_50510201_196_dialog_content = "「아드 프라이테리툼~ 아드 프라이테리툼~ 아드 프라이테리툼!」",
  ui_story_5051_50510201_197_dialog_content = "우리를 저 지난날의 시간으로 인도하라!",
  ui_story_5051_50510201_198_dialog_content = "<size=45>「아브라하다브라!」</size>",
  ui_story_5051_50510201_199_dialog_content = "무슨...?!",
  ui_story_5051_50510201_200_dialog_content = "<size=45>이, 이게 무슨 일이야?!</size>",
  ui_story_5051_50510201_201_dialog_content = "PlayerName... 도와줘...",
  ui_story_5051_50510201_202_dialog_content = "미아! 내 손 잡아!",
  ui_story_5051_50510201_203_dialog_content = "응...!",
  ui_story_5051_50510201_204_dialog_content = "으윽... 으음...?",
  ui_story_5051_50510201_205_dialog_content = "여긴 어디지...?",
  ui_story_5051_50510201_206_dialog_content = "다, 다행이야... 드디어 깨어났구나!",
  ui_story_5051_50510201_207_dialog_content = "미아, 여기가 어디야?",
  ui_story_5051_50510201_208_dialog_content = "나도 모르겠어...! 그것보다 빨리 도망가자... 암귀가 왔어!",
  ui_story_5051_50510201_209_dialog_content = "──!!",
  ui_story_5051_50510201_210_dialog_content = "암귀?!",
  ui_story_5051_50510201_211_dialog_content = "미아, 날 잡아! 이쪽으로 뛰어!",
  ui_story_5051_50510201_212_dialog_content = "PlayerName, 그, 그쪽에도 있어...",
  ui_story_5051_50510201_213_dialog_content = "──!!",
  ui_story_5051_50510201_214_dialog_content = "포위당했잖아?!",
  ui_story_5051_50510201_215_dialog_content = "바, 바바 야가, 바바 야가! 도와줘!",
  ui_story_5051_50510201_216_dialog_content = "제발... 왜 대답해 주지 않는 거야...?",
  ui_story_5051_50510201_217_dialog_content = "으윽... 미아, 절대 내 뒤에서 떨어지지 마!",
  ui_story_5051_50510201_218_dialog_content = "빌어먹을 암귀 자식들! 덤벼!",
  ui_story_5051_50510201_219_dialog_content = "<size=45>크오오!</size>",
  ui_story_5051_50510201_220_dialog_content = "안 돼...",
  ui_story_5051_50510201_221_dialog_content = "하지 마...",
  ui_story_5051_50510201_222_dialog_content = "<size=45>PlayerName한테 손대지 마!!!</size>",
  ui_story_5051_50510201_223_dialog_content = "크오오?!",
  ui_story_5051_50510201_224_dialog_content = "미, 미아...?",
  ui_story_5051_50510201_225_dialog_content = "하, 하아...",
  ui_story_5051_50510201_226_dialog_content = "이...이건... 루미나틱스...?",
  ui_story_5051_50510201_227_dialog_content = "미아, 너 루미나틱스를 쓸 수 있었구나?!",
  ui_story_5051_50510201_228_dialog_content = "전에는 쓸 수 있었어... 하지만 정말 오랫동안 성공한 적이 없었는데...",
  ui_story_5051_50510201_229_dialog_content = "──!!",
  ui_story_5051_50510201_230_dialog_content = "또 있어?! 도대체 얼마나 더 있는 거야?!",
  ui_story_5051_50510201_231_dialog_content = "아직 싸울 수 있겠어?",
  ui_story_5051_50510201_232_dialog_content = "모, 모르겠어...",
  ui_story_5051_50510201_233_dialog_content = "하지만... 싸우지 않으면 PlayerName 네가 위험해질 거야...",
  ui_story_5051_50510201_234_dialog_content = "난 PlayerName 널 지키고 싶어!",
  ui_story_5051_50510201_235_dialog_content = "미아, 너라면 할 수 있을 거야!",
  ui_story_5051_50510201_236_dialog_content = "네가 루미나틱스를 쓸 수 있다면, 내가 네 힘을 이끌어 줄게!",
  ui_story_5051_50510201_237_dialog_content = "날 믿어줘. 그리고 너 자신도 믿어!",
  ui_story_5051_50510201_238_dialog_content = "널... 그리고 날...",
  ui_story_5051_50510201_239_dialog_content = "-",
  ui_story_5051_50510301_1_dialog_content = "미아, 괜찮아?",
  ui_story_5051_50510301_2_dialog_content = "응... 아직 조금 무섭긴 하지만...",
  ui_story_5051_50510301_3_dialog_content = "그래도 조금 자신감이 생긴 것 같아!",
  ui_story_5051_50510301_4_dialog_content = "PlayerName, 방금 싸우느라 다치진 않았어?",
  ui_story_5051_50510301_5_dialog_content = "전혀 안 다쳤어. 걱정 안 해도 돼!",
  ui_story_5051_50510301_6_dialog_content = "그나저나 미아 너 정말 대단하네... 혼자서 저 많은 암귀를 쓰러트렸잖아.",
  ui_story_5051_50510301_7_dialog_content = "그, 그래? 난 전부 네 덕분인 것 같은데...",
  ui_story_5051_50510301_8_dialog_content = "아이테르의 힘은 정말 신기하네...",
  ui_story_5051_50510301_9_dialog_content = "그러고 보니까 정신을 차린 뒤로 다른 사람들이 전혀 감응이 안 돼.",
  ui_story_5051_50510301_10_dialog_content = "다들 어디 간 거지? 그래서 여긴 도대체 어디인 거야?!",
  ui_story_5051_50510301_11_dialog_content = "저기 좀 봐. 저 멀리 <color=#FFB400>백야성</color>이 보여.",
  ui_story_5051_50510301_12_dialog_content = "그럼 여긴 <color=#FFB400>백야성 교외</color>라는 거잖아?",
  ui_story_5051_50510301_13_dialog_content = "우리가 왜 갑자기 이런 곳에...",
  ui_story_5051_50510301_14_dialog_content = "설마... 여기가 바로 「<color=#FFB400>영원한 기억의 수정</color>」 속 세계인 걸까?",
  ui_story_5051_50510301_15_dialog_content = "그럴 수도 있겠네!",
  ui_story_5051_50510301_16_dialog_content = "「아드 프라이테리툼~ 아드 프라이테리툼~ 아드 프라이테리툼!」",
  ui_story_5051_50510301_17_dialog_content = "우리를 저 지난날의 시간으로 인도하라!",
  ui_story_5051_50510301_18_dialog_content = "「아브라하다브라!」",
  ui_story_5051_50510301_19_dialog_content = "생각났어... 쟈키니... 이제 보니 정말 대단한 점술사였구나.",
  ui_story_5051_50510301_20_dialog_content = "다만 너무 조급한 게 문제네...",
  ui_story_5051_50510301_21_dialog_content = "그러게...",
  ui_story_5051_50510301_22_dialog_content = "그리고 쟈키니가 아까 그런 말을 했어.",
  ui_story_5051_50510301_23_dialog_content = "안에 들어간 사람은 기본적으로 모습이 보이지 않게 되고,\n안의 사람이나 물건과 접촉하면 안 된다고 말이야.",
  ui_story_5051_50510301_24_dialog_content = "안 그랬다간 정해진 과거를 바꿔버려서...\n상상을 초월하는 재난을 초래할 수 있다고 했어.",
  ui_story_5051_50510301_25_dialog_content = "하지만 아까 암귀들은 우릴 봤잖아.",
  ui_story_5051_50510301_26_dialog_content = "어떻게 된 거지...",
  ui_story_5051_50510301_27_dialog_content = "<size=45>으아아악!</size>",
  ui_story_5051_50510301_28_dialog_content = "비, 비명 소리야!",
  ui_story_5051_50510301_29_dialog_content = "저건...",
  ui_story_5051_50510301_30_dialog_content = "대장님! 암귀의 수가 너무 많습니다! 이제 더는...",
  ui_story_5051_50510301_31_dialog_content = "집중하라! 주변의 동료들이 쓰러지더라도 무기를 버려서는 안 된다!",
  ui_story_5051_50510301_32_dialog_content = "제기랄!",
  ui_story_5051_50510301_33_dialog_content = "화물차... 백야성 복장의 병사들...\n백야성 수송대가 암귀한테 습격당하고 있어!",
  ui_story_5051_50510301_34_dialog_content = "백야성 밖에 왜 이렇게 암귀가 많은 거지? 대체 무슨 일이 있었던 거야?!",
  ui_story_5051_50510301_35_dialog_content = "우, 우리가 구하러 가자!",
  ui_story_5051_50510301_36_dialog_content = "잠깐만! 쟈키니가 그랬잖아.\n우린 「영원한 기억의 수정」 속 세상에 함부로 간섭하면 안 돼.",
  ui_story_5051_50510301_37_dialog_content = "또 암귀랑 싸웠다간 더 큰일이 생길지도 몰라.",
  ui_story_5051_50510301_38_dialog_content = "하지만...",
  ui_story_5051_50510301_39_dialog_content = "「저항해라. 무덤으로 가기 전에!」",
  ui_story_5051_50510301_40_dialog_content = "──!?",
  ui_story_5051_50510301_41_dialog_content = "보스, 백야성 병사들은 별탈 없어 보입니다. 이제 철수해도 되겠는데요.",
  ui_story_5051_50510301_42_dialog_content = "하지만 솔라드 그 자식은 우리가 죽든 말든 상관도 안 하잖아요.\n우리가 왜 그 자식 졸개들을 구해줘야 하죠?",
  ui_story_5051_50510301_43_dialog_content = "기념일인데 식사나 숙소는커녕 선물만 받고 우릴 쫓아냈잖아요.",
  ui_story_5051_50510301_44_dialog_content = "진짜 치사한 자식이라니까요.",
  ui_story_5051_50510301_45_dialog_content = "눈앞의 작은 이익에 정신을 팔지 마라.\n때가 무르익으면 답은 저절로 드러나게 될 거다.",
  ui_story_5051_50510301_46_dialog_content = "<color=#FFB400>이스타반</color> 어르신...?!",
  ui_story_5051_50510301_47_dialog_content = "저 사람이 이스타반 씨라고?! 엄청 젊어 보이는데?!",
  ui_story_5051_50510301_48_dialog_content = "......?",
  ui_story_5051_50510301_49_dialog_content = "<color=#e8d9bb>쿠르르릉── 콰앙!</color>",
  ui_story_5051_50510301_50_dialog_content = "(번개? 날도 맑은데 무슨... 비가 오려나?)",
  ui_story_5051_50510301_51_dialog_content = "PlayerName! 위험해!",
  ui_story_5051_50510301_52_dialog_content = "왜 또 암귀가 있어?!",
  ui_story_5051_50510301_53_dialog_content = "대체 얼마나 더 있는 거야?!",
  ui_story_5051_50510302_1_dialog_content = "하, 하아...",
  ui_story_5051_50510302_2_dialog_content = "더는 안 오겠지...? 나... 이제 한계야...",
  ui_story_5051_50510302_3_dialog_content = "<color=#FFB400>베로니카</color> 공주, 괜찮나?",
  ui_story_5051_50510302_4_dialog_content = "베로니카 공주 전하?!",
  ui_story_5051_50510302_5_dialog_content = "공주 전하께서 왜 이런 곳에 계시는 겁니까?!",
  ui_story_5051_50510302_6_dialog_content = "아, 전 괜찮아요...",
  ui_story_5051_50510302_7_dialog_content = "그렇다면 다행이군.",
  ui_story_5051_50510302_8_dialog_content = "아까 용감하게 싸우던 모습, 평소와는 전혀 다르더군.",
  ui_story_5051_50510302_9_dialog_content = "처음엔 미처 알아보질 못했는데, 아무래도 지금까지 공주의 실력을 잘못 본 모양이군.",
  ui_story_5051_50510302_10_dialog_content = "아니에요, 그렇게 말씀하지 마세요!",
  ui_story_5051_50510302_11_dialog_content = "오늘은 그냥... 상황이 좀 특별했을 뿐인걸요.",
  ui_story_5051_50510302_12_dialog_content = "(음? 미아가 왜 날 보는 거지?)",
  ui_story_5051_50510302_13_dialog_content = "그런데 오늘처럼 중요한 날에 왜 이런 곳에 있는 거지?",
  ui_story_5051_50510302_14_dialog_content = "뭐... 내가 걱정할 일은 아니긴 하지. 다만 외출할 때는 조심하는 게 좋아.",
  ui_story_5051_50510302_15_dialog_content = "고, 고마워요.",
  ui_story_5051_50510302_16_dialog_content = "아까 성주님을 만날 때 경황이 없어서 조슈아 공작부인께 인사를 못 드렸지 뭐야.",
  ui_story_5051_50510302_17_dialog_content = "공주가 대신 안부를 좀 전해줄 수 있겠나?",
  ui_story_5051_50510302_18_dialog_content = "그리고 가능하면 성주님도 빨리 답을 주셨으면 좋겠군.",
  ui_story_5051_50510302_19_dialog_content = "알겠어요... 꼭 아버님과 어머님께 전할게요. 항상 여러모로 감사드려요.",
  ui_story_5051_50510302_20_dialog_content = "뭐, 해야 할 일을 했을 뿐이라고.",
  ui_story_5051_50510302_21_dialog_content = "(미아는 정말 공주였구나!)",
  ui_story_5051_50510302_22_dialog_content = "거기 소년.",
  ui_story_5051_50510302_23_dialog_content = "네? 저요?",
  ui_story_5051_50510302_24_dialog_content = "그래, 보아하니 넌 공주의 중요한 친구인 모양이군.",
  ui_story_5051_50510302_25_dialog_content = "아무나 백야성 공주님의 보호를 받을 수 있는 건 아니니 말이야.",
  ui_story_5051_50510302_26_dialog_content = "하지만 사내라면 뭐든지 자기 손으로 쟁취해야 하는 거다.",
  ui_story_5051_50510302_27_dialog_content = "항상 남의 뒤에만 서 있으면 곤란하다고.",
  ui_story_5051_50510302_28_dialog_content = "아, 알겠어요...",
  ui_story_5051_50510302_29_dialog_content = "저기... 혹시 우리 전에 어디서 만난 적 있나요?",
  ui_story_5051_50510302_30_dialog_content = "크하하! 그런 진부한 대사라니, 십여 년 만에 처음 듣는 것 같군.",
  ui_story_5051_50510302_31_dialog_content = "답은 「아니」다.",
  ui_story_5051_50510302_32_dialog_content = "재미있는 꼬마, 만약 날 다시 만나고 싶다면 움브라톤으로 찾아와라.",
  ui_story_5051_50510302_33_dialog_content = "거긴 곧 그림자의 제국이 될 것이다.",
  ui_story_5051_50510302_34_dialog_content = "그림자는 모든 것을 포용한다.\n다만 그 안에서 생존할 수 있을지는 네 능력에 달려 있지.",
  ui_story_5051_50510302_35_dialog_content = "모든 것을 포용하는... 확실히 그렇네요.",
  ui_story_5051_50510302_36_dialog_content = "이스타반... 아저씨의 움브라톤은 분명 멋진 곳일 거예요.",
  ui_story_5051_50510302_37_dialog_content = "공주님이 그렇게 믿어 준다니 참으로 영광이군.",
  ui_story_5051_50510302_38_dialog_content = "그럼 늦었으니 우린 이만 가 봐야겠어.",
  ui_story_5051_50510302_39_dialog_content = "베로니카 공주, 그리고 재미있는 꼬마, 다음에 또 보자고.",
  ui_story_5051_50510302_40_dialog_content = "안녕히 가세요...\n저 이스타반 씨, 내가 아는 이스타반 씨보다 훨씬 밝아 보이는데?",
  ui_story_5051_50510302_41_dialog_content = "왠지 묘한 기분이네.",
  ui_story_5051_50510302_42_dialog_content = "맞아, 내 기억 속 과거의 이스타반 어르신은 현재보다 훨씬 기세가 등등했어.",
  ui_story_5051_50510302_43_dialog_content = "나중에 여러가지 일이 많이 있었으니까... 다들 조금씩 변한 거야.",
  ui_story_5051_50510302_44_dialog_content = "미아, 그럼 네가 바로 「베로니카」 공주야?",
  ui_story_5051_50510302_45_dialog_content = "방금 이스타반 씨랑도 아주 자연스럽게 대화하고,\n평소의 수줍은 미아랑은 전혀 다른 사람 같았어.",
  ui_story_5051_50510302_46_dialog_content = "그, 그래?",
  ui_story_5051_50510302_47_dialog_content = "지금은 아직 과거가 단편적으로 떠오를 뿐이야. 아직 기억이 완전히 맞춰지진 않아.",
  ui_story_5051_50510302_48_dialog_content = "근데 왠지 젊었을 때의 이스타반 어르신을 보니까...",
  ui_story_5051_50510302_49_dialog_content = "머리보다 몸이 먼저 평소의 예의나 말투를 떠올린 것 같아.",
  ui_story_5051_50510302_50_dialog_content = "미안... 나도 뭐라고 잘 설명이 안 돼.",
  ui_story_5051_50510302_51_dialog_content = "괜찮아. 애초에 넌 네 과거를 찾으러 온 거잖아.\n중간에 이런저런 일이 많았으니까, 당장 생각이 잘 정리되지 않는 것도 당연해.",
  ui_story_5051_50510302_52_dialog_content = "저기, 미아. 그럼 네가 기억하는 베로니카 공주에 대해 말해줄 수 있을까?",
  ui_story_5051_50510302_53_dialog_content = "응, 좋아.",
  ui_story_5051_50510302_54_dialog_content = "베로니카는 백야성의 <color=#FFB400>공주</color>고, 솔라드가의 <color=#FFB400>장녀</color>야.",
  ui_story_5051_50510302_55_dialog_content = "하지만 오래전 백야성은 그 공주가 <color=#FFB400>별세</color>했다고 대외적으로 발표했어...",
  ui_story_5051_50510302_56_dialog_content = "별세? 왜?",
  ui_story_5051_50510302_57_dialog_content = "공주가 솔라드 가문의 명예를 더럽혔거든.",
  ui_story_5051_50510302_58_dialog_content = "다시 말해서 불길한 존재인 베로니카는 계속 살아갈 자격이 없다는 거야.",
  ui_story_5051_50510302_59_dialog_content = "명예? 불길해? 대체 그게 무슨 소리야...?",
  ui_story_5051_50510302_60_dialog_content = "그게 귀족이 살아가는 방식이야. 귀족에겐 체면이 무엇보다 중요하거든...",
  ui_story_5051_50510302_61_dialog_content = "PlayerName 너도 「<color=#FFB400>루미나 소환물</color>」은 알고 있지?",
  ui_story_5051_50510302_62_dialog_content = "기억 속 내겐 바바 야가 말고도 「히포카」라는 무서운 친구가 있었어.",
  ui_story_5051_50510302_63_dialog_content = "히포카는 내 소환물이야. 어렸을 때 나는 강해지려고 열심히 단련했는데...",
  ui_story_5051_50510302_64_dialog_content = "그 결과 탄생했던 게 바로 「히포카」야.",
  ui_story_5051_50510302_65_dialog_content = "하지만 다들 히포카의 외모를 싫어했어...\n머리는 말이고, 몸은 거미라서... 다들 괴물 같다고 했어.",
  ui_story_5051_50510302_66_dialog_content = "그 사람... 내 아버님은 특히 그걸 싫어하셨어.\n「히포카」가 우리 가문에 불필요한 구설을 일으킨다면서 말이야.",
  ui_story_5051_50510302_67_dialog_content = "「히포카」는 불길하다... 「히포카」는 존재해선 안 된다...\n그런 말을 계속 듣다 보니 결국 나까지 그 애를 두려워하게 됐어.",
  ui_story_5051_50510302_68_dialog_content = "「히포카」는 나 자신의 본질이 구현된 것인데도...\n난 남들의 비난 때문에 그 애를 계속 거부해 왔어.",
  ui_story_5051_50510302_69_dialog_content = "그러다 결국 루미나틱스를 사용할 수 없게 되고 말았던 거야.",
  ui_story_5051_50510302_70_dialog_content = "대신 「히포카」와 비슷한 바바 야가가 나타나서 모든 걸 이어받았어.",
  ui_story_5051_50510302_71_dialog_content = "그렇게 보면 사실 다 자업자득인걸.",
  ui_story_5051_50510302_72_dialog_content = "베로니카 공주는 정말 불쌍했구나...",
  ui_story_5051_50510302_73_dialog_content = "근데 지금 여기 사람들은 널 베로니카라고 부르잖아? 그렇다는 건...",
  ui_story_5051_50510302_74_dialog_content = "공주 전하! 방금 도와주셔서 정말 감사합니다!",
  ui_story_5051_50510302_75_dialog_content = "벼, 별일 아닌걸.",
  ui_story_5051_50510302_76_dialog_content = "다들 괜찮아?",
  ui_story_5051_50510302_77_dialog_content = "안심하십시오. 모두 약간의 부상뿐입니다.\n정비를 마쳤으니 이제 바로 출발할 수 있습니다.",
  ui_story_5051_50510302_78_dialog_content = "괜찮으시다면 성안까지 저희와 함께 가시지요.",
  ui_story_5051_50510302_79_dialog_content = "그렇구나. 정말 다행이네.",
  ui_story_5051_50510302_80_dialog_content = "저기, 잠깐만요. 올해가 몇 년도죠?",
  ui_story_5051_50510302_81_dialog_content = "년도 말입니까? <color=#FFB400>서광력 1988년</color>이지 않습니까? 왜 그러십니까?",
  ui_story_5051_50510302_82_dialog_content = "(1988년... 그럼 <color=#FFB400>12년 전</color>이야!)",
  ui_story_5051_50510302_83_dialog_content = "(12년 전이라면 헤븐즈 밸리는 이미 멸망한 뒤야.)",
  ui_story_5051_50510302_84_dialog_content = "(그럼... 「영원한 기억의 수정」 속 세계에서도 난 동족을 만날 수 없는 건가...)",
  ui_story_5051_50510302_85_dialog_content = "PlayerName, 괜찮아...?",
  ui_story_5051_50510302_86_dialog_content = "아무것도 아니야. 미아, 잠깐 이리 좀 와 줄래?",
  ui_story_5051_50510302_87_dialog_content = "왜, 왜 그래?",
  ui_story_5051_50510302_88_dialog_content = "지금까지 상황을 보면 「영원한 기억의 수정」 속 세계는\n「<color=#FFB400>12년 전 백야성</color>」이 맞을 거야.",
  ui_story_5051_50510302_89_dialog_content = "내 추측이 맞다면 응접실에 있던 다른 사람들도 여기로 들어왔을 거고 말이야.",
  ui_story_5051_50510302_90_dialog_content = "쟈키니는 우리가 수정 속 세계에 간섭하면 안 된다고 말했지만...",
  ui_story_5051_50510302_91_dialog_content = "지금은 상황이 특별해.\n우린 모습을 감출 수도 없고, 내 감응 능력으로 모두를 찾을 수도 없어.",
  ui_story_5051_50510302_92_dialog_content = "그래서 말인데, 네 공주 신분을 이용해서 빨리 모두와 합류하고,\n다 같이 여기서 나갈 방법을 찾는 게 좋겠어.",
  ui_story_5051_50510302_93_dialog_content = "......",
  ui_story_5051_50510302_94_dialog_content = "미아, 왜 그래?",
  ui_story_5051_50510302_95_dialog_content = "저기... PlayerName.",
  ui_story_5051_50510302_96_dialog_content = "그, 그럼 나... 여길 떠나기 전에 어머님을 좀 만나도 될까?",
  ui_story_5051_50510302_97_dialog_content = "아까 테이블 밑에서 들었어. 어머님은 내가 없는 사이에 돌아가셨다고...",
  ui_story_5051_50510302_98_dialog_content = "난 백야성에 돌아오면 여동생과 어머님을 만나서\n많은 이야기를 나누고 싶다고 생각했어.",
  ui_story_5051_50510302_99_dialog_content = "난 이제 어른이 됐고, 용감해졌다고... 바깥세상에서 친구도 많이 사귀었다고...",
  ui_story_5051_50510302_100_dialog_content = "그리고 어머님이 정말 보고 싶었다고... 말하고 싶었어.",
  ui_story_5051_50510302_101_dialog_content = "하지만... 이제 다시는 그럴 수 없게 됐어.",
  ui_story_5051_50510302_102_dialog_content = "...미아의 어머니라면, 솔라드 씨의 부인이잖아?",
  ui_story_5051_50510302_103_dialog_content = "그분이 우릴 도와준다면 분명 더 빨리 모두를 찾을 수 있을 거야!",
  ui_story_5051_50510302_104_dialog_content = "그럼 너희 어머니를 만나는 건 우리 모두를 위해서이기도 한 거야, 그렇지?",
  ui_story_5051_50510302_105_dialog_content = "PlayerName... 으음... 그렇게 말하니까 뭔가 영악한 느낌이야...",
  ui_story_5051_50510302_106_dialog_content = "헤헤, 가끔은 영악해지는 것도 괜찮아.",
  ui_story_5051_50510302_107_dialog_content = "이건 콜로서스의 동료들이 가르쳐 준 처세술이거든.",
  ui_story_5051_50510302_108_dialog_content = "응, 그럼 나도 본받도록 할게.",
  ui_story_5051_50510302_109_dialog_content = "그, 그렇게 말하니까 내가 왠지 미아한테 나쁜 걸 가르치는 거 같잖아...",
  ui_story_5051_50510302_110_dialog_content = "저기... 두 분, 말씀은 다 나누셨습니까? 슬슬 출발하지 않으면 늦을 겁니다.",
  ui_story_5051_50510302_111_dialog_content = "아, 미안해요! 이제 가도 돼요!",
  ui_story_5051_50510302_112_dialog_content = "근데 수송대에 무슨 급한 일이라도 있나요?",
  ui_story_5051_50510302_113_dialog_content = "아주 급한 건 아니지만, 물자를 되도록 빨리 전하는 게 좋습니다. 적어도...",
  ui_story_5051_50510302_114_dialog_content = "「<color=#FFB400>솔라드 가문의 날</color>」 축제 시작 전까지는 가야겠지요.",
  ui_story_5051_50510302_115_dialog_content = "(「솔라드 가문의 날」? 마침 딱 같은 날이잖아?)",
  ui_story_5051_50510302_116_dialog_content = "<color=#e8d9bb>쿠르릉──</color>",
  ui_story_5051_50510302_117_dialog_content = "또 천둥이네...",
  ui_story_5051_50510302_118_dialog_content = "왜 그러십니까?",
  ui_story_5051_50510302_119_dialog_content = "아무것도 아니에요. 비가 오기 전에 얼른 가죠!",
  ui_story_5051_50510302_120_dialog_content = "비? 오늘 비가 옵니까? 뭐, 아무튼 준비가 되었다면 출발합시다.",
  ui_story_5051_50510302_121_dialog_content = "<anim type=Shake><size=32>...솔......</size></anim>",
  ui_story_5051_50510302_122_dialog_content = "<anim type=Shake><size=32>......라드......</size></anim>",
  ui_story_5051_50510302_123_dialog_content = "<anim type=Shake><size=32>...............</size></anim>",
  ui_story_5051_50510402_1_dialog_content = "............",
  ui_story_5051_50510402_2_dialog_content = "휴... 어떻게 이런 곳까지 암귀가 숨어 있는 거죠?",
  ui_story_5051_50510402_3_dialog_content = "대체 언제부터 백야성이 암귀 소굴이 된 겁니까?",
  ui_story_5051_50510402_4_dialog_content = "우와~ 덕분에 살았네요!",
  ui_story_5051_50510402_5_dialog_content = "칼렙 씨가 제때 안 와줬으면 전 암귀의 저녁 식사가 될 뻔했다구요...",
  ui_story_5051_50510402_6_dialog_content = "아니지, 지금은 낮이니까 점심이겠네요.",
  ui_story_5051_50510402_7_dialog_content = "그러고 보니 그 점도 의문이군요.",
  ui_story_5051_50510402_8_dialog_content = "쟈키니 양, 아까 우리가 백야성 궁전에 있을 때는 밤이었어요.",
  ui_story_5051_50510402_9_dialog_content = "그런데 왜 갑자기 야외의 숲속에 있는 거죠? 심지어 낮이고 말입니다.",
  ui_story_5051_50510402_10_dialog_content = "설마 여긴 「영원한 기억의 수정」 속 세계인가요?",
  ui_story_5051_50510402_11_dialog_content = "맞아요! 임시로 짜 맞춘 주문이 정말 성공할 줄은 몰랐다니까요~",
  ui_story_5051_50510402_12_dialog_content = "나 설마... 천재?",
  ui_story_5051_50510402_13_dialog_content = "(아주 대단한 「천재」 나셨네...)",
  ui_story_5051_50510402_14_dialog_content = "근처 건물 양식을 보면 여긴 백야성 다운타운의 교외네요.",
  ui_story_5051_50510402_15_dialog_content = "아까 쟈키니 양이 실수로 앉아서 부숴버린 그 상자는...",
  ui_story_5051_50510402_16_dialog_content = "표식으로 보아 「솔라드 가문의 날」을 축하하기 위해 준비된 물자들 같습니다.",
  ui_story_5051_50510402_17_dialog_content = "아까는 정말 깜짝 놀랐다니까요!",
  ui_story_5051_50510402_18_dialog_content = "멀쩡해 보이던 상자가 좀 앉았다고 찌그러졌지 뭐예요!",
  ui_story_5051_50510402_19_dialog_content = "게다가 안에서 암귀가 잔뜩 튀어나오다니!",
  ui_story_5051_50510402_20_dialog_content = "대체 어떻게 된 거죠?\n설마 당신네 백야성 사람들, 암귀를 기르는 취미가 있는 건 아니죠?!",
  ui_story_5051_50510402_21_dialog_content = "안심하세요. 의사소통도 안 되는 적대 종족을 키우고 좋아할 만큼\n이 성이 썩지는 않았으니까요.",
  ui_story_5051_50510402_22_dialog_content = "「솔라드 가문의 날」에 암귀라... 역시 이곳은 12년 전 백야성이겠군요.",
  ui_story_5051_50510402_23_dialog_content = "대량의 물자가 오가는 기회를 노려 암귀를 숨어들게 만들다니,\n이 혼란의 주모자는 발상이 꽤 대담하군요.",
  ui_story_5051_50510402_24_dialog_content = "그럼... 12년 전에 암귀가 백야성에 침입했었다는 건가요?",
  ui_story_5051_50510402_25_dialog_content = "그렇습니다. 외부에서 이 웅장한 부유성을 어떻게 평가하는지는 모르겠지만...",
  ui_story_5051_50510402_26_dialog_content = "실제로는 그렇게까지 견고하지도 않습니다.",
  ui_story_5051_50510402_27_dialog_content = "저기, 칼렙 씨...",
  ui_story_5051_50510402_28_dialog_content = "혹시 저랑 마주치기 전에 여기서 다른 사람을 만났나요?",
  ui_story_5051_50510402_29_dialog_content = "아니요, 사실 정신을 차리고 얼마 안 돼서 바로 당신과 마주쳤어요.",
  ui_story_5051_50510402_30_dialog_content = "아, 아하하... 원래라면 전송된 후에도 같이 있어야 맞아요...",
  ui_story_5051_50510402_31_dialog_content = "그리고 암귀에게 발견되지도 않았어야 정상이에요.",
  ui_story_5051_50510402_32_dialog_content = "아무래도 뭔가... 작은 실수가 있었던 것 같아요~",
  ui_story_5051_50510402_33_dialog_content = "...쟈키니 양, 한 가지 묻고 싶은 게 있습니다.",
  ui_story_5051_50510402_34_dialog_content = "크, 크흠, 걱정하지 마세요! 제대로 제가 책임지고...\n여러분을 무사히 원래의 세계로 데리고 나갈 테니까요!",
  ui_story_5051_50510402_35_dialog_content = "제가 묻고 싶은 건 그 말이 아닙니다.",
  ui_story_5051_50510402_36_dialog_content = "「영원한 기억의 수정」을 가동한 자의 루미나는 이 세계에 있습니까?",
  ui_story_5051_50510402_37_dialog_content = "네! 맞아요!",
  ui_story_5051_50510402_38_dialog_content = "그럼 구체적으로 어디에 있는 거죠?",
  ui_story_5051_50510402_39_dialog_content = "구, 구체적으로... 음... 어디 보자...",
  ui_story_5051_50510402_40_dialog_content = "「영원한 기억의 수정을 가동하려면 루미나를 주입해야 한다.\n루미나는 이 세계를 움직이는 중요한 에너지원이다.」",
  ui_story_5051_50510402_41_dialog_content = "<size=30>왜 이것밖에 안 쓰여 있는 거죠?!</size>",
  ui_story_5051_50510402_42_dialog_content = "크, 크흠. 루미나가 「영원한 기억의 수정」의 중요한 에너지원이라면,\n분명히 가장 중요한 곳에 보존되어 있을 거예요!",
  ui_story_5051_50510402_43_dialog_content = "「영원한 기억의 수정」 속에서 가장 중요한 거라면 역시...",
  ui_story_5051_50510402_44_dialog_content = "이 세계에 있는 「영원한 기억의 수정」이겠네요!",
  ui_story_5051_50510402_45_dialog_content = "일리는 있군요...",
  ui_story_5051_50510402_46_dialog_content = "그럼 한 가지 더 묻죠.\n루미나가 이 세계의 에너지원이라면, 당연히 언젠가는 에너지가 소진되겠죠.",
  ui_story_5051_50510402_47_dialog_content = "12년이 지난 지금, 수정 속 루미나가 얼마나 남았는지 예상할 수 있습니까?",
  ui_story_5051_50510402_48_dialog_content = "아, 그거라면 걱정 안 해도 돼요~",
  ui_story_5051_50510402_49_dialog_content = "거울 호수의 물조차도 12년에 한 번 보충하면 될 정도니까,\n루미나는 당연히 더 오래가겠죠!",
  ui_story_5051_50510402_50_dialog_content = "다만 만약 이 세계의 질서가 흐트러지는 일이 발생한다면,\n루미나 소모가 빨라질 수 있어요.",
  ui_story_5051_50510402_51_dialog_content = "심지어 극단적인 상황에선 갑자기 루미나가 다 떨어질 수도 있는 거죠.",
  ui_story_5051_50510402_52_dialog_content = "그렇게 되면 우리 목숨도 위험하겠네요.",
  ui_story_5051_50510402_53_dialog_content = "그게 아까 말했던 「상상을 초월하는 재난」입니까?",
  ui_story_5051_50510402_54_dialog_content = "네, 그런 셈이죠. 물론 다른 예상 밖의 상황도 배제하진 말아야겠지만요...",
  ui_story_5051_50510402_55_dialog_content = "아무튼! 그러니까 얼른 다른 사람들을 찾자구요!",
  ui_story_5051_50510402_56_dialog_content = "모습을 못 감추는 상황에선 여기 오래 머무르면 안 돼요.",
  ui_story_5051_50510402_57_dialog_content = "그렇겠죠. 그럼 그 중대한 임무는 이 사태의 장본인인 쟈키니 양에게 맡기도록 하죠.",
  ui_story_5051_50510402_58_dialog_content = "저는 다른 할 일이 있어서 먼저 실례하겠습니다.",
  ui_story_5051_50510402_59_dialog_content = "에엣?! 어떻게 지금 저한테만 떠맡기고 도망갈 수가 있어요?!",
  ui_story_5051_50510402_60_dialog_content = "그리고 제가 방금 말했잖아요! 마음대로 돌아다니면 안 된다구요!\n만약 이 세계를 바꾸어 버린다면 큰일이라니까요!",
  ui_story_5051_50510402_61_dialog_content = "알고 있습니다. 규칙은 잘 지키도록 하죠.\n당신이 다른 사람들도 얌전히 있도록 잘 설득하길 바랄게요.",
  ui_story_5051_50510402_62_dialog_content = "애초부터 얼마 안 남은 루미나가 더 빨리 소모되는 건 저도 원하지 않으니까요.",
  ui_story_5051_50510402_63_dialog_content = "잠깐만요! 미리 경고하는데, 여긴 백야성이에요.\n만약 과거의 당신이랑 마주치기라도 하면 어쩌려고 그래요?!",
  ui_story_5051_50510402_64_dialog_content = "안심하세요. 당시 이날 전 성안에는 없었습니다.\n기사단과 함께 떠난 조카딸을 만나러 움브라톤에 갔었거든요.",
  ui_story_5051_50510402_65_dialog_content = "「영원한 기억의 수정」이 그런 먼 곳까지 기록할 순 없겠죠?",
  ui_story_5051_50510402_66_dialog_content = "그건 그렇긴 하지만...",
  ui_story_5051_50510402_67_dialog_content = "전 손님으로 위장해서 성안에 들어가 제가 만나야 할 사람을 만날 겁니다.\n끝나면 알아서 당신을 찾아오도록 하죠.",
  ui_story_5051_50510402_68_dialog_content = "생명의 위험을 무릅쓰고서라도 꼭 만나야 할 사람인가요?",
  ui_story_5051_50510402_69_dialog_content = "물론입니다. 지나간 과거는 결코 되돌릴 수 없으니까요.\n이렇게 잃어버린 것을 되찾을 기회를 얻는 일이 인생에 몇 번이나 있겠어요?",
  ui_story_5051_50510402_70_dialog_content = "그럼 당신은 얼른 다른 사람들을 찾아주세요. 전 이만.",
  ui_story_5051_50510402_71_dialog_content = "자, 잠깐만요! 아직 어디서 만날지도 안 정했잖아요!",
  ui_story_5051_50510402_72_dialog_content = "(...엄청 빠르네... 순식간에 사라졌어...)",
  ui_story_5051_50510402_73_dialog_content = "(정말... 분명히 품위 있고 예의 바른 사람 같았는데... 완전 속았잖아!)",
  ui_story_5051_50510402_74_dialog_content = "(중요한 순간에 저렇게 이기적이고 매정한 행동을 하다니... 어이없어!)",
  ui_story_5051_50510402_75_dialog_content = "(으으... 짜증나!)",
  ui_story_5051_50510402_76_dialog_content = "(휴... 「잃어버린 것을 되찾을 기회」라...)",
  ui_story_5051_50510402_77_dialog_content = "(나도 그럴 기회가 있을까?)",
  ui_story_5051_50510402_78_dialog_content = "(엄마는 12년 전 「영원한 기억의 수정」을 백야성 성주님께 드리고 북방으로 돌아왔어.)",
  ui_story_5051_50510402_79_dialog_content = "(아빠는 엄마를 이해하기 힘든 사람이라고 했어.\n수행을 위해서라면 가족도 내팽개치고 말 한마디 없이 산에 틀어박혀 버렸으니까.)",
  ui_story_5051_50510402_80_dialog_content = "(하지만 여왕 폐하는 엄마를 세속을 떠난 위대한 수행자라고 하셨어...\n아무래도 나... 엄마랑은 조금도 안 닮은 것 같아.)",
  ui_story_5051_50510402_81_dialog_content = "(만약 엄마가 지금 여기 있다면, 나한테 뭐라고 했을까?)",
  ui_story_5051_50510402_82_dialog_content = "(...으앗! 지금 나 혼자 뭔 생각을 하고 있는 거야?!)",
  ui_story_5051_50510402_83_dialog_content = "(쟈키니! 집중해! 지금 넌 북방의 사절이라구!)",
  ui_story_5051_50510402_84_dialog_content = "(다른 사람들이 못 미더워도 넌 반드시 믿음직한 사람이 돼야 해!\n꼭 책임지고 모두를 데리고 여기서 나가는 거야!)",
  ui_story_5051_50510402_85_dialog_content = "스읍... 후우...",
  ui_story_5051_50510402_86_dialog_content = "(좋아! 북방의 사절 쟈키니, 출발!)",
  ui_story_5051_50510501_1_dialog_content = "(솔라드 녀석이 「영원한 기억의 수정」을 숨길 만한 곳은 많지 않아...\n기껏해야 이 저택 어딘가겠지.)",
  ui_story_5051_50510501_2_dialog_content = "(그 해 가문의 날은 큰 규모로 개최됐으니까,\n경비병 대부분이 연회장 쪽을 지키고 있었을 거야.)",
  ui_story_5051_50510501_3_dialog_content = "(행사가 시작되고 나면 경비가 허술한 곳을 노려서 들어가면 돼.)",
  ui_story_5051_50510501_4_dialog_content = "(그때까진 경비병의 눈을 피해서 얌전히 기다리자.)",
  ui_story_5051_50510501_5_dialog_content = "(정원 쪽엔 아마 사람이 없겠지...)",
  ui_story_5051_50510501_6_dialog_content = "(아이리스인가... 꽃말은 「좋은 소식」, 「그리움」...)",
  ui_story_5051_50510501_7_dialog_content = "(누나는 분명히 큰딸을 위해 아이리스를 심었겠지.)",
  ui_story_5051_50510501_8_dialog_content = "...알고 있어. 이제 곧 꽃이 피는 시기가 지나가 버린다는 걸.",
  ui_story_5051_50510501_9_dialog_content = "그래도 조금만 더 버텨주면 안 될까?",
  ui_story_5051_50510501_10_dialog_content = "내 딸이 곧 돌아올 거야. 너희 모습을 꼭 보여주고 싶어.",
  ui_story_5051_50510501_11_dialog_content = "그 애는 옛날부터 꽃을 무척 좋아했거든.\n너흴 보면 분명히 미소를 되찾을 수 있을 거야.",
  ui_story_5051_50510501_12_dialog_content = "다...당신...",
  ui_story_5051_50510501_13_dialog_content = "<color=#FFB400>누나</color>...?",
  ui_story_5051_50510501_14_dialog_content = "어머.",
  ui_story_5051_50510501_15_dialog_content = "평안하신가요, 낯선 손님.",
  ui_story_5051_50510501_16_dialog_content = "이토록 아름다운 오후에 무슨 바람이 당신을 이곳으로 인도한 걸까요?",
  ui_story_5051_50510501_17_dialog_content = "으음~ 미안하지만 당돌한 질문을 하나 하고 싶네요.",
  ui_story_5051_50510501_18_dialog_content = "우리, 전에 만난 적 있나요?",
  ui_story_5051_50510501_19_dialog_content = "...아니요, 전 그저 보잘것없는 하급 귀족입니다.\n그런 영광을 누린 적은 없었습니다.",
  ui_story_5051_50510501_20_dialog_content = "처음 뵙겠습니다, 조슈아 공작부인.",
  ui_story_5051_50510501_21_dialog_content = "그런가요?",
  ui_story_5051_50510501_22_dialog_content = "하지만... 음, 그래요. 아마 제가 잘못 본 거겠죠.",
  ui_story_5051_50510501_23_dialog_content = "(누나...)",
  ui_story_5051_50510501_24_dialog_content = "(만날 사람이 있다던 건 그저 북방의 점술사를 떼놓으려던 거짓말이었는데...)",
  ui_story_5051_50510501_25_dialog_content = "(여기서 정말 만날 수 있을 줄이야...)",
  ui_story_5051_50510501_26_dialog_content = "(12년... 12년만에... 처음으로 누나와 이야기할 수 있게 되었는데...)",
  ui_story_5051_50510501_27_dialog_content = "(그저 이렇게 낯선 사람인 척이나 해야 한다니...)",
  ui_story_5051_50510501_28_dialog_content = "(안 돼. 내가 이 세계에 온 건 누나가 남긴 루미나를 되찾기 위해서야...)",
  ui_story_5051_50510501_29_dialog_content = "(간섭하거나 멈춰 서선 안 돼... 이건 그저 북방의 비술이 만들어 낸 환영일 뿐이라고.)",
  ui_story_5051_50510501_30_dialog_content = "(이 연극을 한시라도 빨리 끝내야 해...!)",
  ui_story_5051_50510501_31_dialog_content = "괜찮으신가요? 왠지 괴로워 보이네요...",
  ui_story_5051_50510501_32_dialog_content = "정말 죄송합니다.",
  ui_story_5051_50510501_33_dialog_content = "당신처럼 고귀한 분과 이야기하는 건 처음이라, 조금 당황하고 말았습니다.",
  ui_story_5051_50510501_34_dialog_content = "후훗, 거짓말.",
  ui_story_5051_50510501_35_dialog_content = "눈가가 젖어 있잖아요. 다친 건가요? 아니면 무슨 고민이라도 있나요?",
  ui_story_5051_50510501_36_dialog_content = "억지로 무리하지 않아도 돼요.",
  ui_story_5051_50510501_37_dialog_content = "......",
  ui_story_5051_50510501_38_dialog_content = "아, 아니에요!",
  ui_story_5051_50510501_39_dialog_content = "눈에 모래가 들어갔을 뿐이라구요!",
  ui_story_5051_50510501_40_dialog_content = "...아카데미의 꽉 막힌 어른들이나 바보 같은 학생들이 뭘 알아요!",
  ui_story_5051_50510501_41_dialog_content = "「칼렙은 똑똑하지만 부모님한테 교육을 못 받아서 항상 잘난척한다」니 뭐니...",
  ui_story_5051_50510501_42_dialog_content = "<size=30>부모님이 없는 게 뭐 어떻다고... 나한텐 누나만 있으면 되는데...</size>",
  ui_story_5051_50510501_43_dialog_content = "두고 보세요! 언젠간 제가 꼭 이 세상을 바꿔버릴 테니까요!",
  ui_story_5051_50510501_44_dialog_content = "그래, 누나는 널 믿어.",
  ui_story_5051_50510501_45_dialog_content = "우리 귀여운 천재는 절대 거짓말은 안 하잖니. 꺼낸 말은 항상 해내니까.",
  ui_story_5051_50510501_46_dialog_content = "누나, 정말 절 믿어주는 거예요?",
  ui_story_5051_50510501_47_dialog_content = "응, 당연하지.",
  ui_story_5051_50510501_48_dialog_content = "누나... 만약 언젠가... 모든 사람이 먹고사는 걱정을 안 해도 되게 되면...",
  ui_story_5051_50510501_49_dialog_content = "누나도 맨날 저 다니엘 녀석 일을 도울 필요도 없어지는 거죠?",
  ui_story_5051_50510501_50_dialog_content = "으음~ 만약 정말 그런 날이 온다면 정무도 분명히 줄어들겠지.\n하지만 누나는 아내로서 다니엘 곁에 있어야 해.",
  ui_story_5051_50510501_51_dialog_content = "......",
  ui_story_5051_50510501_52_dialog_content = "대신 그때가 되면 네 연구에도 함께해 줄게.\n네 학술발표회에도 전부 참석하고 말이야. 어떠니?",
  ui_story_5051_50510501_53_dialog_content = "정말요?",
  ui_story_5051_50510501_54_dialog_content = "그래, 진짜야.",
  ui_story_5051_50510501_55_dialog_content = "그럼... 전 세계 곳곳에서 학회를 열 거예요!",
  ui_story_5051_50510501_56_dialog_content = "누나는 전에 세계 각지를 여행하고 싶다고 했었잖아요.\n하지만 결혼하고 나서는 다시는 그런 말을 안 하게 됐어요.",
  ui_story_5051_50510501_57_dialog_content = "그러니까 제가 그 꿈을 실현해 줄게요.",
  ui_story_5051_50510501_58_dialog_content = "어머, 너란 아이는 정말... 또 누나를 난처하게 만드는구나.",
  ui_story_5051_50510501_59_dialog_content = "그래도 약속했잖아요. 그러니까 꼭 와 줘야 해요!",
  ui_story_5051_50510501_60_dialog_content = "그래그래~ 약속할게.",
  ui_story_5051_50510501_61_dialog_content = "...눈에... 모래가 들어갔을 뿐입니다.",
  ui_story_5051_50510501_62_dialog_content = "어머, 얼굴까지 찡그리고 억지로 참고 있잖아요.",
  ui_story_5051_50510501_63_dialog_content = "정말 제 동생이랑 똑같단 말이죠...",
  ui_story_5051_50510501_64_dialog_content = "제 동생은 또래보다 훨씬 지혜롭지만, 어떤 점은 언제나 귀여운 어린애 같거든요.",
  ui_story_5051_50510501_65_dialog_content = "항상 울 때면 눈에 모래가 들어갔다느니 하는 뻔한 거짓말을 한다니까요.",
  ui_story_5051_50510501_66_dialog_content = "...어머, 미안해요.",
  ui_story_5051_50510501_67_dialog_content = "제 동생과 닮아서 저도 모르게 제멋대로 말을 하고 말았지 뭐예요.",
  ui_story_5051_50510501_68_dialog_content = "이런 실례를 범하다니, 송구스럽네요.",
  ui_story_5051_50510501_69_dialog_content = "아닙니다, 그렇게 말씀하지 마세요...",
  ui_story_5051_50510501_70_dialog_content = "하지만 정말 신기하네요. 당신과 제 남동생은 나이가 한참 차이가 나는데...",
  ui_story_5051_50510501_71_dialog_content = "당신에게서 그 아이의 모습이 보인단 말이죠...",
  ui_story_5051_50510501_72_dialog_content = "사과의 뜻으로 오늘 연회의 귀빈석을 마련해 드릴게요.",
  ui_story_5051_50510501_73_dialog_content = "연회에 불편한 점이 있다면 누구에게든지 제 이름을 말하면 돼요.",
  ui_story_5051_50510501_74_dialog_content = "그리고 곤란한 일이 있다면 뭐든 제게 말해도 좋아요.",
  ui_story_5051_50510501_75_dialog_content = "그러니까 혼자 억지로 애쓸 필요는 없어요.",
  ui_story_5051_50510501_76_dialog_content = "호의에 감사드립니다. 하지만 전 그저 일 때문에 지나던 길이었습니다.\n축제에 참가하러 온 건 아닙니다.",
  ui_story_5051_50510501_77_dialog_content = "그저 이 꽃을 보고 있으니 그리운 마음이 들어서...\n저도 모르게 걸음을 멈추고 말았네요. 실례가 많았습니다.",
  ui_story_5051_50510501_78_dialog_content = "그럼 저는 먼저 가보겠습니다... 부디... 몸조심하시길.",
  ui_story_5051_50510501_79_dialog_content = "어머, 그렇게 서두를 것까진...",
  ui_story_5051_50510501_80_dialog_content = "이름이라도 남겨줬으면 했는데 말이에요.",
  ui_story_5051_50510501_81_dialog_content = "사람은 내가 알던 모습이랑 다르지만...",
  ui_story_5051_50510501_82_dialog_content = "백야성만은 현재랑 완전히 똑같네.",
  ui_story_5051_50510501_83_dialog_content = "맞아, 이 신성하고 견고한 성벽은 백야성의 상징이자,\n사람들의 신앙의 증거이기도 해.",
  ui_story_5051_50510501_84_dialog_content = "그래서 오랫동안 모두 백야성의 고결함을 지키려고 어떤 대가든지 치렀던 거야...\n이렇게 보면 모든 희생이 가치가 있었던 것 같아.",
  ui_story_5051_50510501_85_dialog_content = "거기 당신, 입성 허가증을 보여주세요.",
  ui_story_5051_50510501_86_dialog_content = "어, 저요...?",
  ui_story_5051_50510501_87_dialog_content = "저기, 이쪽은 내 친구야.",
  ui_story_5051_50510501_88_dialog_content = "베, 베로니카 공주 전하?!",
  ui_story_5051_50510501_89_dialog_content = "들어오십시오! 부디 방금 제 실례를 용서해 주십시오!",
  ui_story_5051_50510501_90_dialog_content = "괜찮아. 기념일에도 보초를 서느라 고생이 많아... 그럼 힘내줘.",
  ui_story_5051_50510501_91_dialog_content = "예!",
  ui_story_5051_50510501_92_dialog_content = "휴~ 공주 신분은 참 편리하구나.",
  ui_story_5051_50510501_93_dialog_content = "전에도 경비병이 가로막았을 때 카렌 덕분에 넘어갔었는데 말이야...",
  ui_story_5051_50510501_94_dialog_content = "PlayerName 넌 좋은 사람이니까 다들 도와주는 거야.",
  ui_story_5051_50510501_95_dialog_content = "그래? 헤헤, 왠지 좀 쑥스럽네.",
  ui_story_5051_50510501_96_dialog_content = "아, 맞다. 잠깐만.",
  ui_story_5051_50510501_97_dialog_content = "저기... 혹시 오늘 「근엄한 백발의 애꾸눈 노인」이나, 「금발에 보라색 눈의 귀족 청년」...",
  ui_story_5051_50510501_98_dialog_content = "아니면 「붉은 머리의 북방 점술사」가 백야성에 오지 않았나요?",
  ui_story_5051_50510501_99_dialog_content = "처음 두 분은 못 봤습니다만...",
  ui_story_5051_50510501_100_dialog_content = "어제 알현하러 오신 북방의 사절분은 확실히 지금 말씀하신 그런 모습이었습니다.",
  ui_story_5051_50510501_101_dialog_content = "(어제 알현하러 온 북방의 사절이라면... 아마 전임 사절이겠지?)",
  ui_story_5051_50510501_102_dialog_content = "알겠어요, 고마워요.",
  ui_story_5051_50510501_103_dialog_content = "PlayerName, 무슨 일이야?",
  ui_story_5051_50510501_104_dialog_content = "경비병이 우리 일행을 봤는지 물어보려던 건데, 아무래도 못 본 모양이야.",
  ui_story_5051_50510501_105_dialog_content = "역시 우리끼리 찾을 수밖에 없겠어.",
  ui_story_5051_50510501_106_dialog_content = "──!!",
  ui_story_5051_50510501_107_dialog_content = "암귀다! 어째서 화물 안에 암귀가 있는 거지?!",
  ui_story_5051_50510501_108_dialog_content = "왜 여기도 암귀가 있어?!",
  ui_story_5051_50510501_109_dialog_content = "괘, 괜찮아. 내가 상대할게...!",
  ui_story_5051_50510502_1_dialog_content = "무슨 일이냐!",
  ui_story_5051_50510502_2_dialog_content = "<color=#FFB400>마임</color> 기사장님, 보고드립니다!\n조금 전 화물 속에 숨어있던 암귀가 대열을 습격했습니다!",
  ui_story_5051_50510502_3_dialog_content = "화물을 운송한 상인은 저희가 체포했고, 사상자는 발생하지 않았습니다.",
  ui_story_5051_50510502_4_dialog_content = "「가문의 날」 축제가 열리는 날에 어째서 이런 일이 발생할 수 있단 말이냐.",
  ui_story_5051_50510502_5_dialog_content = "용의자는 내게 넘겨라. 중대한 죄를 지은 자이니 내가 친히 심판소에 압송하겠다.",
  ui_story_5051_50510502_6_dialog_content = "예!",
  ui_story_5051_50510502_7_dialog_content = "허나 암귀는 어디 있지? 너희들이 모두 처리한 것이냐?",
  ui_story_5051_50510502_8_dialog_content = "한 마리도 남기지 않고 처치했습니다!",
  ui_story_5051_50510502_9_dialog_content = "모두 공주 전하 덕분입니다!",
  ui_story_5051_50510502_10_dialog_content = "공주님! 정말 대단해요!",
  ui_story_5051_50510502_11_dialog_content = "백야성의 용감하고 강한 공주라면... 설마 카렌 공주님인가?",
  ui_story_5051_50510502_12_dialog_content = "아니, 아닐세. 저분은 베로니카 공주님이야.",
  ui_story_5051_50510502_13_dialog_content = "설마 첫째 공주 베로니카 전하까지 저렇게 강하실 줄이야...\n솔라드 가문은 정말 인재가 많군...",
  ui_story_5051_50510502_14_dialog_content = "<size=30>으읏, PlayerName... 다들 날 보고 있어. 왠지 기분이 이상해...</size>",
  ui_story_5051_50510502_15_dialog_content = "아까 미아가 싸우는 모습이 멋있었으니까 그렇지!",
  ui_story_5051_50510502_16_dialog_content = "암귀를 순식간에 전부 쓰러트린 모습은 꼭 백전의 용사 같았다니까.",
  ui_story_5051_50510502_17_dialog_content = "내가... 멋있었어?",
  ui_story_5051_50510502_18_dialog_content = "당연하지!",
  ui_story_5051_50510502_19_dialog_content = "그, 그렇구나... 고마워...",
  ui_story_5051_50510502_20_dialog_content = "용의자는 우리에게 인도해라. 고생했다.",
  ui_story_5051_50510502_21_dialog_content = "알겠습니다. 그럼 잘 부탁드리겠습니다.",
  ui_story_5051_50510502_22_dialog_content = "(저 사람...)",
  ui_story_5051_50510502_23_dialog_content = "(<color=#FFB400>시로나</color> 씨잖아?!)",
  ui_story_5051_50510502_24_dialog_content = "그쪽은 누군데 왜 날 뚫어져라 보는 거지?",
  ui_story_5051_50510502_25_dialog_content = "무슨 부탁이라도 있다면 말해라.\n난 비록 예비 기사일 뿐이지만, 맹세는 반드시 지키고, 온 힘을 다해 돕겠다.",
  ui_story_5051_50510502_26_dialog_content = "하지만 아무 용건도 없다면 자신이 해야 할 일에나 집중해라.",
  ui_story_5051_50510502_27_dialog_content = "(이런, 날 주목해 버렸잖아! 어떻게든 얼버무려서 접촉을 피해야 해!)",
  ui_story_5051_50510502_28_dialog_content = "(근데... 12년 전의 시로나 씨는 아직 14살 아냐?\n어릴 때부터 저렇게 엄격했구나...)",
  ui_story_5051_50510502_29_dialog_content = "앗, 미안해요. 아무것도 아니에요. 그냥 뭔가 저랑 인연이 있는 것 같아서요...",
  ui_story_5051_50510502_30_dialog_content = "인연? 그런 허무맹랑한 말을 꺼내다니, 영문을 모르겠군.",
  ui_story_5051_50510502_31_dialog_content = "그런 진부한 말은 길가의 어린애를 놀릴 때나 쓰도록.",
  ui_story_5051_50510502_32_dialog_content = "아하하하... 아, 아무튼 실례했습니다.",
  ui_story_5051_50510502_33_dialog_content = "-",
  ui_story_5051_50510502_34_dialog_content = "-",
  ui_story_5051_50510502_35_dialog_content = "-",
  ui_story_5051_50510502_36_dialog_content = "-",
  ui_story_5051_50510502_37_dialog_content = "-",
  ui_story_5051_50510502_38_dialog_content = "어이, 봤어? 시로나가 순찰 중에 다른 사람이랑 잡담을 했어!",
  ui_story_5051_50510502_39_dialog_content = "뭐, 어때. 시로나도 십대 소녀잖아. 가끔 좀 놀고 싶을 수도 있지.",
  ui_story_5051_50510502_40_dialog_content = "맞아, 안 그래도 평소 자기한테 너무 엄격한 걸 보면 안쓰러웠다고.",
  ui_story_5051_50510502_41_dialog_content = "휴, 나도 땡땡이치고 꽃마차 퍼레이드 보러 가고 싶다...",
  ui_story_5051_50510502_42_dialog_content = "<size=45>거기 기사들!</size>",
  ui_story_5051_50510502_43_dialog_content = "오늘은 바야흐로 백야성 전역의 경축일이다.\n우리 카르티마 가문은 영광스럽게도 백성의 안전을 지키는 중임을 맡았다.",
  ui_story_5051_50510502_44_dialog_content = "부디 동포들이 사명에 부끄러움이 없도록 엄숙히 임무를 수행하길 바란다.",
  ui_story_5051_50510502_45_dialog_content = "......",
  ui_story_5051_50510502_46_dialog_content = "(아하하하... 시로나 씨 성격은 이때부터 하나도 안 변한 거였구나.)",
  ui_story_5051_50510502_47_dialog_content = "저기... PlayerName, 마임 씨가 어머님이 계신 궁전에 데려다주신대.",
  ui_story_5051_50510502_48_dialog_content = "-",
  ui_story_5051_50510502_49_dialog_content = "-",
  ui_story_5051_50510502_50_dialog_content = "-",
  ui_story_5051_50510502_51_dialog_content = "-",
  ui_story_5051_50510502_52_dialog_content = "-",
  ui_story_5051_50510502_53_dialog_content = "-",
  ui_story_5051_50510502_54_dialog_content = "-",
  ui_story_5051_50510502_55_dialog_content = "-",
  ui_story_5051_50510502_56_dialog_content = "-",
  ui_story_5051_50510502_57_dialog_content = "-",
  ui_story_5051_50510502_58_dialog_content = "그거 잘됐네!\n아, 맞다. 기사단 사람한테 부탁할 게 있었지. 잠깐만 기다리고 있어!",
  ui_story_5051_50510502_59_dialog_content = "어? PlayerName?",
  ui_story_5051_50510502_60_dialog_content = "안녕하세요, 마임 씨라고 하셨죠?",
  ui_story_5051_50510502_61_dialog_content = "그렇습니다만, 무슨 일입니까?",
  ui_story_5051_50510502_62_dialog_content = "친구 세 명과 도중에 엇갈려 버렸거든요.\n저흰 모두 베로니카 공주 전하의 손님이에요.",
  ui_story_5051_50510502_63_dialog_content = "혹시 괜찮으시다면 제가 말씀드리는 세 사람을 좀 찾아 주시겠어요?\n인상착의는...",
  ui_story_5051_50510502_64_dialog_content = "그럼 지금부터 저는 성주 전하를 알현해야 하니 여기서 먼저 실례하겠습니다.",
  ui_story_5051_50510502_65_dialog_content = "고마워요, 마임 씨.",
  ui_story_5051_50510502_66_dialog_content = "저기... 이따가 아버님을 뵀을 때 저랑 친구들에 대해서는\n말씀을 꺼내지 말아 주실 수 있을까요...?",
  ui_story_5051_50510502_67_dialog_content = "그저 말을 꺼내지 않는 것뿐이라면 물론 전하의 체면을 봐서 가능하겠지요.",
  ui_story_5051_50510502_68_dialog_content = "다만 오늘은 제 기사단이 기념일의 순찰과 경비를 담당합니다.\n부디 전하와 친구분도 절 곤란하게 하는 일이 없도록 부탁드립니다.",
  ui_story_5051_50510502_69_dialog_content = "알겠어요. 절대 폐 끼치지 않을게요.",
  ui_story_5051_50510502_70_dialog_content = "미아, 이야기는 끝났어?",
  ui_story_5051_50510502_71_dialog_content = "응, 마임 씨한테 아버님 앞에서 우리 얘기를 꺼내지 말아 달라고 부탁했어.",
  ui_story_5051_50510502_72_dialog_content = "과거 이날에 난 독단적인 결정을 했거든.\n지금 내가 돌아온 걸 아버님께서 보신다면 분명히 화내실 거야...",
  ui_story_5051_50510502_73_dialog_content = "베로니카?",
  ui_story_5051_50510502_74_dialog_content = "어, 어머님...?",
  ui_story_5051_50510502_75_dialog_content = "어머님!",
  ui_story_5051_50510502_76_dialog_content = "어머, 우리 귀염둥이가 왜 이러실까?",
  ui_story_5051_50510502_77_dialog_content = "어머님... 정말 어머님인가요...? 정말... 보고 싶었어요...",
  ui_story_5051_50510502_78_dialog_content = "그래, 착하지. 엄마는 여기 있어.",
  ui_story_5051_50510502_79_dialog_content = "자, 엄마한테 얼굴 좀 보여주렴. 혹시 기사단에서 다쳤니?",
  ui_story_5051_50510502_80_dialog_content = "아니면 친구랑 싸운 걸까?",
  ui_story_5051_50510502_81_dialog_content = "(어? 왜 날 보시는 거지...?! 아, 아, 아니에요! 제 탓이 아니라구요!\n미아 어머님... 오해하지 마세요!)",
  ui_story_5051_50510502_82_dialog_content = "어머님, 전 PlayerName의 도움으로 여기까지 온 거예요...",
  ui_story_5051_50510502_83_dialog_content = "그랬구나. 좋은 친구를 만들었구나.",
  ui_story_5051_50510502_84_dialog_content = "어머, 너 무릎은 왜 그러니? 관절 부위의 자국은 대체...",
  ui_story_5051_50510502_85_dialog_content = "괜찮아요, 어머님. 전 괜찮아요...",
  ui_story_5051_50510502_86_dialog_content = "전 이제... 용감해졌으니까요.",
  ui_story_5051_50510502_87_dialog_content = "그러니까... 괜찮아요...!",
  ui_story_5051_50510502_88_dialog_content = "그러니? 그런 울상으로는 설득력이 없는걸.",
  ui_story_5051_50510502_89_dialog_content = "자, 엄마가 세수 시켜줄게. 천천히 앉아서 얘기하자.",
  ui_story_5051_50510601_1_dialog_content = "(둘이서 가버렸네...)",
  ui_story_5051_50510601_2_dialog_content = "(가면서 미아 어머니가 날 보고 웃은 건 아마 여기서 기다리라는 거겠지?)",
  ui_story_5051_50510601_3_dialog_content = "(「숙녀가 단장하는 모습을 들여다보면 안 된다」는 말도 있었던 것 같으니까...\n일단 자리를 피해 줘야겠네.)",
  ui_story_5051_50510601_4_dialog_content = "(여기까지 오는 동안 만난 이스타반 씨도, 시로나 씨도, 미아 어머니도...)",
  ui_story_5051_50510601_5_dialog_content = "(모두 실제 사람처럼 아주 자연스럽게 우리랑 대화할 수 있었어.)",
  ui_story_5051_50510601_6_dialog_content = "(「영원한 기억의 수정」은 정말 신기하네...)",
  ui_story_5051_50510601_7_dialog_content = "(하지만 수정의 본래 용도를 생각하면, 우린 여기 사람들과 교류해선 안 돼.)",
  ui_story_5051_50510601_8_dialog_content = "(이런 식으로 저들과 접촉하면 분명히 수정에 부담을 늘리고 말 거야.)",
  ui_story_5051_50510601_9_dialog_content = "(휴, 지금 상황이 좋은 건지, 나쁜 건지... 얼른 사람들을 찾아야 할 텐데...)",
  ui_story_5051_50510601_10_dialog_content = "거기 당신.",
  ui_story_5051_50510601_11_dialog_content = "여긴 솔라드 가문의 사유지야.",
  ui_story_5051_50510601_12_dialog_content = "수상한 녀석, 어떻게 들어왔어?",
  ui_story_5051_50510601_13_dialog_content = "응? 지금 누가 말하는 거야?",
  ui_story_5051_50510601_14_dialog_content = "무례한 녀석! 카렌은 네 앞에 있잖아!",
  ui_story_5051_50510601_15_dialog_content = "<size=45>카렌?!</size>",
  ui_story_5051_50510601_16_dialog_content = "감히 내 이름을 함부로 불러?",
  ui_story_5051_50510601_17_dialog_content = "카렌도 귀족의 오만한 태도는 싫어.\n하지만 여기서 카렌을 무시하는 건 솔라드 가문을 무시하는 거나 다름없어.",
  ui_story_5051_50510601_18_dialog_content = "「솔라드 가문의 날」에 우리 영지로 몰래 침입해서...",
  ui_story_5051_50510601_19_dialog_content = "불손한 언동으로 솔라드의 이름을 더럽히다니, 앞으로 어떻게 될지 알고 있겠지?",
  ui_story_5051_50510601_20_dialog_content = "잠깐만! 방금은 그냥 한눈에 못 찾아서 그런 거야!",
  ui_story_5051_50510601_21_dialog_content = "카, 카렌... 아니, 카렌 전하! 제 말 좀 들어보세요!",
  ui_story_5051_50510601_22_dialog_content = "누구게?",
  ui_story_5051_50510601_23_dialog_content = "<size=45>으앗?!</size>",
  ui_story_5051_50510601_24_dialog_content = "뭐, 뭐야?!",
  ui_story_5051_50510601_25_dialog_content = "비겁한 침입자! 한패가 있었어?!",
  ui_story_5051_50510601_26_dialog_content = "어? 음...",
  ui_story_5051_50510601_27_dialog_content = "그래, 우린 동료야. 둘이서 카렌을 잡으러 왔어~",
  ui_story_5051_50510601_28_dialog_content = "비, 비겁해! 카렌의 장창은 어디 있어?!\n흐앙, 이거 놔! 장창을 못 찾겠어!",
  ui_story_5051_50510601_29_dialog_content = "자, 잠깐만... 이 목소리... 혹시 언니야?",
  ui_story_5051_50510601_30_dialog_content = "우후후~ 틀렸어, 베로니카 아니거든~",
  ui_story_5051_50510601_31_dialog_content = "그렇게 목소리 바꿔서 카렌 놀리지 마! 카, 카렌은 이제 어린애가 아냐!",
  ui_story_5051_50510601_32_dialog_content = "어머, 진짜? 카렌~",
  ui_story_5051_50510601_33_dialog_content = "후훗... 카렌은 평소에는 어른스럽게 굴지만, 눈만 가리면 당황한다니까.",
  ui_story_5051_50510601_34_dialog_content = "어머님? 어머님도 계신가요? 언니한테 카렌을 놔달라고 해주세요!",
  ui_story_5051_50510601_35_dialog_content = "안 돼~ 왜 또 어머님이라고 부르는 거니? 엄마라고 안 부르면 안 도와줄래~",
  ui_story_5051_50510601_36_dialog_content = "너, 너무해요!",
  ui_story_5051_50510601_37_dialog_content = "손님한테 사납게 군 건 누구였을까?",
  ui_story_5051_50510601_38_dialog_content = "초면인 사람을 퉁명스럽게 대하면 좋지 않아.",
  ui_story_5051_50510601_39_dialog_content = "역시 너 때문이었어! 비겁한 침입자! 언니와 어머님을 어떻게 속인 거야?!",
  ui_story_5051_50510601_40_dialog_content = "아, 아니, 난 아무것도 안 했다고...",
  ui_story_5051_50510601_41_dialog_content = "헤헤, 우리 카렌이 얼마나 더 참을 수 있을까?",
  ui_story_5051_50510601_42_dialog_content = "히잉... 카렌이 잘못했어! 사납게 안 굴게! 언니, 엄마... 카렌을 놔 줘...",
  ui_story_5051_50510601_43_dialog_content = "후훗, 카렌이랑 이렇게 노는 것도 정말 오랜만이네.\n웃겨서 배가 다 아플 정도야...",
  ui_story_5051_50510601_44_dialog_content = "으으... 언니 너무해...",
  ui_story_5051_50510601_45_dialog_content = "그래야지. 베로니카는 역시 웃을 때가 제일 귀엽거든.",
  ui_story_5051_50510601_46_dialog_content = "그런데 우리 카렌은 아직도 안 웃네... 엄마가 간지럼 태워줄까?",
  ui_story_5051_50510601_47_dialog_content = "괘, 괜찮아요!",
  ui_story_5051_50510601_48_dialog_content = "가족은 역시 이래야지. 다니엘도 있었으면 좋았을 텐데...",
  ui_story_5051_50510601_49_dialog_content = "미안해, 못난 모습을 보이고 말았네.",
  ui_story_5051_50510601_50_dialog_content = "베로니카에게 들었어. PlayerName, 이렇게 불러도 될까?",
  ui_story_5051_50510601_51_dialog_content = "그럼요. 어떻게 부르셔도 다 괜찮아요.",
  ui_story_5051_50510601_52_dialog_content = "네가 베로니카를 「미아」라고 부르는 것처럼?",
  ui_story_5051_50510601_53_dialog_content = "아? 그, 그건...",
  ui_story_5051_50510601_54_dialog_content = "(미아랑 이야기하는 걸 들으신 모양이네!)",
  ui_story_5051_50510601_X54_dialog_content = "어머님... 저기, 사실... 저흰 움브라톤에서 만난 친구 사이예요. 그리고...",
  ui_story_5051_50510601_56_dialog_content = "후훗, 괜찮아. 나도 젊었을 땐 자주 가명을 쓰고 나가서 놀았거든.",
  ui_story_5051_50510601_57_dialog_content = "누구든 선의의 작은 비밀은 있기 마련이잖니, 엄마도 이해해.",
  ui_story_5051_50510601_58_dialog_content = "어머님... 감사해요.",
  ui_story_5051_50510601_59_dialog_content = "-",
  ui_story_5051_50510601_60_dialog_content = "-",
  ui_story_5051_50510601_61_dialog_content = "-",
  ui_story_5051_50510601_62_dialog_content = "-",
  ui_story_5051_50510601_63_dialog_content = "-",
  ui_story_5051_50510601_64_dialog_content = "-",
  ui_story_5051_50510601_65_dialog_content = "-",
  ui_story_5051_50510601_66_dialog_content = "선의의 작은 비밀? 카렌은 이해 못 했어요...",
  ui_story_5051_50510601_67_dialog_content = "비겁한 침입자! 빨리 비밀이 뭔지 말해!",
  ui_story_5051_50510601_68_dialog_content = "내 이름은 PlayerName인데...",
  ui_story_5051_50510601_69_dialog_content = "(카렌이 내 발을 밟다니...)",
  ui_story_5051_50510601_70_dialog_content = "(지금 이 어린 카렌도 실제 나이보다 진지하고 어른스럽긴 하지만,\n표정이 굉장히 풍부하고 활발한 아이네.)",
  ui_story_5051_50510601_71_dialog_content = "(어머니가 돌아가시고, 언니도 사라지고... 아버지와의 관계도...\n카렌도 힘든 일을 많이 겪었으니까...)",
  ui_story_5051_50510601_72_dialog_content = "(그런 경험이 없었다면 현실의 카렌은 더 많이 웃는 아이가 되었을까?)",
  ui_story_5051_50510601_73_dialog_content = "-",
  ui_story_5051_50510601_74_dialog_content = "-",
  ui_story_5051_50510601_75_dialog_content = "-",
  ui_story_5051_50510601_76_dialog_content = "미안해. 카렌이 조금 고지식해 보여도, 사실은 표현이 서투를 뿐이고 나쁜 마음은 없어.",
  ui_story_5051_50510601_77_dialog_content = "미... 아니, 베로니카, 이제 가족들 일이 다 기억났어?",
  ui_story_5051_50510601_78_dialog_content = "응, 어머님이랑 여동생이랑 같이 있으니까...\n모든 기억이 다 갑자기 되살아난 것 같아.",
  ui_story_5051_50510601_79_dialog_content = "나랑 여동생은 같이 정원에서 그네를 타는 걸 가장 좋아했어...",
  ui_story_5051_50510601_80_dialog_content = "「누구게?」 놀이도 질리지도 않고 계속했고...",
  ui_story_5051_50510601_81_dialog_content = "그 기억들도, 감정도, 행복도... 전부 사실이었던 거야...",
  ui_story_5051_50510601_82_dialog_content = "생각나서 정말 다행이야!",
  ui_story_5051_50510601_83_dialog_content = "(하지만 미아는 아버지를 전혀 언급하지 않고 있잖아...\n아까 응접실에서 만났을 때도 뭔가 답답한 분위기였고.)",
  ui_story_5051_50510601_84_dialog_content = "(혹시 미아도 카렌이랑 마찬가지로 아버지랑 사이가 안 좋았던 걸까?)",
  ui_story_5051_50510601_85_dialog_content = "한참 놀았는데, 목은 안 마르니? 배고프진 않아? 홀에 간식이 있단다.",
  ui_story_5051_50510601_86_dialog_content = "언니, 가자. 같이 가서 간식 먹자.",
  ui_story_5051_50510601_87_dialog_content = "어머, 언니 잡아당기지 말고 천천히 가...",
  ui_story_5051_50510601_88_dialog_content = "PlayerName, 너도 멍하니 있지 말고 같이 가자.",
  ui_story_5051_50510601_89_dialog_content = "하하... 모처럼 가족끼리 모였는데, 전 방해 안 할게요.",
  ui_story_5051_50510601_90_dialog_content = "얘, 괜찮아.",
  ui_story_5051_50510601_91_dialog_content = "...네 그 눈빛, 난 무척 익숙하게 느껴지거든.",
  ui_story_5051_50510601_92_dialog_content = "비록 굳세지만, 그 안의 빛깔은 길을 잃은 아이처럼 외로워 보여.",
  ui_story_5051_50510601_93_dialog_content = "움브라톤에서 지내면서 뭔가 곤란한 일이라도 있었니?",
  ui_story_5051_50510601_94_dialog_content = "아, 아니에요! 사실 전 움브라톤 사람도 아니고, 저는...",
  ui_story_5051_50510601_95_dialog_content = "(아... 말하면 안 돼. 아이테르는 외부와 교류하지 않는 종족이고,\n바깥사람들도 우릴 잘 알지 못해.)",
  ui_story_5051_50510601_96_dialog_content = "(다른 사람들한테 내가 아이테르라는 말을 한다면...\n분명히 「영원한 기억의 수정」에 부담을 주게 될 거야.)",
  ui_story_5051_50510601_97_dialog_content = "저는 보잘것없는 사람이에요.",
  ui_story_5051_50510601_98_dialog_content = "전 가족이 없어요. 그래서 곳곳을 여행하면서 새 친구를 만나는 걸 좋아해요.",
  ui_story_5051_50510601_99_dialog_content = "여행... 나도 여행을 좋아해.\n하지만 아쉽게도 곳곳을 돌아다닐 기회는 없었어.",
  ui_story_5051_50510601_100_dialog_content = "얘, 넌 지금 생활이 행복하니?",
  ui_story_5051_50510601_101_dialog_content = "네, 행복해요.",
  ui_story_5051_50510601_102_dialog_content = "그럼 다행이구나.",
  ui_story_5051_50510601_103_dialog_content = "넌 베로니카의 친구고, 마음이 예쁜 착한 아이 같아.",
  ui_story_5051_50510601_104_dialog_content = "여기 있는 동안에는 이 집을 네 집이라고 생각하렴.",
  ui_story_5051_50510601_105_dialog_content = "고마워요... 공작부인님.",
  ui_story_5051_50510601_106_dialog_content = "내 이름은 조슈아야. 편하게 불러도 돼.",
  ui_story_5051_50510601_107_dialog_content = "아, 아하하... 그래도 역시 조슈아 공작부인님이라고 부르는 게 좋을 것 같아요.",
  ui_story_5051_50510601_108_dialog_content = "언니, 몰래 기사단을 따라 움브라톤에서 임무를 수행했어?!",
  ui_story_5051_50510601_109_dialog_content = "어떤 임무야? 기사단은 어떻게 싸워? 나한테도 말려줄 수 있어?",
  ui_story_5051_50510601_110_dialog_content = "그건...",
  ui_story_5051_50510601_111_dialog_content = "그래, 베로니카. 내게 그 건에 대한 해명을 할 수 있겠느냐.",
  ui_story_5051_50510601_112_dialog_content = "<size=45>아, 아버님!</size>",
  ui_story_5051_50510601_113_dialog_content = "네게 전사의 무용이 있다면, 전장에 나가길 자청해도 나는 반대하지 않는다.",
  ui_story_5051_50510601_114_dialog_content = "허나 너는 또다시 싸움에서 도망쳤을 뿐만 아니라,\n당당하게 궁전에 숨어들어 기념일을 즐기고 있다.",
  ui_story_5051_50510601_115_dialog_content = "가문의 기념일에 이러한 촌극을 벌여놓고, 어떻게 수습할 생각이냐.",
  ui_story_5051_50510601_116_dialog_content = "............",
  ui_story_5051_50510601_117_dialog_content = "다니엘, 베로니카는 내가 부른 거예요.",
  ui_story_5051_50510601_118_dialog_content = "오늘은 솔라드가의 가족들이 모여 함께 보내는 날이잖아요.\n그러면 베로니카도 물론 우리와 함께해야죠. 아닌가요?",
  ui_story_5051_50510601_119_dialog_content = "...조슈아, 솔라드는 「가문」이지 「가족」이 아냐.",
  ui_story_5051_50510601_120_dialog_content = "솔라드 가문은 자식을 응석받이로 키운 선례는 없어.\n물론 앞으로도 있어선 안 되고.",
  ui_story_5051_50510601_121_dialog_content = "그래요. 우린 「가문」이죠. 하지만 「가족」이기도 해요.",
  ui_story_5051_50510601_122_dialog_content = "가장 가까운 사람의 마음도 헤아려 주지 못한다면,\n어떻게 한 가문을 지탱할 수 있겠어요?",
  ui_story_5051_50510601_123_dialog_content = "(이 사람이 솔라드 씨...?)",
  ui_story_5051_50510601_124_dialog_content = "(위엄 있는 건 똑같지만, 지금이랑은 전혀 다르잖아...\n고작 이 시간 동안 그렇게나 늙었단 말이야?)",
  ui_story_5051_50510601_125_dialog_content = "(어색한 분위기네... 미아도 안색이 엄청 나쁘잖아...\n하필 이럴 때 감응 능력을 쓸 수 없다니!)",
  ui_story_5051_50510601_126_dialog_content = "실례합니다, 지나갈게요.",
  ui_story_5051_50510601_127_dialog_content = "(블랑 씨네! 아까랑 같은 예복을 입고 있어...\n12년 전에도 솔라드 씨의 일을 돕고 있었구나.)",
  ui_story_5051_50510601_128_dialog_content = "그대는 또 누구인가?",
  ui_story_5051_50510601_129_dialog_content = "저, 저요? 전 베로니카의 친구인데요...",
  ui_story_5051_50510601_130_dialog_content = "친구라고?",
  ui_story_5051_50510601_131_dialog_content = "다니엘.",
  ui_story_5051_50510601_132_dialog_content = "휴, 미즈 로트, 이자를 손님으로 대접하게.",
  ui_story_5051_50510601_133_dialog_content = "알겠습니다.",
  ui_story_5051_50510601_134_dialog_content = "성주 전하, 원로원의 귀족들이 기다리고 있습니다.",
  ui_story_5051_50510601_135_dialog_content = "조슈아, 그대가 베로니카를 다시 불러들였으니, 잘 지켜봐 줘.",
  ui_story_5051_50510601_136_dialog_content = "베로니카와 친구가 다른 소란을 일으키지 않도록.",
  ui_story_5051_50510601_137_dialog_content = "알겠어요. 잘 돌보고 있을게요.",
  ui_story_5051_50510601_138_dialog_content = "그러니까 당신도 너무 매섭게 굴지 말아요. 알겠죠?",
  ui_story_5051_50510601_139_dialog_content = "...그래.",
  ui_story_5051_50510601_140_dialog_content = "곧 퍼레이드가 시작될 테니 어서 아이들을 데리고 준비해 줘.",
  ui_story_5051_50510601_141_dialog_content = "휴...",
  ui_story_5051_50510601_142_dialog_content = "베로니카, 괜찮니?",
  ui_story_5051_50510601_143_dialog_content = "아빠가 오늘 많이 바빠서 그래. 너한테 화가 난 건 아니야.",
  ui_story_5051_50510601_144_dialog_content = "저...전...",
  ui_story_5051_50510601_145_dialog_content = "자, 착하지. 무서워할 거 없어.",
  ui_story_5051_50510601_146_dialog_content = "언니...",
  ui_story_5051_50510601_147_dialog_content = "공작부인 전하, 퍼레이드까진 아직 시간이 있습니다.\n가족들과 말씀 나누고 계세요. 준비는 제게 맡겨주시면 됩니다.",
  ui_story_5051_50510601_148_dialog_content = "고마워, 미즈 로트.",
  ui_story_5051_50510601_149_dialog_content = "제가 마땅히 해야 할 일인걸요.",
  ui_story_5051_50510601_150_dialog_content = "그리고 친구분께서는 번거로우시겠지만 저와 함께\n퍼레이드 절차를 확인하고 준비하는 일을 도와주셨으면 해요.",
  ui_story_5051_50510601_151_dialog_content = "안심하세요. 베로니카 공주님은 공작부인 전하께서 잘 달래주실 거예요.",
  ui_story_5051_50510601_152_dialog_content = "알겠어요... 그럼 잘 부탁할게요, 블랑 씨.",
  ui_story_5051_50510601_153_dialog_content = "블랑 씨? 어머, 여기서 절 그렇게 부르는 분을 만날 줄은 몰랐네요.",
  ui_story_5051_50510601_154_dialog_content = "그런데 어떻게 제 이름을 알고 계실까요?",
  ui_story_5051_50510601_155_dialog_content = "(설마 블랑 씨가 12년 전에는 이 이름이 아니었던 건가?)",
  ui_story_5051_50510601_156_dialog_content = "(아참, 오늘 현실에서 솔라드 씨는 블랑 씨를 「미즈 로트」라고 불렀어.)",
  ui_story_5051_50510601_157_dialog_content = "(...그럼 「미즈 로트」는 솔라드 씨를 위해 일할 때 쓰는 이름인 모양이네.\n이걸 뭐라고 얼버무리지...?)",
  ui_story_5051_50510601_158_dialog_content = "그리 곤란해하실 필요는 없어요.\n제게 비밀이 있듯이 당신에게도 비밀이 있을 테니까요. 전혀 이상하지 않아요.",
  ui_story_5051_50510601_159_dialog_content = "당신은 성주 전하께서 친히 제게 대접을 당부하신 손님이에요.\n그러니 오늘 당신이 멋진 하루를 보내도록 돕는 건 제 책무예요.",
  ui_story_5051_50510601_160_dialog_content = "다만 일을 더 쉽게 할 수 있도록 당분간은 「미즈 로트」라고 불러주시겠어요?",
  ui_story_5051_50510601_161_dialog_content = "알겠어요, 「미즈 로트」. 폐 끼치지 않을게요.",
  ui_story_5051_50510601_162_dialog_content = "협조에 감사드려요. 자, 이쪽으로 오시죠.",
  ui_story_5051_50510701_1_dialog_content = "「인웨니이레 에움~ 인웨니이레 에움~ 인웨니이레 에움~」",
  ui_story_5051_50510701_2_dialog_content = "부디 알려주세요. 제가 생각하는 사람은 지금 어디에 있나요?",
  ui_story_5051_50510701_3_dialog_content = "<size=45>「아브라하다브라!」</size>",
  ui_story_5051_50510701_4_dialog_content = "아... 이 앞이구나!",
  ui_story_5051_50510701_5_dialog_content = "다른 기사단 하나가 움브라톤에 파견됐다고 하더라고.",
  ui_story_5051_50510701_6_dialog_content = "뭐? 움브라톤엔 뭐 하러 가는 건데?",
  ui_story_5051_50510701_7_dialog_content = "암귀의 침입에 맞서는 거지. 움브라톤도 백야성의 방어선 중 하나니까.",
  ui_story_5051_50510701_8_dialog_content = "그럼 우린 왜 안 가?",
  ui_story_5051_50510701_9_dialog_content = "너 바보냐? 우린 <color=#FFB400>카르티마</color> 가문 기사단이잖아. 그딴 곳에 뭐 하러 가?",
  ui_story_5051_50510701_10_dialog_content = "쉿! 조용히 해. 또 시로나한테 땡땡이치는 거 들키고 싶어?",
  ui_story_5051_50510701_11_dialog_content = "역시 카르티마 가문이 좋다니까.\n성주님에 버금가는 발언권이 있는 가문답단 말이야.",
  ui_story_5051_50510701_12_dialog_content = "그런 거였나...",
  ui_story_5051_50510701_13_dialog_content = "그런 거였구나...",
  ui_story_5051_50510701_14_dialog_content = "어이! 당신 누구야?!",
  ui_story_5051_50510701_15_dialog_content = "수상한 녀석이다! 잡아!",
  ui_story_5051_50510701_16_dialog_content = "아하하, 미안해요! 길을 잘못 들었나 봐요! 바이바이~",
  ui_story_5051_50510701_17_dialog_content = "「아브라하다브라!」",
  ui_story_5051_50510701_18_dialog_content = "이번엔 또 어디야?",
  ui_story_5051_50510701_19_dialog_content = "이번 학기도 성적 1등은 또 이리돈인가...",
  ui_story_5051_50510701_20_dialog_content = "이리돈 선배는 예쁘면서 공부도 잘하고, 여명 아카데미 선생님들 앞에서도 당당해.",
  ui_story_5051_50510701_21_dialog_content = "정말 동경하게 된다니까.",
  ui_story_5051_50510701_22_dialog_content = "휴, 저러면 나중에 월반해서 조기 졸업할 것 같단 말이지.",
  ui_story_5051_50510701_23_dialog_content = "사람이 너무 심하게 완벽한 거 아냐?",
  ui_story_5051_50510701_24_dialog_content = "이리돈? 그게 누구지?",
  ui_story_5051_50510701_25_dialog_content = "저 특이한 복장을 한 여자애는 누구지? 빨간 머리가 참 예쁘네.",
  ui_story_5051_50510701_26_dialog_content = "저게 대체 무슨 복장이야?! 부끄러운 줄도 모르나? 심판소에 신고해야겠어!",
  ui_story_5051_50510701_27_dialog_content = "으아아... 또 잘못 왔나 봐요! 미안해요!",
  ui_story_5051_50510701_28_dialog_content = "「아브라... 하다브라...」",
  ui_story_5051_50510701_29_dialog_content = "여긴... 식당?",
  ui_story_5051_50510701_30_dialog_content = "근데 사람이 없잖아?",
  ui_story_5051_50510701_31_dialog_content = "<color=#e8d9bb>꼬르륵──</color>",
  ui_story_5051_50510701_32_dialog_content = "수정구슬아, 지금 내가 배고픈 걸 알고 여기 데려와 준 거야?",
  ui_story_5051_50510701_33_dialog_content = "으... 그래도 사람 찾는 게 먼저야!\n그리고 수정 속 세계에서 뭘 먹어봤자 아무 의미도 없잖아!",
  ui_story_5051_50510701_34_dialog_content = "다시 가자!",
  ui_story_5051_50510701_35_dialog_content = "「인웨니이레 에움~ 인웨니이레 에움~ 인웨니이레 에움~」",
  ui_story_5051_50510701_36_dialog_content = "부디 알려주세요. 제가 생각하는 사람은 지금 어디에 있나요?",
  ui_story_5051_50510701_37_dialog_content = "「아브라하다브라!」",
  ui_story_5051_50510701_38_dialog_content = "<size=45>푸하하하하하!</size>",
  ui_story_5051_50510701_39_dialog_content = "누, 누구세요?! 갑자기 큰소리로 웃고... 깜짝 놀랐잖아요!",
  ui_story_5051_50510701_40_dialog_content = "야, 너 점술 실력이... 딸꾹... 진짜 허접하네.",
  ui_story_5051_50510701_41_dialog_content = "지금 제 점술이 허접하다구요?!",
  ui_story_5051_50510701_42_dialog_content = "제 점술은 엄마한테 배운 거예요! 우리 엄마는 최고의 점술사라구요!",
  ui_story_5051_50510701_43_dialog_content = "설마 북방의 점술사 「<color=#FFB400>보아즈</color>」를 모른다고는 안 하겠죠!",
  ui_story_5051_50510701_44_dialog_content = "「푸아즈」...? 어디서 들어본 것도 같은데... 딸꾹.",
  ui_story_5051_50510701_45_dialog_content = "그래서 그게 뭐 어쨌다고? 네가 못하면 못한 거지.\n야, 그냥 그게 네 실력이라고 순순히 인정해~",
  ui_story_5051_50510701_46_dialog_content = "흥! 정말 무례한 사람이네요!\n오늘 제가 확실하게 보여줄 테니까 똑바로 잘 봐요!",
  ui_story_5051_50510701_47_dialog_content = "딸꾹... 기지배가 실력도 없으면서 큰소리는 잘 치네.",
  ui_story_5051_50510701_48_dialog_content = "아니면 나가서 나랑 겨뤄볼래? 누구 점이 더 잘 맞는지?",
  ui_story_5051_50510701_49_dialog_content = "얼마든지요!",
  ui_story_5051_50510701_50_dialog_content = "거기 두 분, 계산하셔야죠.",
  ui_story_5051_50510701_51_dialog_content = "아? 맞다... 어머, 내 정신 좀 봐. 돈을 안 갖고 왔네... 딸꾹.",
  ui_story_5051_50510701_52_dialog_content = "그럼 그쪽 손님은요?",
  ui_story_5051_50510701_53_dialog_content = "저, 저요? 전 이 사람이랑 전혀 모르는데 왜 제가 돈을 내요...?",
  ui_story_5051_50510701_54_dialog_content = "두 분 모두 계산을 안 하시겠다면 여기서 경비병이 올 때까지 기다려 주세요.",
  ui_story_5051_50510701_55_dialog_content = "네?! 아, 안 돼요! 전 지금 중요한 일을 해야 한다구요!",
  ui_story_5051_50510701_56_dialog_content = "이게 다 당신 때문이잖아요! 가만히 있지 말고 뭐라고 말 좀 해 봐요!",
  ui_story_5051_50510701_57_dialog_content = "Zzz...",
  ui_story_5051_50510701_58_dialog_content = "잠들었잖아...",
  ui_story_5051_50510701_59_dialog_content = "돈을 내시거나 경비병에게 잡혀가거나, 둘 중 하나를 선택하세요, 아가씨.",
  ui_story_5051_50510701_60_dialog_content = "알겠어요... 얼마죠?",
  ui_story_5051_50510701_61_dialog_content = "127938 나이티움입니다.",
  ui_story_5051_50510701_62_dialog_content = "<size=45>어, 얼마요?!</size>",
  ui_story_5051_50510701_63_dialog_content = "이 손님은 저희 가게의 소장품 와인을 여러 병 드셨습니다.\n게다가 지금 가격은 기념일 특가입니다.",
  ui_story_5051_50510701_64_dialog_content = "안 돼... 내 여비... 비상금...",
  ui_story_5051_50510701_65_dialog_content = "(하지만 「영원한 기억의 수정」 속에서 일어난 일은 현실이 아니잖아.\n여기서 나오기만 하면 내 돈은 잘 있겠지?)",
  ui_story_5051_50510701_66_dialog_content = "여기요...",
  ui_story_5051_50510701_67_dialog_content = "감사합니다.",
  ui_story_5051_50510701_68_dialog_content = "저기요, 제가 당신 대신 술값을 냈어요.\n그러니까 이제 무슨 핑계를 대도 못 도망가요.",
  ui_story_5051_50510701_69_dialog_content = "엄마의 명예를 걸고 당신과 싸우겠어요!",
  ui_story_5051_50510701_70_dialog_content = "...어, 어디 갔지?",
  ui_story_5051_50510701_71_dialog_content = "으음~ 이쪽이야... 딸꾹.",
  ui_story_5051_50510701_72_dialog_content = "잠깐만요! 거기 서요!",
  ui_story_5051_50510701_73_dialog_content = "사람들 사이로 도망칠 생각인가요?!",
  ui_story_5051_50510701_74_dialog_content = "자, 이쪽이야...",
  ui_story_5051_50510701_75_dialog_content = "잡았다!",
  ui_story_5051_50510701_76_dialog_content = "술값도 대신 내게 만들고, 틈을 타서 도망치려고 하다니...",
  ui_story_5051_50510701_77_dialog_content = "제가 놓칠 줄 알았어요?!",
  ui_story_5051_50510701_78_dialog_content = "응? 뭘 도망친다는 거야? 자, 네가 찾는 사람은 저기 있어.",
  ui_story_5051_50510701_79_dialog_content = "제가 찾는 사람이요...?",
  ui_story_5051_50510701_80_dialog_content = "봐! 퍼레이드 행렬이 왔어!",
  ui_story_5051_50510701_81_dialog_content = "오오! 성주님의 저 용맹한 모습을 보거라!",
  ui_story_5051_50510701_82_dialog_content = "카렌 공주님이랑 베로니카 공주님도 보여!",
  ui_story_5051_50510701_83_dialog_content = "조슈아 님!",
  ui_story_5051_50510701_84_dialog_content = "솔라드 가문 만세!",
  ui_story_5051_50510701_85_dialog_content = "베로니카, 고개를 들으렴. 모두가 네게 인사하고 있어.",
  ui_story_5051_50510701_86_dialog_content = "아...알겠어요.",
  ui_story_5051_50510701_87_dialog_content = "긴장 안 해도 돼. 자, 내 손 잡으렴.",
  ui_story_5051_50510701_88_dialog_content = "(미아, 역시 긴장하고 있는 것 같네.)",
  ui_story_5051_50510701_89_dialog_content = "(퍼레이드는 좀 더 계속될 텐데, 미아가 잘 참을 수 있을까...?)",
  ui_story_5051_50510701_90_dialog_content = "(원래 「솔라드 가문의 날」은 이렇게 성대하게 개최됐었구나.)",
  ui_story_5051_50510701_91_dialog_content = "(현실의 그 연회도 충분히 화려했지만, 12년 전 이 축제랑은 비교가 안 돼.)",
  ui_story_5051_50510701_92_dialog_content = "(12년 동안 왜 그렇게 변해버린 걸까?)",
  ui_story_5051_50510701_93_dialog_content = "(게다가 오늘 성문에서 마주친 암귀는 절대 우연히 짐에 섞여 든 게 아니었어.)",
  ui_story_5051_50510701_94_dialog_content = "(12년 전 누군가가 기념일을 노려서 몰래 암귀를 백야성에 보낸 거겠지.)",
  ui_story_5051_50510701_95_dialog_content = "(기사단이 잘 대응할 수 있을까? 아니면 더 큰 소동이 벌어질까...?)",
  ui_story_5051_50510701_96_dialog_content = "(휴... 다들 위험해지지 않았으면 좋겠는데.)",
  ui_story_5051_50510701_97_dialog_content = "(...음? 누가 날 계속 쳐다보고 있는 것 같은데?)",
  ui_story_5051_50510701_98_dialog_content = "(아니겠지. 지금 난 고작 평범한 수행원일 뿐이잖아.)",
  ui_story_5051_50510701_99_dialog_content = "(그리고 미즈 로트도 퍼레이드 중에는 두리번거리거나\n대열에서 벗어나지 말라고 했어...)",
  ui_story_5051_50510701_100_dialog_content = "(괜한 생각하지 말자!)",
  ui_story_5051_50510701_101_dialog_content = "PlayerName 씨! 미아 씨! 여기야──!",
  ui_story_5051_50510701_102_dialog_content = "으, 사람이 너무 많아서 시끄럽잖아! 전혀 말이 전해지질 않아!",
  ui_story_5051_50510701_103_dialog_content = "흐아암... 소용없어.",
  ui_story_5051_50510701_104_dialog_content = "네 목소리가 들린다 해도 저 둘이 저기서 빠져나올 수 있을 것 같아?",
  ui_story_5051_50510701_105_dialog_content = "그것도 그렇네요...",
  ui_story_5051_50510701_106_dialog_content = "아니, 근데 제가 사람을 찾고 있는 건 어떻게 알았어요?",
  ui_story_5051_50510701_107_dialog_content = "게다가 그 사람들이 여기 있는지는 어떻게 안 거죠?!",
  ui_story_5051_50510701_108_dialog_content = "나랑 점술 대결한다고 안 했어?",
  ui_story_5051_50510701_109_dialog_content = "내가 이겼네~",
  ui_story_5051_50510701_110_dialog_content = "......",
  ui_story_5051_50510701_111_dialog_content = "<size=45>저, 정말 대단해요!</size>",
  ui_story_5051_50510701_112_dialog_content = "<size=45>절 제자로 받아 주세요!</size>",
  ui_story_5051_50510701_113_dialog_content = "아이... 조용히 해. 시끄러워서 머리가 아프잖아...",
  ui_story_5051_50510701_114_dialog_content = "난 제자는 안 받아. 여기 온 것도 일 좀 돕고 술값이나 벌려던 것뿐이야.",
  ui_story_5051_50510701_115_dialog_content = "오늘 밤이나 내일... 아니면 모레? 실컷 마시다 질리면 집에 갈 거야.",
  ui_story_5051_50510701_116_dialog_content = "그럼 적어도 이름이라도 알려주세요!",
  ui_story_5051_50510701_117_dialog_content = "(그럼 「영원한 기억의 수정」에서 나온 뒤에 찾아가면 되니까요~)",
  ui_story_5051_50510701_118_dialog_content = "뭐, 그래. 아까 술값도 내줬겠다...",
  ui_story_5051_50510701_119_dialog_content = "난 「보아즈」라고 해.",
  ui_story_5051_50510701_120_dialog_content = "어...?",
  ui_story_5051_50510701_121_dialog_content = "<color=#FFB400>엄마</color>?",
  ui_story_5051_50510701_122_dialog_content = "오늘 이 특별한 날을 함께 축하하고자 여기에 모인\n백야성의 온 백성들에게 감사의 뜻을 전한다.",
  ui_story_5051_50510701_123_dialog_content = "솔라드 가문은 백야성 정상의 면류관이자, 백야성의 시작이 되었던 초석이다.",
  ui_story_5051_50510701_124_dialog_content = "비록 우리는 이 팔로 백성들을 지키나, 우리의 손에 쥔 검은 백성들이 만든 것이다.",
  ui_story_5051_50510701_125_dialog_content = "오늘 우리는 이곳에 모여 「솔라드」 가문의 미덕을 노래하고,\n백야성 백성들의 미덕을 노래할 것이다.",
  ui_story_5051_50510701_126_dialog_content = "「솔라드 가문의 날」 축제의 개막을 선언한다!",
  ui_story_5051_50510701_127_dialog_content = "이어서 「결투 의식」을 거행한다.",
  ui_story_5051_50510701_128_dialog_content = "참으로 멋진 개막 인사였습니다. 성주 전하.",
  ui_story_5051_50510701_129_dialog_content = "......",
  ui_story_5051_50510701_130_dialog_content = "보시지요, 이 성대함, 이는 곧 우리 백야성의 힘을 보여주는 것입니다.",
  ui_story_5051_50510701_131_dialog_content = "또한 오직 솔라드 가문만이 이러한 영광에 어울린다고 할 수 있겠지요.",
  ui_story_5051_50510701_132_dialog_content = "오늘 베로니카 공주가 성에 잠입하려던 암귀를 성문에서 처리했다고 들었습니다.",
  ui_story_5051_50510701_133_dialog_content = "견습기사이면서도 정식 기사단원 못지않은 용기를 보였다고 하더군요.",
  ui_story_5051_50510701_134_dialog_content = "기념일을 위해 배치한 호위대가 현장에 도착했을 때\n암귀는 한 마리도 빠짐없이 쓰러졌다고 합니다.",
  ui_story_5051_50510701_135_dialog_content = "기념일의 경비를 맡은 건 카르티마 가문이었지요? 쯧쯧, 어찌 그런...",
  ui_story_5051_50510701_136_dialog_content = "...사소한 일이 아닌가. 입에 담을 필요는 없다.",
  ui_story_5051_50510701_137_dialog_content = "아마 베로니카도 그 점을 알기에 공연히 보고하지 않은 것이겠지.",
  ui_story_5051_50510701_138_dialog_content = "......",
  ui_story_5051_50510701_139_dialog_content = "그리 겸손할 필요는 없지 않은가.",
  ui_story_5051_50510701_140_dialog_content = "이 건은 이미 성안에 알려져 있다네.",
  ui_story_5051_50510701_141_dialog_content = "평소 실력을 감추던 베로니카 공주가 순식간에 암귀를 쓰러트려\n위기를 해결했다고 모두가 알게 되었지.",
  ui_story_5051_50510701_142_dialog_content = "그렇다면 백성들도 그 공주의 용감한 자태를 직접 보고 싶어 하지 않겠나?",
  ui_story_5051_50510701_143_dialog_content = "용감히 나서 약자를 돕는 것은 찬양할 만한 미덕이지.",
  ui_story_5051_50510701_144_dialog_content = "허나 젊은 나이부터 무작정 남의 앞에 나서는 습관을 들이는 것은 좋지 않다.",
  ui_story_5051_50510701_145_dialog_content = "드러나는 재주에만 심취해서는 큰 그릇이 될 수 없으니 말이야.",
  ui_story_5051_50510701_146_dialog_content = "그렇게 말씀하시면 안 되지요!",
  ui_story_5051_50510701_147_dialog_content = "베로니카 공주는 사람됨이 겸손해 명성이 잘 전해지지 않았을 뿐입니다.",
  ui_story_5051_50510701_148_dialog_content = "반면 카렌 공주는 어려서부터 제왕학의 기재로 칭송받고 있지요.",
  ui_story_5051_50510701_149_dialog_content = "몇 년 후면 카렌 공주는 더욱 두각을 나타낼 것입니다.\n그렇게 되면 베로니카 공주의 장녀로서의 위엄은...",
  ui_story_5051_50510701_150_dialog_content = "트로이 공작! 후계문제는 우리가 멋대로 참견할 일이 아닐세!",
  ui_story_5051_50510701_151_dialog_content = "성주 전하는 재능을 보는 혜안이 있고, 인재를 소중히 여기는 분이네.",
  ui_story_5051_50510701_152_dialog_content = "이번에 공주를 전선에서 불러들인 것도 전하의 생각이 있었기 때문일 것이네.",
  ui_story_5051_50510701_153_dialog_content = "하하, 그것도 그렇지요. 저마다 재능의 쓰임새가 다른 법 아니겠습니까.\n어쩌면 베로니카 공주는 성에서 더 재주를 발휘하실지도 모르겠군요.",
  ui_story_5051_50510701_154_dialog_content = "전하, 부디 무례를 용서하시길.",
  ui_story_5051_50510701_155_dialog_content = "아버님, 저는...",
  ui_story_5051_50510701_156_dialog_content = "베로니카, 준비해라.",
  ui_story_5051_50510701_157_dialog_content = "네? 준비요?",
  ui_story_5051_50510701_158_dialog_content = "「예정」대로 이제 곧 네 차례다.",
  ui_story_5051_50510701_159_dialog_content = "백성들을 기다리게 하지 마라.",
  ui_story_5051_50510701_160_dialog_content = "네... 알겠습니다!",
  ui_story_5051_50510701_161_dialog_content = "두 공작은 오랫동안 내 곁에 있으면서 이젠 내 생각까지 읽게 된 모양이군.",
  ui_story_5051_50510701_162_dialog_content = "베로니카를 피날레 순서에 올려 개막식에서 솔라드 가문의\n다음 세대의 힘을 보여주려 했건만...",
  ui_story_5051_50510701_163_dialog_content = "그대들이 이미 간파했을 줄은 몰랐군.",
  ui_story_5051_50510701_164_dialog_content = "허허... 늙은이도 그냥 해 본 말이었을 뿐인데 말이야.",
  ui_story_5051_50510701_165_dialog_content = "베로니카 공주의 첫 활약이라니, 참으로 기대되는군요!",
  ui_story_5051_50510701_166_dialog_content = "미아, 진짜 할 거야?",
  ui_story_5051_50510701_167_dialog_content = "......",
  ui_story_5051_50510701_168_dialog_content = "난 지금이 도망칠 좋은 기회인 것 같아.",
  ui_story_5051_50510701_169_dialog_content = "원래 우린 조슈아 부인만 만나려던 건데,\n성주님이 나타나서 어쩔 수 없이 여기까지 오게 된 거야.",
  ui_story_5051_50510701_X169_dialog_content = "조슈아 부인한테 동료를 찾아달라고 할 기회는 놓치긴 했지만,\n그래도 우린 되도록 이곳의 일에 얽히지 않는 게 좋아.",
  ui_story_5051_50510701_170_dialog_content = "마, 맞아... 그만 가자...",
  ui_story_5051_50510701_171_dialog_content = "관람석의 저 사람은 그저 환영일 뿐이지, 아버님이 아니야...\n거절해도 괜찮을 거야... 화내지 않으실 테니까...",
  ui_story_5051_50510701_X171_dialog_content = "베로니카, 내가 몇 번이나 말했느냐.\n너는 전투의 재능이 없다. 그러니 연습 같은 건 하지 않아도 된단 말이다.",
  ui_story_5051_50510701_X172_dialog_content = "베로니카, 어째서 다른 사람들과 인사를 못 하는 것이냐.\n너는 이제 열 살이나 되었다. 더는 갓난아이가 아니란 말이다.",
  ui_story_5051_50510701_X173_dialog_content = "기사단에 들어가겠다고?\n베로니카, 나는 네가 남보다 뛰어나길 바라지 않는다.\n그저 네 어머니를 걱정하게 만들지 말라는 것이다!",
  ui_story_5051_50510701_172_dialog_content = "미아...?",
  ui_story_5051_50510701_173_dialog_content = "(미아가 갑자기 왜 떨기 시작했지? 설마 아버지의 명령을 거역하는 게 무서운 건가?)",
  ui_story_5051_50510701_174_dialog_content = "(만약 그런 거라면... 지금 미아를 억지로 데리고 떠나는 건\n미아한테 더 큰 부담만 주게 될 거야.)",
  ui_story_5051_50510701_175_dialog_content = "(이제 막 병이 호전됐는데, 그럴 순 없어!)",
  ui_story_5051_50510701_176_dialog_content = "-",
  ui_story_5051_50510701_177_dialog_content = "미아, 너 결투에 나가고 싶어?",
  ui_story_5051_50510701_178_dialog_content = "나, 나? 난 다 괜찮아...\nPlayerName, 넌 어떻게 생각해? 내가 참가하는 게 맞을까?",
  ui_story_5051_50510701_179_dialog_content = "결투에 참가해서 네 상태가 좋아질 수 있다면 그렇게 하자.",
  ui_story_5051_50510701_180_dialog_content = "응? 아... 내, 내 몸이 또...",
  ui_story_5051_50510701_181_dialog_content = "-",
  ui_story_5051_50510701_182_dialog_content = "-",
  ui_story_5051_50510701_183_dialog_content = "-",
  ui_story_5051_50510701_184_dialog_content = "-",
  ui_story_5051_50510701_185_dialog_content = "-",
  ui_story_5051_50510701_X180_dialog_content = "미안해... 내가 폐를 끼쳤네...",
  ui_story_5051_50510701_X181_dialog_content = "아니야, 미아. 가족을 찾아주겠다고 연회에 널 데려온 건 나야.\n난 약속했으니까, 널 돌볼 의무가 있어.",
  ui_story_5051_50510701_X182_dialog_content = "만약 결투에 참가해서 네 마음속 매듭을 풀 수 있다면... 해보는 거야!",
  ui_story_5051_50510701_X183_dialog_content = "책임은 내가 질게!",
  ui_story_5051_50510701_X184_dialog_content = "(기껏해야 결투가 끝나고 같이 또 도망치는 정도겠지만...)",
  ui_story_5051_50510701_X185_dialog_content = "PlayerName... 네가 상냥하고 좋은 사람인 건 알아.\n하지만 왜 나한테 이렇게...",
  ui_story_5051_50510701_X186_dialog_content = "우린 친구니까.",
  ui_story_5051_50510701_X187_dialog_content = "응...? 친구?",
  ui_story_5051_50510701_X188_dialog_content = "친구끼리 서로 돕고, 서로가 건강하고 행복하길 바라는 건 당연한 일이잖아.",
  ui_story_5051_50510701_X189_dialog_content = "..................",
  ui_story_5051_50510701_X190_dialog_content = "내, 내 말이 이상해?",
  ui_story_5051_50510701_X191_dialog_content = "헤헤... 아주 조금?",
  ui_story_5051_50510701_X192_dialog_content = "뭐가 이상한데...?",
  ui_story_5051_50510701_X193_dialog_content = "바바 야가 말고는 아무도 날 친구로 여겨준 적이 없었거든.",
  ui_story_5051_50510701_X194_dialog_content = "다들 날 「공주 전하」 아니면 「불쌍한 미아」라고 여겼으니까...",
  ui_story_5051_50510701_X195_dialog_content = "PlayerName, 정말 내가 결투에 나가도 될까?",
  ui_story_5051_50510701_X196_dialog_content = "응, 그래도 돼.",
  ui_story_5051_50510701_X197_dialog_content = "고마워... 반드시 네 믿음을 저버리지 않을게!",
  ui_story_5051_50510701_X198_dialog_content = "...참, 무대에 올라 결투를 하면 주변의 이목을 집중시킬 수 있어.",
  ui_story_5051_50510701_X199_dialog_content = "그동안 PlayerName 넌 관람석에서 아버님과 다른 사람들을 찾아봐 줘.",
  ui_story_5051_50510701_X200_dialog_content = "그러면 어머님의 도움 없이도 우리 일행을 찾을 수 있을 거야.",
  ui_story_5051_50510701_X201_dialog_content = "그렇게 생각하면 결투에 참가하는 것도 나쁘지 않은 결정 같네...",
  ui_story_5051_50510701_X202_dialog_content = "맞아! 미아 너도 이제 내 맹목적인 낙관주의를 다 배운 모양이네, 아하하.",
  ui_story_5051_50510701_X203_dialog_content = "베로니카 공주님, 결투가 곧 시작될 겁니다. 이쪽으로 오시지요.",
  ui_story_5051_50510701_X204_dialog_content = "알겠어. 지금 바로 갈게.",
  ui_story_5051_50510701_X205_dialog_content = "그럼... 나 갈게...!",
  ui_story_5051_50510701_X206_dialog_content = "응, 나도 응원할게!",
  ui_story_5051_50510701_186_dialog_content = "미아, 힘내. 만약 정말 못 이길 것 같으면...",
  ui_story_5051_50510701_187_dialog_content = "만약 공주님께서 열세에 처하신다면, 제가 적당히 봐드리겠습니다.",
  ui_story_5051_50510701_188_dialog_content = "음? 당신은...",
  ui_story_5051_50510701_189_dialog_content = "베로니카 공주 전하, 저는 잠시 후 전하와 결투를 펼칠 경비병입니다.",
  ui_story_5051_50510701_190_dialog_content = "성주님께서 이미 사람을 보내 당부하셨습니다.\n저는 공주 전하의 안전을 보장하면서 대련에 임할 것입니다.",
  ui_story_5051_50510701_191_dialog_content = "무기도 이쪽에 있는 검으로 바꿔 주시지요.\n연습용 검이니 다치실 일은 없을 겁니다.",
  ui_story_5051_50510701_192_dialog_content = "게다가 오늘은 「솔라드 가문의 날」 개막식인 이상,\n물론 공주 전하가 망신을 사게 만들 순 없습니다.",
  ui_story_5051_50510701_193_dialog_content = "경기에서는 서로 손발을 맞춰서 절 쓰러트리시는 척을 하시면 됩니다.",
  ui_story_5051_50510701_194_dialog_content = "쓰러트리는... 척...?",
  ui_story_5051_50510701_195_dialog_content = "그러니까 진짜 대결이 아니라는 거야...?",
  ui_story_5051_50510701_196_dialog_content = "그냥 연회의 접대처럼... 연기를 할 뿐이라는 거야...?",
  ui_story_5051_50510701_197_dialog_content = "베로니카, 내가 몇 번이나 말했느냐.\n너는 전투의 재능이 없다. 그러니 연습 같은 건 하지 않아도 된단 말이다.",
  ui_story_5051_50510701_198_dialog_content = "베로니카, 어째서 다른 사람들과 인사를 못 하는 것이냐.\n너는 이제 열 살이나 되었다. 더는 갓난아이가 아니란 말이다.",
  ui_story_5051_50510701_199_dialog_content = "기사단에 들어가겠다고?\n베로니카, 나는 네가 남보다 뛰어나길 바라지 않는다.\n그저 네 어머니를 걱정하게 만들지 말라는 것이다!",
  ui_story_5051_50510701_200_dialog_content = "미아! 정신 차려!",
  ui_story_5051_50510701_201_dialog_content = "PlayerName...",
  ui_story_5051_50510701_202_dialog_content = "미아, 널 증명하기 위해서 아버지가 손을 내밀 때까지 기다릴 필요는 없어.",
  ui_story_5051_50510701_203_dialog_content = "성주는 큰 권력을 가진 자리지만, 그렇다고 네 모든 걸 간섭할 수 있는 건 아냐.",
  ui_story_5051_50510701_204_dialog_content = "미아 네가 무슨 기억을 떠올렸는진 모르지만...",
  ui_story_5051_50510701_205_dialog_content = "지금의 넌 이미 12년 전의 네가 아니야.",
  ui_story_5051_50510701_206_dialog_content = "......",
  ui_story_5051_50510701_207_dialog_content = "너도 분명히 짜 맞춘 「승리」는 받아들일 수 없을 거라 생각해.",
  ui_story_5051_50510701_208_dialog_content = "그럼 실력으로 모두한테 보여주면 돼.\n네가 네 힘으로 진정한 「승리」를 쟁취할 수 있다는 걸 말이야.",
  ui_story_5051_50510701_209_dialog_content = "하지만 상대는 이미...",
  ui_story_5051_50510701_210_dialog_content = "상대가 진지하게 안 하면, 몰아붙여서 본실력을 꺼낼 수밖에 없게 만들면 돼!",
  ui_story_5051_50510701_211_dialog_content = "몰아붙여? 으... 저 사람이 전력을 다하게... 내가 할 수 있을까?",
  ui_story_5051_50510701_212_dialog_content = "당연히 할 수 있지! 아까 그 사람들도 말했잖아.\n기사단이 오기 전에 네가 암귀를 쓰러트린 건 이미 온 백야성에 알려졌어.",
  ui_story_5051_50510701_213_dialog_content = "평범한 경비병이 미아 네 상대가 될 리가 없잖아!",
  ui_story_5051_50510701_214_dialog_content = "크흠. 저기... 두 분, 저 아직 여기 있습니다만...",
  ui_story_5051_50510701_215_dialog_content = "아, 미안해요... 아하하하...",
  ui_story_5051_50510701_216_dialog_content = "이미 들은 이상, 그럼 우리도 확실하게 말해둘게요.",
  ui_story_5051_50510701_217_dialog_content = "미아, 준비됐어?",
  ui_story_5051_50510701_218_dialog_content = "PlayerName 넌 날 그렇게나 믿어주는 거구나...\n내 힘을 믿어준 그 정도로 믿어준 사람은 네가 처음이야!",
  ui_story_5051_50510701_219_dialog_content = "응! 준비됐어.",
  ui_story_5051_50510701_220_dialog_content = "그렇다면──",
  ui_story_5051_50510701_221_dialog_content = "「만물은 백야 아래에, 용감한 전사여. 그대에게 결투를 신청한다!」",
  ui_story_5051_50510701_222_dialog_content = "「그대는 검을 쥘 것인가, 아니면 존엄을 내려놓을 것인가.」",
  ui_story_5051_50510701_223_dialog_content = "「도전을 받겠다면, 서로 이곳에서 목숨을 잃더라도 원망하지 않도록 하자!」",
  ui_story_5051_50510701_224_dialog_content = "목숨까진 좀 오버였나...",
  ui_story_5051_50510701_225_dialog_content = "맞습니다. 좀 봐주십쇼... 저도 그 정도까진 좀...",
  ui_story_5051_50510701_226_dialog_content = "소, 소설 속에 그런 대사가 있길래 그냥 해본 말이야...",
  ui_story_5051_50510701_227_dialog_content = "휴... 알겠습니다. 쉽게 죽은 척이나 항복은 하지 않겠다고 약속하죠.",
  ui_story_5051_50510701_228_dialog_content = "다만 공주 전하께서 정말로 절 이길 수 없게 되면 순순히 항복하겠습니다.\n성주님의 명령을 어길 수는 없으니까요.",
  ui_story_5051_50510701_229_dialog_content = "응, 고마워!",
  ui_story_5051_50510701_230_dialog_content = "그럼 이 검은...",
  ui_story_5051_50510701_231_dialog_content = "미아가 저 검을 쓰는 게 좋겠어.",
  ui_story_5051_50510701_232_dialog_content = "그래야죠, 공주님이 자기 몸에 상처를 주는 일은 없어야 하니까요.",
  ui_story_5051_50510701_233_dialog_content = "전 미아가 당신을 다치게 할까 봐 그러는 거예요!",
  ui_story_5051_50510701_234_dialog_content = "네... 네?",
  ui_story_5051_50510701_235_dialog_content = "그것도 그렇네.",
  ui_story_5051_50510701_236_dialog_content = "그런데 아까부터 「미아」라고 부르시는데...",
  ui_story_5051_50510701_237_dialog_content = "지금 제 눈앞의 저돌적인 아가씨가 정말 그 가녀린 베로니카 공주님이 맞나요?",
  ui_story_5051_50510701_238_dialog_content = "다, 당연하죠! 「미아」는 그냥...",
  ui_story_5051_50510701_239_dialog_content = "우리끼리만 부르는 별명이야!",
  ui_story_5051_50510701_240_dialog_content = "그, 그렇군요...",
  ui_story_5051_50510701_241_dialog_content = "자, 이제 슬슬 시간이 다 됐습니다.\n잠시 뒤 대련장에서 뵙겠습니다, 공주 전하.",
  ui_story_5051_50510701_242_dialog_content = "알겠어. 절대 봐주지 말고 끝까지 싸워줘...!",
  ui_story_5051_50510701_243_dialog_content = "부, 분부대로 하겠습니다...",
  ui_story_5051_50510701_244_dialog_content = "(난 그저 상관이 시킨 일을 하러 온 건데...\n왠지 억지로 청춘 로맨스 영화를 본 기분이란 말이지...)",
  ui_story_5051_50510802_1_dialog_content = "(이 밀려오는 파도 같은 함성, 어디선가 들어본 것 같은데.)",
  ui_story_5051_50510802_2_dialog_content = "(아무래도 식전이 시작된 것 같군.)",
  ui_story_5051_50510802_3_dialog_content = "(그럼 이제 「영원한 기억의 수정」을 가지러 가 볼까...)",
  ui_story_5051_50510802_4_dialog_content = "거기 당신, 잠깐 서 봐.",
  ui_story_5051_50510802_5_dialog_content = "(쳇, 경비병이 아직도 있었다니!)",
  ui_story_5051_50510802_6_dialog_content = "신분을 밝혀라.",
  ui_story_5051_50510802_7_dialog_content = "신분 말입니까? 훈작사 칼렙 마그누스입니다만, 이걸로 부족합니까?",
  ui_story_5051_50510802_8_dialog_content = "칼렙 마그누스 경...?!",
  ui_story_5051_50510802_9_dialog_content = "아니지, 칼렙 경은 이미 며칠 전에 공작부인 전하를 찾아오셨는데...",
  ui_story_5051_50510802_10_dialog_content = "확실히 꽤 비슷하긴 하지만... 머리도 그렇게 안 길고, 체형도 달랐어!",
  ui_story_5051_50510802_11_dialog_content = "침입자! 순순히 투항...",
  ui_story_5051_50510802_12_dialog_content = "소리 지르지 마세요. 다른 병사까지 달려오면 곤란하니까요.",
  ui_story_5051_50510802_13_dialog_content = "(벌써 두 번째 의외의 전개인가... 오늘은 유독 일이 잘 안 풀리잖아.)",
  ui_story_5051_50510802_14_dialog_content = "(반드시 루미나가 소진되기 전에 「영원한 기억의 수정」을 훔쳐야만 해...)",
  ui_story_5051_50510802_15_dialog_content = "음료수 사 왔어요!",
  ui_story_5051_50510802_16_dialog_content = "응, 왔구나.",
  ui_story_5051_50510802_17_dialog_content = "어~? 왜 하필 해장차야?",
  ui_story_5051_50510802_18_dialog_content = "지금 술에 취해서 계속 저한테 제대로 얘기를 안 해 주시잖아요...",
  ui_story_5051_50510802_19_dialog_content = "그러게 왜 갑자기 울면서 껴안아가지고 옷을 콧물투성이로 만들어?",
  ui_story_5051_50510802_20_dialog_content = "아무튼 상관없어~ 술 마실 거야~",
  ui_story_5051_50510802_21_dialog_content = "아, 알겠어요... 술도 사 왔어요, 여기요.",
  ui_story_5051_50510802_22_dialog_content = "꿀꺽꿀꺽... 캬아~ 맛 좋다! 역시 이거지!",
  ui_story_5051_50510802_23_dialog_content = "이 정도면 이제 점술에 대해 말해줄 마음이 드시나요?",
  ui_story_5051_50510802_24_dialog_content = "음... 좋아. 뭘 듣고 싶어?",
  ui_story_5051_50510802_25_dialog_content = "「영원한 기억의 수정」 속에 들어가는 주문에 대해 얼마나 아세요?",
  ui_story_5051_50510802_26_dialog_content = "왜 주문을 외우고 들어왔는데, 모습도 안 감춰지고,\n게다가 저마다 다른 장소로 흩어진 걸까요...?",
  ui_story_5051_50510802_27_dialog_content = "「영원한 기억의」... 「수정」...?",
  ui_story_5051_50510802_28_dialog_content = "야, 그건 네가 알 리가 없는 지식이야.",
  ui_story_5051_50510802_29_dialog_content = "너 대체 누구야?",
  ui_story_5051_50510802_30_dialog_content = "그러니까 말했잖아요! 당신 딸이라구요! 쟈키니예요!",
  ui_story_5051_50510802_31_dialog_content = "그게 뭔 농담이야~ 쟈키니라고?",
  ui_story_5051_50510802_32_dialog_content = "확실히 내가 집에 잘 안 가긴 하지만... 우리 쟈키니는 아직 걷지도 못할 텐데~",
  ui_story_5051_50510802_33_dialog_content = "갑자기 이렇게 커질 리가 없잖아!",
  ui_story_5051_50510802_34_dialog_content = "저야말로 지금 이 상황이 농담이었으면 좋겠다구요!",
  ui_story_5051_50510802_35_dialog_content = "엄마... 엄마는 신비롭고 위대한... 세상과 거리를 두는 점술사 아니었어요?",
  ui_story_5051_50510802_36_dialog_content = "지금은 왜 그냥 술고래인 거냐구요!",
  ui_story_5051_50510802_37_dialog_content = "너 지금 나보고 술고래라고 했어?",
  ui_story_5051_50510802_38_dialog_content = "북방의 바람처럼 종잡을 수 없는 여자... 보아즈라고 불러!",
  ui_story_5051_50510802_39_dialog_content = "휴...그건 또 뭐냐구요...",
  ui_story_5051_50510802_40_dialog_content = "원래라면 엄마한테 이 상황을 말해선 안 되는 거지만...\n이렇게 된 이상 전 엄마밖에 믿을 사람이 없어요.",
  ui_story_5051_50510802_41_dialog_content = "한 번만 말할 거니까 똑바로 잘 들어요!",
  ui_story_5051_50510802_42_dialog_content = "뭐?",
  ui_story_5051_50510802_43_dialog_content = "우리 엄마... 그러니까 보아즈 씨...",
  ui_story_5051_50510802_44_dialog_content = "당신은 「영원한 기억의 수정」이란 걸 만들었어요.\n그리고 지금 우리가 있는 여긴 바로 「영원한 기억의 수정」 속 세계예요.",
  ui_story_5051_50510802_45_dialog_content = "지금으로부터 12년 뒤엔 이 수정을 가동한 분이 이미 세상을 떠나셨어요.",
  ui_story_5051_50510802_46_dialog_content = "그래서 전 이 세계로 들어오기 위해 엄마가 남긴 노트를 토대로 주문을 만들었어요.",
  ui_story_5051_50510802_47_dialog_content = "근데 이 세계에 들어와 보니까 모습을 숨길 수도 없고,\n일행들이랑도 떨어져 버렸어요...",
  ui_story_5051_50510802_48_dialog_content = "이제 전 어떡하면 좋죠?",
  ui_story_5051_50510802_49_dialog_content = "...그랬구나.",
  ui_story_5051_50510802_50_dialog_content = "이해하셨어요...?",
  ui_story_5051_50510802_51_dialog_content = "너네 엄마는 나랑 동명이인이고, 심지어 내 작품을 표절한 거였네!",
  ui_story_5051_50510802_52_dialog_content = "다들 내 이름은 행운을 가져다준다고 하던데...\n너희 엄마는~ 후훗, 운이 좀 딸렸나 봐~",
  ui_story_5051_50510802_53_dialog_content = "으으... 진짜...",
  ui_story_5051_50510802_54_dialog_content = "이 술고래! 됐으니까 계속 술이나 마셔요!",
  ui_story_5051_50510802_55_dialog_content = "다 잊어버릴 만큼 마시라구요! 저랑 아빠까지 잊어버려요!\n그리고 다시는 돌아오지 마요!",
  ui_story_5051_50510802_56_dialog_content = "야, 너무 심한 말은 하지 마.",
  ui_story_5051_50510802_57_dialog_content = "그러니까 넌 지금 너네 엄마 공책에 쓰여 있는 걸 보고\n「영원한 기억의 수정」에 들어오는 주문을 만들었다는 거지?",
  ui_story_5051_50510802_58_dialog_content = "농담이지? 그런 건 나도 못 해.",
  ui_story_5051_50510802_59_dialog_content = "그런 걸 해낼 수 있다면 그 사람은 전대미문의 천재일걸!",
  ui_story_5051_50510802_60_dialog_content = "처, 천재요...?",
  ui_story_5051_50510802_61_dialog_content = "제가 전대미문의 천재인가요?",
  ui_story_5051_50510802_62_dialog_content = "아하하하하, 내가 너네 엄마였으면 신나서 펄쩍 뛰었을걸!",
  ui_story_5051_50510802_63_dialog_content = "에헤헤... 역시 그렇죠?",
  ui_story_5051_50510802_64_dialog_content = "아니지! 지금 그게 중요한 게 아니잖아요!",
  ui_story_5051_50510802_65_dialog_content = "그래서 저 이제 어떡하냐구요!",
  ui_story_5051_50510802_66_dialog_content = "음... 네가 만들었다는 주문을 좀 들려줘 봐.",
  ui_story_5051_50510802_67_dialog_content = "아, 알겠어요.",
  ui_story_5051_50510802_68_dialog_content = "「아드 프라이테리툼~ 아드 프라이테리툼~ 아드 프라이테리툼!」",
  ui_story_5051_50510802_69_dialog_content = "우리를 저 지난날의 시간으로 인도하라!",
  ui_story_5051_50510802_70_dialog_content = "「아브라하다브라!」",
  ui_story_5051_50510802_71_dialog_content = "이게 다예요...",
  ui_story_5051_50510802_72_dialog_content = "음? 아~ 너 그 주문 틀렸어.",
  ui_story_5051_50510802_73_dialog_content = "네?",
  ui_story_5051_50510802_74_dialog_content = "「아브라하다브라」가 아니라 「아브라카다브라」야.",
  ui_story_5051_50510802_75_dialog_content = "너 뭐야~ 점술사가 그렇게 덜렁대고~",
  ui_story_5051_50510802_76_dialog_content = "아니에요, 엄마가 남긴 공책엔 그렇게 쓰여 있어요! 보세요!",
  ui_story_5051_50510802_77_dialog_content = "어디 보자... 아하하하, 이 사람 글씨 되게 못 쓰네.",
  ui_story_5051_50510802_78_dialog_content = "여긴 무슨 글자를 하늘까지 그어놨어? 이러니까 네가 틀리지.",
  ui_story_5051_50510802_79_dialog_content = "이 사람 이거 취했을 때 쓴 거 아냐?",
  ui_story_5051_50510802_80_dialog_content = "엄마가 쓴 거잖아요!!",
  ui_story_5051_50510802_81_dialog_content = "아하하하...",
  ui_story_5051_50510802_82_dialog_content = "이 주문, 나쁘지 않아~",
  ui_story_5051_50510802_83_dialog_content = "다만 실제로 사용할 땐 상세한 주의사항이 있어.",
  ui_story_5051_50510802_84_dialog_content = "너희 들어올 때~ 손 잡았어?",
  ui_story_5051_50510802_85_dialog_content = "아니요...",
  ui_story_5051_50510802_86_dialog_content = "그러니까 한 곳으로 못 왔지.",
  ui_story_5051_50510802_87_dialog_content = "그래도 일행들한테는 잘 말해 놨어요. 절대 이 세계를 바꾸면 안 된다구요.",
  ui_story_5051_50510802_88_dialog_content = "그럼 큰 문제는 없겠죠...?",
  ui_story_5051_50510802_89_dialog_content = "에이~ 틀렸어~",
  ui_story_5051_50510802_90_dialog_content = "너희가 모습을 숨길 수 없는 한, 그저 숨만 쉬어도 이 세계를 바꾸게 될 거야.",
  ui_story_5051_50510802_91_dialog_content = "뭐라고요...?",
  ui_story_5051_50510802_92_dialog_content = "「영원한 기억의 수정」 속 세계가 너흴 알아차린 시점에서,\n이 세계의 모든 게 너희를 따라서 조정될 거거든.",
  ui_story_5051_50510802_93_dialog_content = "그리고 마지막엔...",
  ui_story_5051_50510802_94_dialog_content = "마지막엔...?",
  ui_story_5051_50510802_95_dialog_content = "이 세계의 일부가 되어, <color=#FFB400>영원히 나갈 수 없게 돼</color>.",
  ui_story_5051_50510802_96_dialog_content = "<size=45>뭐라고요?!</size>",
  ui_story_5051_50510802_97_dialog_content = "어머, 조용, 조용히 좀 해...",
  ui_story_5051_50510802_98_dialog_content = "그럼 지금이라도 어떻게든 될까요? 앞으로 얼마나 시간이 남았죠?",
  ui_story_5051_50510802_99_dialog_content = "음... 「영원한 기억의 수정」이 저장할 수 있는 시간은 대략 하루니까...",
  ui_story_5051_50510802_100_dialog_content = "오늘 하루가 끝나지 않으면 아직 괜찮아~ 아마도~",
  ui_story_5051_50510802_101_dialog_content = "그럼 아직 시간이 있네요! 얼른 일행들이랑 합류해서 밖으로 나가야겠어요!",
  ui_story_5051_50510802_102_dialog_content = "고마워요 엄마! 안녕히 계세요! 언젠가 꼭 제가 잡아서 집에 끌고 갈 거예요!",
  ui_story_5051_50510802_103_dialog_content = "어? 잠깐만, 너 어디 가?",
  ui_story_5051_50510802_104_dialog_content = "으앗?! 왜, 왜 이래요? 저 이제 술 사줄 돈도 없다구요!",
  ui_story_5051_50510802_105_dialog_content = "너, 벌써 반나절 동안 사람 찾아다녔지?",
  ui_story_5051_50510802_106_dialog_content = "내가 안 도와줬으면... 한 명도 못 찾았을 거 아냐?",
  ui_story_5051_50510802_107_dialog_content = "아... 맞아요...",
  ui_story_5051_50510802_108_dialog_content = "으음~ 그럼 너네 엄마랑 이름이 같은 인연을 봐서 좀 도와줄게.",
  ui_story_5051_50510802_109_dialog_content = "내가 점술을 쓰는 법을 지도해 줄게.",
  ui_story_5051_50510802_110_dialog_content = "진짜요?!",
  ui_story_5051_50510802_111_dialog_content = "그래그래... 자, 내 마음이 바뀌기 전에 얼른 시작하자.",
  ui_story_5051_50510901_1_dialog_content = "<anim type=Shake><size=32>......</size></anim>",
  ui_story_5051_50510901_2_dialog_content = "<anim type=Shake><size=32>다...</size></anim>",
  ui_story_5051_50510901_3_dialog_content = "<anim type=Shake><size=32>니...</size></anim>",
  ui_story_5051_50510901_4_dialog_content = "<anim type=Shake><size=32>다니엘...</size></anim>",
  ui_story_5051_50510901_5_dialog_content = "<anim type=Shake><size=32>베로니카... 카렌...</size></anim>",
  ui_story_5051_50510901_6_dialog_content = "<anim type=Shake><size=37>다니엘... 베로니카... 카렌...</size></anim>",
  ui_story_5051_50510901_7_dialog_content = "<anim type=Shake><size=42>다니엘! 베로니카! 카렌!</size></anim>",
  ui_story_5051_50510901_8_dialog_content = "<color=#e8d9bb>쿠르르릉──!</color>",
  ui_story_5051_50510901_9_dialog_content = "으앗?!",
  ui_story_5051_50510901_10_dialog_content = "PlayerName 님, 왜 그러시죠?",
  ui_story_5051_50510901_11_dialog_content = "갑자기 안색이 나빠지신 것 같은데요?",
  ui_story_5051_50510901_12_dialog_content = "아, 아무것도 아니에요... 방금 천둥소리에 좀 놀란 거예요.",
  ui_story_5051_50510901_13_dialog_content = "천둥이요?",
  ui_story_5051_50510901_14_dialog_content = "아침에도 한 번 들었는데, 방금 건 아침 때보다 훨씬 컸거든요.",
  ui_story_5051_50510901_15_dialog_content = "아마 곧 폭우가 오려는 모양이네요.",
  ui_story_5051_50510901_16_dialog_content = "카렌은 천둥소리 같은 거 못 들었는데.",
  ui_story_5051_50510901_17_dialog_content = "어? 방금 소리 엄청 컸는데, 못 들었어?",
  ui_story_5051_50510901_18_dialog_content = "정말 들렸어도 카렌은 무서워하지 않아.",
  ui_story_5051_50510901_19_dialog_content = "아하하, 카렌 넌... 아니, 카렌 공주님은 참 용감한 꼬마 친구구나.",
  ui_story_5051_50510901_20_dialog_content = "카렌은 이제 어린애가 아냐.",
  ui_story_5051_50510901_21_dialog_content = "......",
  ui_story_5051_50510901_22_dialog_content = "어라... 카렌?",
  ui_story_5051_50510901_23_dialog_content = "(또 조슈아 부인한테 가버렸네.)",
  ui_story_5051_50510901_24_dialog_content = "(아까 그 눈빛... 현실의 카렌이랑 정말 똑같잖아.)",
  ui_story_5051_50510901_25_dialog_content = "카렌 공주님은 항상 저런 모습이랍니다. 어린애 취급을 하면 언짢아하시죠.",
  ui_story_5051_50510901_26_dialog_content = "다만 신기하네요. 카렌 공주님이 흥미를 느낀 사람은 당신이 처음이거든요.",
  ui_story_5051_50510901_27_dialog_content = "흥미요?",
  ui_story_5051_50510901_28_dialog_content = "못 느끼셨나요?\n카렌 공주님은 아까부터 근처에서 한참 동안 당신을 관찰하셨거든요.",
  ui_story_5051_50510901_29_dialog_content = "설마 아직도 절 경계하는 건 아니겠죠...?",
  ui_story_5051_50510901_30_dialog_content = "아, 미아... 아니, 베로니카는 아직 경기 중인데,\n이런 중요한 순간에 정신을 다른 데 팔았네요!",
  ui_story_5051_50510901_31_dialog_content = "이게 바로 내 힘이야!",
  ui_story_5051_50510901_32_dialog_content = "으윽... 콜록콜록.",
  ui_story_5051_50510901_33_dialog_content = "베로니카 공주님께서는 아직 전력을 다하지 않으신 것 같습니다만,\n이미 우위에 서 계시는군요.",
  ui_story_5051_50510901_34_dialog_content = "불과 얼마 동안 못 뵌 사이에 베로니카 공주님의 검술이\n이 정도로 발전했다니 놀랍네요.",
  ui_story_5051_50510901_35_dialog_content = "정말 궁금하네요.\nPlayerName 님이 공주님께 뭔가 신비한 비약이라도 드린 걸까요?",
  ui_story_5051_50510901_36_dialog_content = "(미아는 오는 동안 줄곧 자기 힘을 믿으려 하지 않았어.)",
  ui_story_5051_50510901_37_dialog_content = "(과거의 미아는 전투에 능숙하지 못하다는 인상을 항상 주변 사람들에게 줬던 걸까?)",
  ui_story_5051_50510901_38_dialog_content = "말씀해 주지 않으시는 건가요?\n아무래도 또 제가 알 수 없는 비밀인 모양이네요.",
  ui_story_5051_50510901_39_dialog_content = "사실 딱히 비밀 같은 건 아니에요.",
  ui_story_5051_50510901_40_dialog_content = "베로니카는 항상 강했어요. 그저 과거의 베로니카는 그걸 몰랐을 뿐이에요.",
  ui_story_5051_50510901_41_dialog_content = "호오?",
  ui_story_5051_50510901_42_dialog_content = "우와... 위험했어. 방금 공주 전하의 공격이 저 경비병한테 맞을 뻔했다고.",
  ui_story_5051_50510901_43_dialog_content = "검끼리 부딪치는 불꽃까지 여기서 뚜렷하게 보여... 진짜 진검승부네!",
  ui_story_5051_50510901_44_dialog_content = "베로니카 공주님, 저희도 응원할게요!",
  ui_story_5051_50510901_45_dialog_content = "우와──!",
  ui_story_5051_50510901_46_dialog_content = "공주님의 검술에 백성들이 환호성과 박수를 보내고 있네요.",
  ui_story_5051_50510901_47_dialog_content = "아, 그럼 조금 전에 들었다는 천둥소리는 혹시 박수 소리였던 건 아닐까요?",
  ui_story_5051_50510901_48_dialog_content = "그럴까요...",
  ui_story_5051_50510901_49_dialog_content = "(어라, 잠깐만!)",
  ui_story_5051_50510901_50_dialog_content = "(...뭐지? 방금 등 뒤에서 한기가 확 느껴졌는데?)",
  ui_story_5051_50510901_51_dialog_content = "(누군가 있어! 누가 날 보고 있어!)",
  ui_story_5051_50510901_52_dialog_content = "(카렌은 아냐... 딸의 시합을 보는 솔라드 씨랑 조슈아 부인도 아니야...)",
  ui_story_5051_50510901_53_dialog_content = "(이 느낌은 설마...)",
  ui_story_5051_50510901_54_dialog_content = "PlayerName 님, 어디 가시나요?",
  ui_story_5051_50510901_55_dialog_content = "자, 잠깐 화장실 좀 다녀올게요.",
  ui_story_5051_50510901_56_dialog_content = "그럼 제가 안내해 드릴게요.",
  ui_story_5051_50510901_57_dialog_content = "혼자 갈 수 있어요!",
  ui_story_5051_50510901_58_dialog_content = "(어머, PlayerName 님... 의외로 발이 빠르시군요.)",
  ui_story_5051_50510901_59_dialog_content = "(베로니카 공주님의 이 친구분... 정말 재미있는 분이시네요.)",
  ui_story_5051_50510901_60_dialog_content = "시선은 이쪽에서 느껴졌던 것 같은데...",
  ui_story_5051_50510901_61_dialog_content = "크흠.",
  ui_story_5051_50510901_62_dialog_content = "성주님! 진짜로 성주님이었군요!",
  ui_story_5051_50510901_63_dialog_content = "역시 PlayerName 그대의 감각은 날카롭군.",
  ui_story_5051_50510901_64_dialog_content = "여긴 어떻게 찾으신 거예요?",
  ui_story_5051_50510901_65_dialog_content = "젊은이들은 번화한 곳을 좋아하지. 혹시나 하여 와본 것이다.",
  ui_story_5051_50510901_66_dialog_content = "허나 그대가 이토록 빨리 <color=#FFB400>이 세계의 나</color>와 만났으리라고는 생각하지 못했다만.",
  ui_story_5051_50510901_67_dialog_content = "그건...",
  ui_story_5051_50510901_68_dialog_content = "그대도 이미 알고 있겠지.\n우리는 「영원한 기억의 수정」이 기록한 역사 속으로 빨려 들어왔다.",
  ui_story_5051_50510901_69_dialog_content = "본래라면 우리는 모습을 숨기고 이 세계를 관찰할 수 있어야 할 터이거늘,\n지금 우리는 이 세계의 다른 이들의 눈에 보이고 있다.",
  ui_story_5051_50510901_70_dialog_content = "저도 그게 이상했어요. 대체 어떻게 된 걸까요?",
  ui_story_5051_50510901_71_dialog_content = "젊은이여, 지금은 그것을 생각하기에는 이미 늦은 때다.",
  ui_story_5051_50510901_72_dialog_content = "문제는 이미 벌어졌다. 지금 시급한 일은 발생할 수 있는 위기를 피하고,\n해결 방법을 찾는 것이다.",
  ui_story_5051_50510901_73_dialog_content = "북방의 사절은 수정 속 역사를 바꾸려 해서는 안 된다고 말했다.\n그렇지 않으면 상상할 수 없는 결과가 있을 거라고도 했었지.",
  ui_story_5051_50510901_74_dialog_content = "이 세계와 얽히지 않으려면 우리는 조심해서 행동해야 한다.",
  ui_story_5051_50510901_75_dialog_content = "저랑 미아도 어쩔 수 없었어요. 성안에서 일행을 찾으려다 보니까...",
  ui_story_5051_50510901_76_dialog_content = "......",
  ui_story_5051_50510901_77_dialog_content = "성주님? 왜 그러세요?",
  ui_story_5051_50510901_78_dialog_content = "미아가... 저들과 만났나?",
  ui_story_5051_50510901_79_dialog_content = "「저들」이요...?",
  ui_story_5051_50510901_80_dialog_content = "누굴 가리키는지 알고 있을 텐데.",
  ui_story_5051_50510901_81_dialog_content = "크흠... 조슈아 공작부인, 꼬마 카렌, 그리고 이곳의 「성주님」 말씀이시라면...",
  ui_story_5051_50510901_82_dialog_content = "네, 다들 미아를 받아줬어요. 지금은 「베로니카」라고 부르고 있어요.",
  ui_story_5051_50510901_83_dialog_content = "미아의 현재 모습은 확실히 그 당시와도 다를 것이 없지.",
  ui_story_5051_50510901_84_dialog_content = "그럼... 인정하시는 거군요.",
  ui_story_5051_50510901_85_dialog_content = "미아가 바로 「베로니카」 공주이자 성주님의 딸인 거죠?",
  ui_story_5051_50510901_86_dialog_content = "...이 세계는 이미 우리의 행동에 의해 어지럽혀졌다.",
  ui_story_5051_50510901_87_dialog_content = "게다가 어째서 그대는 미아에게 위험을 무릅쓰고 경비병과 겨루게 한 것이냐.",
  ui_story_5051_50510901_88_dialog_content = "미아가 다치기라도 한다면 어떻게 할지는 생각했느냐.",
  ui_story_5051_50510901_89_dialog_content = "미아는 백야성 성주의 딸이지만, 계속 정신이 나간 환자 취급을 받으면서\n움브라톤에 숨겨져 있었어요...",
  ui_story_5051_50510901_90_dialog_content = "미아의 아버님은 미아가 움브라톤에서 다치기라도 하면 어떡할지 생각하셨을까요?",
  ui_story_5051_50510901_91_dialog_content = "젊은이여, 명심해라.",
  ui_story_5051_50510901_92_dialog_content = "일의 전모를 모르는 채로는 쉽게 평하지 않는 편이 좋을 것이다.",
  ui_story_5051_50510901_93_dialog_content = "죄송해요. 확실히 전 두 사람 사이에 무슨 일이 있었는지 몰라요.",
  ui_story_5051_50510901_94_dialog_content = "하지만 솔라드 씨도 미아의 진짜 힘을 모르시는 것 같은데요.",
  ui_story_5051_50510901_95_dialog_content = "흐음?",
  ui_story_5051_50510901_96_dialog_content = "대단해!",
  ui_story_5051_50510901_97_dialog_content = "베로니카 공주님! 와아아──! 베로니카 공주님!",
  ui_story_5051_50510901_98_dialog_content = "보세요. 지금 모두가 미아의 실력에 환호하고 있어요.",
  ui_story_5051_50510901_99_dialog_content = "예전의 미아는 전투에 능하지 못했다.",
  ui_story_5051_50510901_100_dialog_content = "허나 지금의 미아는 저토록 강대한 힘을 지니게 된 것인가...",
  ui_story_5051_50510901_101_dialog_content = "미아는 왠지 이번 기회에 자기가 더 많은 걸 할 수 있다고\n솔라드 씨한테 보여주고 싶은 것 같았어요.",
  ui_story_5051_50510901_102_dialog_content = "하지만 지금은 때가 아니다.",
  ui_story_5051_50510901_103_dialog_content = "PlayerName, 어떻게 해서든 반드시 미아가 이 경기를 끝내게 해라.",
  ui_story_5051_50510901_104_dialog_content = "왜죠? 이해가 안 돼요. 이제 곧 미아가 이길 건데요?",
  ui_story_5051_50510901_105_dialog_content = "여전히 미아를 못 믿으시는 건가요?",
  ui_story_5051_50510901_106_dialog_content = "PlayerName, 당시 의식 중에 무슨 일이 일어났는지 알고 있나?",
  ui_story_5051_50510901_107_dialog_content = "네?",
  ui_story_5051_50510901_108_dialog_content = "베로니카 공주님, 지금부터는 저도 전력을 다하겠습니다!",
  ui_story_5051_50510901_109_dialog_content = "응... 봐주지 마.",
  ui_story_5051_50510901_110_dialog_content = "이얍!",
  ui_story_5051_50510901_111_dialog_content = "<color=#e8d9bb>채앵──!</color>",
  ui_story_5051_50510901_112_dialog_content = "아니... 이것까지 받아내신단 말입니까?",
  ui_story_5051_50510901_113_dialog_content = "...아슬아슬했어.",
  ui_story_5051_50510901_114_dialog_content = "(방금 그 공격, 엄청난 힘이었어. 자칫하면 못 버틸 뻔했어.)",
  ui_story_5051_50510901_115_dialog_content = "(PlayerName... 날 봐주고 있을까?)",
  ui_story_5051_50510901_116_dialog_content = "(어, 어디 간 거야?)",
  ui_story_5051_50510901_117_dialog_content = "(찾았다! 그런데 옆에 있는 사람은...)",
  ui_story_5051_50510901_118_dialog_content = "언니! 위험해!",
  ui_story_5051_50510901_119_dialog_content = "하압──!",
  ui_story_5051_50510901_120_dialog_content = "(어떡하지?! 이, 이건 못 막을 수도 있겠어.)",
  ui_story_5051_50510901_121_dialog_content = "(도망칠까? 아니, 안 돼. 아버님이 보고 계셔... 그 모습을 보신다면...)",
  ui_story_5051_50510901_122_dialog_content = "(그래, 아직 시간은 있어. 힘을 모아서 반격하자!)",
  ui_story_5051_50510901_123_dialog_content = "설마 <color=#FFB400>그걸</color> 꺼내려는 것인가?",
  ui_story_5051_50510901_124_dialog_content = "베로니카...",
  ui_story_5051_50510901_125_dialog_content = "(안 돼! 아버님은 내가 히포카를 소환하는 걸 싫어하셨잖아...\n나 어떻게 이걸 잊고 있었던 거야?)",
  ui_story_5051_50510901_126_dialog_content = "(하지만... 지금 내 손에 모인 힘으로는... 경비병을 다치게 만들고 말 거야.)",
  ui_story_5051_50510901_127_dialog_content = "(어쩌지... 어쩌면 좋지?)",
  ui_story_5051_50510901_128_dialog_content = "(...저기 있는 나무상자는 뭘까? 혹시 저 상자가 이 힘을 받아낼 수 있을까?)",
  ui_story_5051_50510901_129_dialog_content = "(뭐야? 왜 옆으로 달려가는 거지?)",
  ui_story_5051_50510901_130_dialog_content = "(분명히 이제 곧 소환물을 불러낼 수 있었는데!)",
  ui_story_5051_50510901_131_dialog_content = "......",
  ui_story_5051_50510901_132_dialog_content = "베로니카, 앞으로 다시는 네가 불러낸 괴물을 사람들이 보는 일이 없게 해라.",
  ui_story_5051_50510901_133_dialog_content = "히, 히포카는... 괴물이 아니에요.",
  ui_story_5051_50510901_134_dialog_content = "말 머리가 달린 거미에 이름까지 붙인 것이냐?",
  ui_story_5051_50510901_135_dialog_content = "카렌도 자기 백마가 있잖아요...",
  ui_story_5051_50510901_136_dialog_content = "베로니카, 네게는 전투의 재능이 없다. 더는 이 일에 미련을 갖지 마라.",
  ui_story_5051_50510901_137_dialog_content = "아...",
  ui_story_5051_50510901_138_dialog_content = "아무래도 아직 기억하는 모양이로군.",
  ui_story_5051_50510901_139_dialog_content = "미아가 저 나무상자에 부딪히려고 해요!",
  ui_story_5051_50510901_140_dialog_content = "뭐라?!",
  ui_story_5051_50510901_141_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_5051_50510901_142_dialog_content = "<anim type=Shake>크오오오──!</anim>",
  ui_story_5051_50510901_143_dialog_content = "암귀?! 암귀다!",
  ui_story_5051_50510901_144_dialog_content = "장식용 상자에 왜 암귀가 잔뜩 있던 거야?!",
  ui_story_5051_50510901_145_dialog_content = "도망쳐!",
  ui_story_5051_50510901_146_dialog_content = "어...어, 어떻게 된 거야?",
  ui_story_5051_50510901_147_dialog_content = "나, 나 때문이야?",
  ui_story_5051_50510901_148_dialog_content = "<anim type=Shake>그어어!</anim>",
  ui_story_5051_50510901_149_dialog_content = "여, 역시 난 이런 데 나서는 게 아니었어...",
  ui_story_5051_50510901_150_dialog_content = "매번 내가 뭘 하려고 하면... 항상 이런 식이야...",
  ui_story_5051_50510901_151_dialog_content = "항상... 나쁜 결과밖에...",
  ui_story_5051_50510901_152_dialog_content = "기사단에 들어가겠다고?\n베로니카, 나는 네가 남보다 뛰어나길 바라지 않는다.\n그저 네 어머니를 걱정하게 만들지 말라는 것이다!",
  ui_story_5051_50510901_153_dialog_content = "공주 전하, 저희와 함께 싸우실 필요는 없습니다.\n안전한 곳에서 기다려 주시면 됩니다!",
  ui_story_5051_50510901_154_dialog_content = "베로니카, 어떻게 된 거니...?",
  ui_story_5051_50510901_155_dialog_content = "안 돼──!",
  ui_story_5051_50510901_156_dialog_content = "전부... 전부 나 때문이야...",
  ui_story_5051_50510901_157_dialog_content = "적을 피해 물러서라!",
  ui_story_5051_50510901_158_dialog_content = "으엣...?",
  ui_story_5051_50510901_159_dialog_content = "<anim type=Shake>크오오오오!</anim>",
  ui_story_5051_50510901_160_dialog_content = "「지배자의 칼날!」",
  ui_story_5051_50510901_161_dialog_content = "아버님? 지, 진짜 아버님인가요?",
  ui_story_5051_50510901_162_dialog_content = "미아, 괜찮아?",
  ui_story_5051_50510901_163_dialog_content = "PlayerName... 난 괜찮아. 그냥 잠깐 정신이 없었을 뿐이야...",
  ui_story_5051_50510901_164_dialog_content = "정말 괜찮은 게냐?",
  ui_story_5051_50510901_165_dialog_content = "괘, 괜찮아요!",
  ui_story_5051_50510901_166_dialog_content = "좋다. 지금부터 함께 돌파하는 것이다.",
  ui_story_5051_50510901_167_dialog_content = "...처, 처음이에요... 아버님과 함께 싸우는 건...",
  ui_story_5051_50510901_168_dialog_content = "또한...",
  ui_story_5051_50510901_169_dialog_content = "히포카를 소환하고 싶다면 그렇게 해라.",
  ui_story_5051_50510901_170_dialog_content = "아, 아버님?",
  ui_story_5051_50510901_171_dialog_content = "준비는 되었느냐?",
  ui_story_5051_50510901_172_dialog_content = "...네!",
  ui_story_5051_50510901_173_dialog_content = "<color=#e8d9bb>한편</color>",
  ui_story_5051_50510901_174_dialog_content = "저 검은 괴물... 암귀야?!",
  ui_story_5051_50510901_175_dialog_content = "어머님, 카렌이 모두를 지킬 거예요!",
  ui_story_5051_50510901_176_dialog_content = "카렌, 난 우리 카렌이 할 수 있다고 믿어. 하지만 지금은 아니야. 알겠지?",
  ui_story_5051_50510901_177_dialog_content = "...알겠어요.",
  ui_story_5051_50510901_178_dialog_content = "조슈아, 미즈 로트가 그대와 카렌을 지켜줄 테니 어서 피해!",
  ui_story_5051_50510901_179_dialog_content = "다니엘, 나도 같이...",
  ui_story_5051_50510901_180_dialog_content = "안심해, 조슈아.",
  ui_story_5051_50510901_181_dialog_content = "내가 베로니카를 잘 데리고 돌아갈 테니까.",
  ui_story_5051_50510901_182_dialog_content = "그럼 내 말 꼭 지켜요. 두 사람, 반드시 무사히 집으로 돌아와요.",
  ui_story_5051_50510901_183_dialog_content = "<anim type=Shake>크오오──!</anim>",
  ui_story_5051_50510901_184_dialog_content = "「모든 것을 지배한다!」",
  ui_story_5051_50510901_185_dialog_content = "이 녀석들, 벌써 이곳까지 발을 들인 것이냐.",
  ui_story_5051_50510901_186_dialog_content = "흥, 스스로 고통을 자초하는구나.",
  ui_story_5051_50511001_1_dialog_content = "「인웨니이레 에움~ 인웨니이레 에움~ 인웨니이레 에움~」",
  ui_story_5051_50511001_2_dialog_content = "부디 알려주세요. 제가 생각하는 성주님은 지금 어디에 있나요?",
  ui_story_5051_50511001_3_dialog_content = "<size=42>「아브라카다브라!」</size>",
  ui_story_5051_50511001_4_dialog_content = "<color=#e8d9bb>지이잉!</color>",
  ui_story_5051_50511001_5_dialog_content = "우와! 수정구슬이 이렇게 격렬하게 대답해 준 건 처음이에요!",
  ui_story_5051_50511001_6_dialog_content = "그럼 저 진짜로 지금까지 마지막 주문을 잘못 외우고 있었던 거네요?",
  ui_story_5051_50511001_7_dialog_content = "근데 궁금한 게 있어요...",
  ui_story_5051_50511001_8_dialog_content = "왜 주문을 외울 때마다 마지막에 「아브라카다브라」라고 해야 하죠?",
  ui_story_5051_50511001_9_dialog_content = "「아브라카다브라」라는 말에 무슨 특별한 의미라도 있나요?",
  ui_story_5051_50511001_10_dialog_content = "응? 무슨 뜻이었더라...",
  ui_story_5051_50511001_11_dialog_content = "아~ 생각났어~",
  ui_story_5051_50511001_12_dialog_content = "「말 안 들으면 없애버린다」는 뜻이야!",
  ui_story_5051_50511001_13_dialog_content = "하아아?!",
  ui_story_5051_50511001_14_dialog_content = "아하하하하, 너 그렇게 놀라니까 진짜 재미있네, 하하하!",
  ui_story_5051_50511001_15_dialog_content = "지금 저 놀리는 거예요?!",
  ui_story_5051_50511001_16_dialog_content = "<size=30>어릴 적 엄마에 대한 따스한 추억은 설마 내 머릿속에서 멋대로 가공된 거였던건가...</size>",
  ui_story_5051_50511001_17_dialog_content = "야, 뭘 투덜거리고 있어?\n얼른 수정구슬에 답해 주지 않으면 정보가 사라져 버릴 거야.",
  ui_story_5051_50511001_18_dialog_content = "아, 제일 중요한 걸 잊어버릴 뻔했네요!",
  ui_story_5051_50511001_19_dialog_content = "수정구슬의 정보는 그러니까...",
  ui_story_5051_50511001_20_dialog_content = "성주님이랑 PlayerName 씨, 미아 씨가 같은 방향에 있다고?",
  ui_story_5051_50511001_21_dialog_content = "벌써 합류한 모양이네요.",
  ui_story_5051_50511001_22_dialog_content = "...그럼 저 혼자 여기서 한참 시간을 낭비했단 소리잖아요?",
  ui_story_5051_50511001_23_dialog_content = "어떻게 이게 시간 낭비야~?",
  ui_story_5051_50511001_24_dialog_content = "내 특별한 주문을 전부 너한테 가르쳐 줬잖아~",
  ui_story_5051_50511001_25_dialog_content = "아, 그렇네요!",
  ui_story_5051_50511001_26_dialog_content = "그리고 찾는 사람의 위치를 정확하게 점친 것도 이번이 처음이에요!",
  ui_story_5051_50511001_27_dialog_content = "근데...",
  ui_story_5051_50511001_28_dialog_content = "그래서 「아브라카다브라」가 대체 무슨 뜻인데요?",
  ui_story_5051_50511001_29_dialog_content = "아, 머리 아파~",
  ui_story_5051_50511001_30_dialog_content = "맛있는 거 먹여줘야 기억이 날 것 같아.",
  ui_story_5051_50511001_31_dialog_content = "으으, 또요?",
  ui_story_5051_50511001_32_dialog_content = "여기까지 왔으면 이제 괜찮겠지?",
  ui_story_5051_50511001_33_dialog_content = "그래도 좀 더 도망가는 게 좋겠어! 따라와!",
  ui_story_5051_50511001_34_dialog_content = "어라? 왜 갑자기 다들 광장에서 도망치고 있는 거죠?",
  ui_story_5051_50511001_35_dialog_content = "다들 넘어지지 않도록 침착하게 이동해!",
  ui_story_5051_50511001_36_dialog_content = "저기, 기사님! 혹시...",
  ui_story_5051_50511001_37_dialog_content = "흐음?",
  ui_story_5051_50511001_38_dialog_content = "와, 저보다 어리신 것 같네요?",
  ui_story_5051_50511001_39_dialog_content = "무슨 일이지?",
  ui_story_5051_50511001_40_dialog_content = "아, 저기, 지금 광장 쪽에 무슨 일이 있나요?",
  ui_story_5051_50511001_41_dialog_content = "자세한 건 나도 모른다.\n다만 백성들을 대피시키라는 명령이 상부에서 내려왔다.",
  ui_story_5051_50511001_42_dialog_content = "근데 전 광장에 사람을 찾으러 가야 해요!",
  ui_story_5051_50511001_43_dialog_content = "잠깐만, 그 모습...",
  ui_story_5051_50511001_44_dialog_content = "아하, 다들 제가 우리 엄마... 아니, 보아즈 님을 많이 닮았다고 하긴 해요.",
  ui_story_5051_50511001_45_dialog_content = "빨간 머리에 초록색 눈동자... 네가 쟈키니인가?",
  ui_story_5051_50511001_46_dialog_content = "어? 제 이름을 어떻게 아세요?",
  ui_story_5051_50511001_47_dialog_content = "자, 자, 자자자잠깐만요! 설마 당신도 저처럼 실수로 여기 들어와 버린 건가요?",
  ui_story_5051_50511001_48_dialog_content = "미안하지만 무슨 말인지 모르겠다.",
  ui_story_5051_50511001_49_dialog_content = "난 베로니카 공주님의 친구인 PlayerName의 부탁을 받아서,\n당신과 두 남자의 행방을 찾고 있다.",
  ui_story_5051_50511001_50_dialog_content = "맞아요! 저도 PlayerName 씨를 찾던 중이에요!",
  ui_story_5051_50511001_51_dialog_content = "근데 아직 중앙 광장에 있는 것 같더라구요.",
  ui_story_5051_50511001_52_dialog_content = "우선 나를 따라오도록. 상황이 진정되면 데리고 가 주겠다.",
  ui_story_5051_50511001_53_dialog_content = "그래 준다니 고맙긴 하지만...",
  ui_story_5051_50511001_54_dialog_content = "아무래도 이러다간 늦을 것 같거든요. 전 빨리 일행이랑 합류해야 돼요!",
  ui_story_5051_50511001_55_dialog_content = "그럼 당신은 지금 술에 취한 여자를 데리고\n암귀가 날뛰고 있는 구역으로 들어가겠다는 건가?",
  ui_story_5051_50511001_56_dialog_content = "암귀?",
  ui_story_5051_50511001_57_dialog_content = "야야야, 나 안 취했거든? 취한 건 너겠지!",
  ui_story_5051_50511001_58_dialog_content = "음... 확실히 그건 좀 그렇네요.",
  ui_story_5051_50511001_59_dialog_content = "그럼 꼬마 기사님, 이 사람 좀 맡아주실 수 있나요?",
  ui_story_5051_50511001_60_dialog_content = "혼자 광장에 일행을 찾으러 가겠다는 건가?",
  ui_story_5051_50511001_61_dialog_content = "헤헤, 저 이래 봬도 암귀 정도는 무섭지 않거든요.",
  ui_story_5051_50511001_62_dialog_content = "이 기지배가... 배울 거 다 배웠다고 이제 스승도 버리고 도망가려고?",
  ui_story_5051_50511001_63_dialog_content = "이 보아즈 님이 암귀를 무서워할 것 같아?",
  ui_story_5051_50511001_64_dialog_content = "정확한 주문 외우는 법 가르쳐 준 건 정말 고마워요!",
  ui_story_5051_50511001_65_dialog_content = "그리고 짧은 시간이었지만 만날 수 있었던 걸로 이미 만족해요.\n할 수만 있다면...",
  ui_story_5051_50511001_66_dialog_content = "저도 여기서 헤어지고 싶진 않아요.",
  ui_story_5051_50511001_67_dialog_content = "하지만... 친구들을 내버려 둘 순 없어요!",
  ui_story_5051_50511001_68_dialog_content = "저만 아니었다면... 다들 지금 같은 위험에 빠지진 않았을 테니까요.",
  ui_story_5051_50511001_69_dialog_content = "뭔 소린지 모르겠고, 나도 데려가. 꼭 데리고 가!",
  ui_story_5051_50511001_70_dialog_content = "나한테 더 배우기 싫어? 게다가 나 아직 술이 부족하단 말이야!",
  ui_story_5051_50511001_71_dialog_content = "......",
  ui_story_5051_50511001_72_dialog_content = "이런 위기의 순간에도 친구를 생각하다니.\n쟈키니, 당신에게 경의를 표하겠어.",
  ui_story_5051_50511001_73_dialog_content = "솔직히 말하자면 나도 광장에 가서 함께 싸우고 싶다.",
  ui_story_5051_50511001_74_dialog_content = "당신들이 꼭 광장에 가야겠다면, 내가 데려다주겠다.",
  ui_story_5051_50511001_75_dialog_content = "네? 진짜요?",
  ui_story_5051_50511001_76_dialog_content = "따라와라. 마주치는 암귀들은 내가 해치울 테니까!",
  ui_story_5051_50511002_1_dialog_content = "상황은?",
  ui_story_5051_50511002_2_dialog_content = "주변의 암귀는 이미 다 처리한 것 같아요.",
  ui_story_5051_50511002_3_dialog_content = "좋다.",
  ui_story_5051_50511002_4_dialog_content = "이 앞에 지름길이 있다.\n암귀들이 활개 치는 구역을 빠르게 벗어날 수 있을 것이다.",
  ui_story_5051_50511002_5_dialog_content = "너희는 내 뒤를 따라라.",
  ui_story_5051_50511002_6_dialog_content = "네? 지금 가는 건가요?",
  ui_story_5051_50511002_7_dialog_content = "너는 이미 오랜 시간을 싸웠으니 휴식이 필요하다.",
  ui_story_5051_50511002_8_dialog_content = "하지만...",
  ui_story_5051_50511002_9_dialog_content = "「하지만」은 없다.",
  ui_story_5051_50511002_10_dialog_content = "여기서 시간과 힘을 낭비하고 있을 수는 없는 법이다.",
  ui_story_5051_50511002_11_dialog_content = "저, 전 모두를 위해 암귀를 더 쓰러트리고 싶어요...",
  ui_story_5051_50511002_12_dialog_content = "<size=45>그만두고 어서 가지 못하겠느냐!</size>",
  ui_story_5051_50511002_13_dialog_content = "앗...",
  ui_story_5051_50511002_14_dialog_content = "베로니카, 네게는 전투의 재능이 없다. 더는 이 일에 미련을 갖지 마라.",
  ui_story_5051_50511002_15_dialog_content = "......",
  ui_story_5051_50511002_X15_dialog_content = "(미아의 표정이 결투 전이랑 똑같아졌잖아.)",
  ui_story_5051_50511002_X16_dialog_content = "(설마 또 무슨 안 좋은 일이 떠오른 걸까?)",
  ui_story_5051_50511002_16_dialog_content = "미아, 뭔가 떠올랐어?",
  ui_story_5051_50511002_17_dialog_content = "저, 정말 죄송해요!",
  ui_story_5051_50511002_18_dialog_content = "다 제 탓이에요... 전부 제 잘못이에요...",
  ui_story_5051_50511002_19_dialog_content = "성주님, 방금 하신 말씀이 미아를 자극한 건 아닐까요?",
  ui_story_5051_50511002_20_dialog_content = "미아의 병세는 이제 막 좋아졌어요. 너무 심한 자극은 못 견딜 거예요.",
  ui_story_5051_50511002_21_dialog_content = "......",
  ui_story_5051_50511002_22_dialog_content = "-",
  ui_story_5051_50511002_23_dialog_content = "-",
  ui_story_5051_50511002_X21_dialog_content = "가족끼리의 문제인데 제가 참견하면 안 된다는 건 저도 알아요.",
  ui_story_5051_50511002_X22_dialog_content = "하지만 아이가 자기 아버지를 저렇게까지 두려워하는 것도 정상은 아니잖아요!",
  ui_story_5051_50511002_24_dialog_content = "성주님, 미아는 왜 저렇게 성주님을 무서워하는 거죠?",
  ui_story_5051_50511002_25_dialog_content = "성주님이...",
  ui_story_5051_50511002_26_dialog_content = "미아를 줄곧 움브라톤에 버려두고, 관심을 기울이지 않았기 때문인가요?",
  ui_story_5051_50511002_27_dialog_content = "<size=45>나는 단 하루도 결코 미아를 저버린 적이 없었다!</size>",
  ui_story_5051_50511002_28_dialog_content = "...이 일은 그대가 알 필요 없다.",
  ui_story_5051_50511002_X28_dialog_content = "그대에게 내 가족을 두고 평할 자격은 없다.",
  ui_story_5051_50511002_X29_dialog_content = "아버님... PlayerName한테 그렇게 매섭게 말씀하지 말아 주세요...",
  ui_story_5051_50511002_X30_dialog_content = "조용히 해라. 내 알아서 할 터이니.",
  ui_story_5051_50511002_X31_dialog_content = "아뇨, PlayerName한테 그러시면 안 되는 거예요...!",
  ui_story_5051_50511002_X32_dialog_content = "미아...?",
  ui_story_5051_50511002_X33_dialog_content = "「백야성의 성주」, 「가문의 수호자」...\n아버님은 많은 위대한 이름들을 가지고 계시죠.",
  ui_story_5051_50511002_X34_dialog_content = "하지만 그런 이름들은... 그저 절 숨막히게 만들 뿐이에요.",
  ui_story_5051_50511002_X35_dialog_content = "어쩌면 모두의 눈에는 아버님이 무척 위대하고 숭고하게 보일지도 모르겠죠.",
  ui_story_5051_50511002_X36_dialog_content = "하지만 제 앞에서는... 항상 그렇게 사납고,\n주변 사람들의 마음을 아프게 할 뿐이라고요...",
  ui_story_5051_50511002_X37_dialog_content = "......",
  ui_story_5051_50511002_29_dialog_content = "-",
  ui_story_5051_50511002_30_dialog_content = "-",
  ui_story_5051_50511002_31_dialog_content = "-",
  ui_story_5051_50511002_32_dialog_content = "-",
  ui_story_5051_50511002_33_dialog_content = "-",
  ui_story_5051_50511002_34_dialog_content = "-",
  ui_story_5051_50511002_35_dialog_content = "-",
  ui_story_5051_50511002_36_dialog_content = "-",
  ui_story_5051_50511002_37_dialog_content = "-",
  ui_story_5051_50511002_38_dialog_content = "-",
  ui_story_5051_50511002_39_dialog_content = "-",
  ui_story_5051_50511002_40_dialog_content = "-",
  ui_story_5051_50511002_41_dialog_content = "-",
  ui_story_5051_50511002_42_dialog_content = "-",
  ui_story_5051_50511002_43_dialog_content = "-",
  ui_story_5051_50511002_44_dialog_content = "-",
  ui_story_5051_50511002_45_dialog_content = "-",
  ui_story_5051_50511002_46_dialog_content = "-",
  ui_story_5051_50511002_47_dialog_content = "-",
  ui_story_5051_50511002_X38_dialog_content = "이, 이게 바로 제 진심이에요.",
  ui_story_5051_50511002_X39_dialog_content = "화가 나시면 저한테 따지세요. 제 친구를 곤란하게 만들지 마세요...!",
  ui_story_5051_50511002_48_dialog_content = "으읏...",
  ui_story_5051_50511002_49_dialog_content = "두려운 것이냐.",
  ui_story_5051_50511002_50_dialog_content = "저...저는 무섭다고 말해선 안 돼요.",
  ui_story_5051_50511002_51_dialog_content = "아버님의 장녀로서, 전 뭐든지 가장 잘해야만 해요.\n그래야 아버님도 실망하지 않으시니까요.",
  ui_story_5051_50511002_52_dialog_content = "제가 좋아하는 음악이나 미술도, 제가 싫어하는 정치나 전투도...",
  ui_story_5051_50511002_53_dialog_content = "전 모두 잘해야만 해요...",
  ui_story_5051_50511002_54_dialog_content = "내 딸아, 너는 이미 충분히 잘해왔다.",
  ui_story_5051_50511002_55_dialog_content = "하지만 저는 아직 아버님의 어떤 부담도 덜어 드리지 못했잖아요...",
  ui_story_5051_50511002_56_dialog_content = "저... 생각났어요. 전부 기억이 났어요.",
  ui_story_5051_50511002_57_dialog_content = "그때 전 용기를 내서 기사단에 들어갔어요.\n하지만 곧 암귀와 싸우다가 다치고 말았죠...",
  ui_story_5051_50511002_58_dialog_content = "그 뒤엔... 어머님이 절 구해주셨어요. 그렇죠?",
  ui_story_5051_50511002_59_dialog_content = "전 아무것도 할 수 없고, 오히려 짐이 될 뿐이에요...",
  ui_story_5051_50511002_60_dialog_content = "그리고 지금도... 제가 다 망쳤잖아요?",
  ui_story_5051_50511002_61_dialog_content = "그, 그게 아니라면... 아버님께서 제게 그토록 화를 내진 않으셨겠죠.\n제게 빨리 이곳을 떠나라고 하지도 않으셨을 테고요...",
  ui_story_5051_50511002_X61_dialog_content = "전부 제가 너무 쓸모없기 때문에...\n아버님이 계속 화를 내시는 거죠? 그런 거죠...?",
  ui_story_5051_50511002_62_dialog_content = "그런 뜻이 아니다, 미아.",
  ui_story_5051_50511002_63_dialog_content = "아버님은 또... 절 <color=#FFB400>머나먼 곳</color>으로 보내실 건가요?",
  ui_story_5051_50511002_64_dialog_content = "!!!",
  ui_story_5051_50511002_65_dialog_content = "너를 움브라톤으로 보내 신원을 숨기고 치료를 받게 한 것은\n내 부득이한 선택이었다.",
  ui_story_5051_50511002_66_dialog_content = "허나 인정하마. 그때의 나는 아직 너무 젊었다.",
  ui_story_5051_50511002_67_dialog_content = "시간을 다시 돌릴 수만 있다면 반드시 모든 것을 고려하여\n더 나은 방법을 찾았을 것이다.",
  ui_story_5051_50511002_68_dialog_content = "지금에 와서 이러한 말을 한들 쓸모없는 것은 안다.\n허나 어찌 되었든... 그것은 내가 내렸던 가장 끔찍한 결정 중 하나였다.",
  ui_story_5051_50511002_69_dialog_content = "그동안 너 홀로 많은 고통을 겪었구나.",
  ui_story_5051_50511002_70_dialog_content = "아버님...",
  ui_story_5051_50511002_71_dialog_content = "저, 전 어머니와 여동생이... 그리고 아버님이... 너무 그리웠어요.",
  ui_story_5051_50511002_72_dialog_content = "알고 있다, 내 딸아.",
  ui_story_5051_50511002_73_dialog_content = "네가 움브라톤에서 생활하는 동안, 이스타반은 줄곧 나에게 네 상황을 전했다.",
  ui_story_5051_50511002_74_dialog_content = "나는 네 병세가 이미 호전된 것을 알았고,\n어쩌면 언젠가는 네게 이 모든 것을 분명히 말해야 한다고 생각했다.",
  ui_story_5051_50511002_75_dialog_content = "다만 이러한 사태에 휘말릴 줄은 몰랐던 것이다...",
  ui_story_5051_50511002_76_dialog_content = "약속하마. 나가고 나면 모든 진실을 알려주마.\n지금 시급한 것은 이곳을 떠나는 것이다.",
  ui_story_5051_50511002_77_dialog_content = "전... 으읏...",
  ui_story_5051_50511002_79_dialog_content = "하, 하지만 여길 떠나면... 전 영원히 다시는 어머님을 뵐 수 없는 거죠?",
  ui_story_5051_50511002_80_dialog_content = "......",
  ui_story_5051_50511002_81_dialog_content = "...저 때문이었나요?",
  ui_story_5051_50511002_82_dialog_content = "어머님은 저 때문에 돌아가신 건가요?",
  ui_story_5051_50511002_83_dialog_content = "얘야, 그 일은 나중에 다시 이야기하기로 하자.",
  ui_story_5051_50511002_84_dialog_content = "우선 이곳을 떠나야 한다.",
  ui_story_5051_50511002_85_dialog_content = "여길... 떠나요?",
  ui_story_5051_50511002_86_dialog_content = "네게 다시 문제가 생기는 것을 더는 보고 싶지 않다. 알겠느냐.",
  ui_story_5051_50511002_87_dialog_content = "...네.",
  ui_story_5051_50511002_88_dialog_content = "자, 일어설 수 있겠느냐.",
  ui_story_5051_50511002_89_dialog_content = "내 손을 잡아라. 이제 가자.",
  ui_story_5051_50511002_90_dialog_content = "<color=#e8d9bb>챙!</color>",
  ui_story_5051_50511002_91_dialog_content = "흐음?",
  ui_story_5051_50511002_92_dialog_content = "(이게... 대체 무슨 상황이야?)",
  ui_story_5051_50511002_93_dialog_content = "아버님!",
  ui_story_5051_50511002_94_dialog_content = "베로니카, 멀리 떨어져라.",
  ui_story_5051_50511002_95_dialog_content = "널 데려가려는 도적에게 다가가지 마라!",
  ui_story_5051_50511002_96_dialog_content = "......",
  ui_story_5051_50511002_97_dialog_content = "(젊은 솔라드 씨는 상대가 자기 자신이라는 걸 못 알아챈 건가?!)",
  ui_story_5051_50511002_98_dialog_content = "(아... 그것도 그렇네...)",
  ui_story_5051_50511002_99_dialog_content = "(사정을 몰랐으면 나도 눈앞의 두 사람이 같은 사람이라는 걸\n절대 믿지 않았을 테니까.)",
  ui_story_5051_50511002_100_dialog_content = "감히 이 솔라드의 여식을 붙잡을 배짱이 있는 자가...",
  ui_story_5051_50511002_101_dialog_content = "어째서 나와 정정당당하게 맞설 배짱은 없는 거지?",
  ui_story_5051_50511002_102_dialog_content = "불필요한 오해는 피하고 싶을 뿐이네.",
  ui_story_5051_50511002_103_dialog_content = "불필요한 오해?",
  ui_story_5051_50511002_104_dialog_content = "그대를 만나본 기억은 없다만.",
  ui_story_5051_50511002_105_dialog_content = "트로이 가문인가? 아니, 그래 보이지는 않는군.",
  ui_story_5051_50511002_106_dialog_content = "그렇다면, 카르티마 가문이겠지?",
  ui_story_5051_50511002_107_dialog_content = "전부 아니다. 나는 베로니카의...",
  ui_story_5051_50511002_108_dialog_content = "친구라네.",
  ui_story_5051_50511002_109_dialog_content = "친구?",
  ui_story_5051_50511002_110_dialog_content = "친구의 친구는 그 또한 친구인 법이지.",
  ui_story_5051_50511002_111_dialog_content = "재미있군. 하지만 내가 들어본 것은 「적의 적은 나의 친구」라는 말뿐이다.",
  ui_story_5051_50511002_112_dialog_content = "이제 들어보게 되었잖나.",
  ui_story_5051_50511002_113_dialog_content = "그 말투로 봐서는 나와 친구가 되고 싶지는 않아 보이는군.",
  ui_story_5051_50511002_114_dialog_content = "아버님, 이분은... 제가 움브라톤에서 알게 된 친구가 맞아요.",
  ui_story_5051_50511002_115_dialog_content = "방금 전에도 절 도와주셨어요.",
  ui_story_5051_50511002_116_dialog_content = "빠르지도, 늦지도 않게, 하필 암귀가 나타났을 때 함께 모습을 드러냈다.",
  ui_story_5051_50511002_117_dialog_content = "너무나도 공교롭지 않느냐.",
  ui_story_5051_50511002_118_dialog_content = "베로니카, 앞으로 친구를 사귈 때는 어머니와 좀 더 상의하는 게 좋겠다.",
  ui_story_5051_50511002_119_dialog_content = "......",
  ui_story_5051_50511002_120_dialog_content = "(크흠... 솔라드 씨는 분명히 젊었을 때의 자신한테 화가 잔뜩 나셨겠지?)",
  ui_story_5051_50511002_121_dialog_content = "(근데 이대로 계속 가는 건 곤란해...)",
  ui_story_5051_50511002_122_dialog_content = "(그렇다고 젊은 솔라드 씨한테 「이 사람은 십여 년 뒤의 당신」이라고\n말할 수도 없잖아...)",
  ui_story_5051_50511002_123_dialog_content = "(...뭐라도 해보는 수밖에 없겠어.)",
  ui_story_5051_50511002_124_dialog_content = "...사실은요!",
  ui_story_5051_50511002_125_dialog_content = "흐음?",
  ui_story_5051_50511002_126_dialog_content = "성주님, 용서해 주세요.",
  ui_story_5051_50511002_127_dialog_content = "사실 이분은 저희 아버지... 「스카이워커」 씨라고 해요.",
  ui_story_5051_50511002_128_dialog_content = "이번에 제가 베로니카 공주님이랑 백야성으로 돌아간다고\n아버지한테 말씀을 못 드렸거든요...",
  ui_story_5051_50511002_129_dialog_content = "그랬더니 아버지가 친구분한테 부탁해서 백야성까지 절 찾으러 오신 거예요.",
  ui_story_5051_50511002_130_dialog_content = "근데 만나자마자 암귀한테 습격을 당할 줄은 정말 몰랐어요.",
  ui_story_5051_50511002_131_dialog_content = "마, 맞아요!",
  ui_story_5051_50511002_132_dialog_content = "하하, 내가 오해라고 말했지 않은가.",
  ui_story_5051_50511002_133_dialog_content = "어찌 되었든 귀하와 가족에게는 아들이 신세를 졌군. 감사하지.",
  ui_story_5051_50511002_134_dialog_content = "정말 그러한 것이라면, 내 대접이 소홀했다.",
  ui_story_5051_50511002_135_dialog_content = "다만...",
  ui_story_5051_50511002_136_dialog_content = "여전히 믿지 못하는 것인가.",
  ui_story_5051_50511002_137_dialog_content = "PlayerName의 나이는 베로니카와 큰 차이는 없어 보이는군.",
  ui_story_5051_50511002_138_dialog_content = "난 그대가 PlayerName의 조부라고 생각했다만.",
  ui_story_5051_50511002_139_dialog_content = "하하하... 젊은이여.",
  ui_story_5051_50511002_140_dialog_content = "덕분에 내가 확실히 젊을 적 남에게 호감을 주는 사람은 아니었음을 실감했네.",
  ui_story_5051_50511002_141_dialog_content = "상상이 가는군.",
  ui_story_5051_50511002_142_dialog_content = "다행히 이 정도 나이가 되면 그런 것들은 신경이 쓰이지 않게 되지.",
  ui_story_5051_50511002_143_dialog_content = "내 짐작이 맞다면 귀하에게는 아직 다른 중요한 할 일이 있을 터인데.",
  ui_story_5051_50511002_144_dialog_content = "그런들 어쨌다는 거지?",
  ui_story_5051_50511002_145_dialog_content = "이래 봬도 암귀를 상대하는 일에는 적지 않은 경험이 있어서 말이지.",
  ui_story_5051_50511002_146_dialog_content = "내가 베로니카와 아들을 데리고 안전한 곳으로 피신해 줄 수 있네.",
  ui_story_5051_50511002_147_dialog_content = "호의는 고맙게 받도록 하지.",
  ui_story_5051_50511002_148_dialog_content = "허나 베로니카는 내 딸이다.",
  ui_story_5051_50511002_149_dialog_content = "내 딸은 내가 알아서 지킨다.",
  ui_story_5051_50511002_150_dialog_content = "남이 끼어들 필요는 없다.",
  ui_story_5051_50511002_151_dialog_content = "......",
  ui_story_5051_50511002_152_dialog_content = "<color=#FFB400>아버님</color>...",
  ui_story_5051_50511002_153_dialog_content = "(지금 그건...)",
  ui_story_5051_50511002_154_dialog_content = "(어느 쪽 「<color=#FFB400>아버님</color>」이야?!)",
  ui_story_5051_50511101_1_dialog_content = "수정구슬의 반응이 점점 격렬해지고 있어요.",
  ui_story_5051_50511101_2_dialog_content = "PlayerName 씨랑 다들 분명히 이 근처에 있을 거예요!",
  ui_story_5051_50511101_3_dialog_content = "조용하군.",
  ui_story_5051_50511101_4_dialog_content = "그러게요... 오는 길의 「시끌벅적」했던 모습이랑은 딴판이네요.",
  ui_story_5051_50511101_5_dialog_content = "우리 그냥 북적북적한 데 가서 놀자!",
  ui_story_5051_50511101_6_dialog_content = "여긴 너무 썰렁해.",
  ui_story_5051_50511101_7_dialog_content = "딱 봐도 맛있는 술집 같은 건 없게 생겼잖아~",
  ui_story_5051_50511101_8_dialog_content = "크흠, 우리 지금 놀러 온 거 아니에요.",
  ui_story_5051_50511101_9_dialog_content = "아직 정식 제자도 안 됐으면서 날 속이려는 거야?",
  ui_story_5051_50511101_10_dialog_content = "아까 검은 예복 입은 사람들이 막 떠들던 거 누가 봐도 손님 끄는 거잖아.",
  ui_story_5051_50511101_11_dialog_content = "「검은 예복 입은 사람들」? 설마 암귀 말하는 건 아니죠?!",
  ui_story_5051_50511101_12_dialog_content = "그럼 지금 암귀도 구분 못 할 정도로 취한 거였어요?",
  ui_story_5051_50511101_13_dialog_content = "<size=30>어쩐지 나도 못 알아보더라니...</size>",
  ui_story_5051_50511101_14_dialog_content = "살펴보니 근처의 암귀는 이미 깨끗이 처리된 것 같다.",
  ui_story_5051_50511101_15_dialog_content = "성주님과 공주님이 계신 곳은 더 많은 병력이 배치되어 있다.",
  ui_story_5051_50511101_16_dialog_content = "당신 친구는 그분들과 함께 있으니 분명히 무사할 거다.",
  ui_story_5051_50511101_17_dialog_content = "고마워요, 꼬마 기사님.",
  ui_story_5051_50511101_18_dialog_content = "아까 당신이 「휙휙휙」하고 암귀를 치워주지 않았으면\n이렇게 빨리 여기까지 못 왔을 거예요.",
  ui_story_5051_50511101_19_dialog_content = "당신은 제가 백야성에서 본 기사들 중에 가장 믿음직한 기사예요!",
  ui_story_5051_50511101_20_dialog_content = "수정구슬을 사용하지 않아도 알 수 있어요...",
  ui_story_5051_50511101_21_dialog_content = "당신은 미래에 분명히 세상에 이름을 날릴 거물이 될 거예요!",
  ui_story_5051_50511101_22_dialog_content = "과찬이야.",
  ui_story_5051_50511101_23_dialog_content = "지금의 나는 그저 예비 기사일 뿐이다.",
  ui_story_5051_50511101_24_dialog_content = "그래도 날 그렇게 믿어준다니 큰 격려가 됐어.",
  ui_story_5051_50511101_25_dialog_content = "괜찮아요. 아직 젊으니까요! 앞으로 기회는 얼마든지...",
  ui_story_5051_50511101_26_dialog_content = "앗, 잠깐만요!",
  ui_story_5051_50511101_27_dialog_content = "(「영원한 기억의 수정」이 기록하고 있는 건 12년 전에 일어난 일이잖아.)",
  ui_story_5051_50511101_28_dialog_content = "(그럼... 이 보기엔 젊어 보이는 기사님도 현실 세계에선 나보다 훨씬 연상이란 거잖아?!)",
  ui_story_5051_50511101_29_dialog_content = "크흠, 저기, 꼬마 기사님, 당신... 나이가 어떻게 되죠?",
  ui_story_5051_50511101_30_dialog_content = "어머, 이 기지배 좀 봐. 아까 내 제자가 되고 싶다고 할 때는 기세가 등등하더니.",
  ui_story_5051_50511101_31_dialog_content = "왜 갑자기 쭈뼛거리고 있어?",
  ui_story_5051_50511101_32_dialog_content = "좋으면 좋아한다고 말을 하란 말이야!",
  ui_story_5051_50511101_33_dialog_content = "으앗, 아니, 전 그런 뜻이 아니라니까요!",
  ui_story_5051_50511101_34_dialog_content = "으엑?",
  ui_story_5051_50511101_35_dialog_content = "무, 물론 꼬마 기사님이 싫다는 뜻도 아니에요!",
  ui_story_5051_50511101_36_dialog_content = "그, 그러니까... 아이참... 뭐라고 말을 잘 못하겠어요.",
  ui_story_5051_50511101_37_dialog_content = "그치만! 혹시 12년 뒤에도 아직 백야성에서 기사로 일하고 계신다면...",
  ui_story_5051_50511101_38_dialog_content = "우리 분명히 다시 만날 수 있을 거예요~",
  ui_story_5051_50511101_39_dialog_content = "뭐야, 또 그 「몇 년 뒤에 내가 찾아갈 테니 날 기다려 줘」 같은 클리셰야?",
  ui_story_5051_50511101_40_dialog_content = "그런 흔한 대사는 내가 여덟 살 때 이미 한물갔거든? 좀 더 참신할 순 없어?",
  ui_story_5051_50511101_41_dialog_content = "아, 아하하하...",
  ui_story_5051_50511101_42_dialog_content = "저 술고래는 지금 헛소리하는 거예요. 꼬마 기사님, 절대 신경 쓰지 마세요!",
  ui_story_5051_50511101_43_dialog_content = "약속하겠어!",
  ui_story_5051_50511101_44_dialog_content = "엣?",
  ui_story_5051_50511101_45_dialog_content = "비록 우리 가문 사람들은 여러 가지 이유로 날 좋게 보지 않고 있지만...",
  ui_story_5051_50511101_46_dialog_content = "그래도 저들이 돌아가면서 날 길러주지 않았다면 지금의 나는 없었을 거다.",
  ui_story_5051_50511101_47_dialog_content = "그래서 난 언젠가 저들에게 내 가치를 증명하고 싶다.\n그리고 카르티마 가문의 영광스러운 역사를 새롭게 써나갈 것이다.",
  ui_story_5051_50511101_48_dialog_content = "12년 뒤...",
  ui_story_5051_50511101_49_dialog_content = "당신이 다시 날 보러 올 때면, 난 반드시 수천수만의 군대를 통솔하는\n최강의 기사가 되고 말겠어!",
  ui_story_5051_50511101_50_dialog_content = "우와... 왠지 멋져요!",
  ui_story_5051_50511101_51_dialog_content = "그럼 약속이에요. 저 꼭 기사단으로 찾아갈게요!",
  ui_story_5051_50511101_52_dialog_content = "아... 근데 저 그러고 보니 아직 당신 이름도 모르는 것 같은데요.",
  ui_story_5051_50511101_53_dialog_content = "「시로나 카르티마」다.",
  ui_story_5051_50511101_54_dialog_content = "「시로나」... 정말 귀여운 이름이네요.",
  ui_story_5051_50511101_55_dialog_content = "아니, 자, 잠깐만요...",
  ui_story_5051_50511101_56_dialog_content = "기사님 여자애였어요?!",
  ui_story_5051_50511101_57_dialog_content = "<color=#e8d9bb>한편, 거리의 다른 곳</color>",
  ui_story_5051_50511101_58_dialog_content = "젊은이여, 서두르지 말아야 하네.",
  ui_story_5051_50511101_59_dialog_content = "귀하가 처한 상황도, 마음도 물론 이해는 하네.",
  ui_story_5051_50511101_60_dialog_content = "나는 나이가 들고 나서야 비로소 「부드러움으로 강함을 이기는」 이치를 알게 되었네.",
  ui_story_5051_50511101_61_dialog_content = "부디 귀하가 깊이 생각하고, 가족을 다른 일에 끌어들이지 않길 바라겠네.",
  ui_story_5051_50511101_62_dialog_content = "기회가 된다면 그대를 꼭 원로원의 각위에게 소개해 드리도록 하지.",
  ui_story_5051_50511101_63_dialog_content = "분명 말이 잘 통할 것이다.\n게다가 다들 「젊은이」의 스승이 되는 걸 좋아하고 말이야.",
  ui_story_5051_50511101_64_dialog_content = "...그리 생각하는가.",
  ui_story_5051_50511101_65_dialog_content = "(그랬군, 이걸 잊어버리다니...)",
  ui_story_5051_50511101_66_dialog_content = "(젊은 시절 내가 가장 싫어하던 것이 독선적인 설교가 아니었던가.)",
  ui_story_5051_50511101_67_dialog_content = "<size=45>우와──!</size>",
  ui_story_5051_50511101_68_dialog_content = "흐음?",
  ui_story_5051_50511101_69_dialog_content = "드디어 찾았네요! 다들 괜찮으세요?",
  ui_story_5051_50511101_70_dialog_content = "팔다리도 잘 붙어 있고, 표정에 생기도 있고...\n다들 별일 없어 보이네요! 다행이에요!",
  ui_story_5051_50511101_71_dialog_content = "쟈키니...",
  ui_story_5051_50511101_72_dialog_content = "PlayerName 씨, 제 걱정은 안 해도 돼요!\n보세요! 아주 멀쩡하잖아요~",
  ui_story_5051_50511101_73_dialog_content = "자, 그럼 이제 여기서 죽치고 있으면 안 되죠.",
  ui_story_5051_50511101_74_dialog_content = "크흠... 저흰 좀 특수한 사정이 있어서...",
  ui_story_5051_50511101_75_dialog_content = "반드시 「오늘」 안에 여길 떠나야 하거든요!",
  ui_story_5051_50511101_76_dialog_content = "쉿...",
  ui_story_5051_50511101_77_dialog_content = "어? PlayerName 씨, 무슨 문제 있어요?",
  ui_story_5051_50511101_78_dialog_content = "아, 혹시 여기 잔뜩 취한 분이 누군지 물어보시려는 건가요?",
  ui_story_5051_50511101_79_dialog_content = "그건 말하자면 좀 복잡한데...\n대신 우릴 도와준 여기 이 기사님은 소개해 드릴 수 있어요!",
  ui_story_5051_50511101_80_dialog_content = "뭐야? 왜 없어?",
  ui_story_5051_50511101_81_dialog_content = "제가 친구를 찾았으니까 그냥 말도 없이 가버린 건가요?",
  ui_story_5051_50511101_82_dialog_content = "휴, 정말... 백야성 사람들은 왜 하나같이 제대로 작별 인사를 안 하는 건지~",
  ui_story_5051_50511101_83_dialog_content = "야, 이 사람들이 네가 찾던 친구들이야?",
  ui_story_5051_50511101_84_dialog_content = "왠지 어디서 본 것 같은데?",
  ui_story_5051_50511101_85_dialog_content = "보아즈? 어젯밤에 북방으로 돌아간 게 아니었나?",
  ui_story_5051_50511101_86_dialog_content = "모처럼 백야성에 왔으니까... 딸꾹, 나도 푹 쉬고 싶다고.",
  ui_story_5051_50511101_87_dialog_content = "아~ 생각났어. 당신, 어제 그...",
  ui_story_5051_50511101_88_dialog_content = "성주님이네!",
  ui_story_5051_50511101_89_dialog_content = "(어? 이, 이 사람이... 여기 성주님?!)",
  ui_story_5051_50511101_90_dialog_content = "(어쩐지 아까부터 PlayerName 씨가 눈치를 주더라니...)",
  ui_story_5051_50511101_91_dialog_content = "<size=30>PlayerName 씨, 잠깐 이리 좀 와요!</size>",
  ui_story_5051_50511101_92_dialog_content = "앗, 천천히 해. 당기지 말고...",
  ui_story_5051_50511101_93_dialog_content = "지, 지금 대체 무슨 상황인 거죠?",
  ui_story_5051_50511101_94_dialog_content = "나도 상황 정리를 하려고 했는데, 네가 나타나서 상황이 더 복잡해진 것 같아...",
  ui_story_5051_50511101_95_dialog_content = "세상에 복잡한 일이 어딨어요? 너무 복잡하게 생각한 거 아니에요?",
  ui_story_5051_50511101_96_dialog_content = "아무튼 그러니까 성주님이 방금 성주님을 만나서 성주님이 도적인 줄 알고...",
  ui_story_5051_50511101_97_dialog_content = "들으면 들을수록 모르겠는데요?",
  ui_story_5051_50511101_98_dialog_content = "그러니까 복잡한 상황이라고 한 거야...",
  ui_story_5051_50511101_99_dialog_content = "그럼 요점은 어떻게 두 성주님을 구별하냐는 거죠?",
  ui_story_5051_50511101_100_dialog_content = "아까 난 우리랑 이 세계에 들어온 성주님을\n우리 아버지 「스카이워커」 씨라고 소개했어...",
  ui_story_5051_50511101_101_dialog_content = "「스카이워커」? 그거 PlayerName 씨 콜로서스 이름이잖아요?",
  ui_story_5051_50511101_102_dialog_content = "너무 급해서 갑자기 다른 이름은 생각이 안 나더라고...",
  ui_story_5051_50511101_103_dialog_content = "그럼 한쪽은 늙은 성주님, 다른 한쪽은 젊은 성주님, 이렇게 구분하면 간단하잖아요?",
  ui_story_5051_50511101_104_dialog_content = "성주님한테는 좀 미안하긴 하지만, 네가 이해하기 쉬우려면 어쩔 수 없지...",
  ui_story_5051_50511101_105_dialog_content = "아까 늙은 성주님이 미아를 데려가려고 했는데\n젊은 성주님한테 도둑으로 오해를 받았거든.",
  ui_story_5051_50511101_106_dialog_content = "그래서 지금 어떻게 여기서 빠져나갈지 생각하던 참이었어!",
  ui_story_5051_50511101_107_dialog_content = "아~ 그렇게 말하니까 알겠네요!",
  ui_story_5051_50511101_108_dialog_content = "저한테 맡기세요!",
  ui_story_5051_50511101_109_dialog_content = "...괜찮아요, 나 진~짜로 안 취했어요!",
  ui_story_5051_50511101_110_dialog_content = "좋다. 그렇다면 옆에 있는 사람은 누구인지 소개해 줄 수 있겠나?",
  ui_story_5051_50511101_111_dialog_content = "자기소개는 제가 할게요! 제가 바로 보아즈 님의 제자랍니다~ 에헤헷.",
  ui_story_5051_50511101_112_dialog_content = "북방의 여왕이 사절을 두 명 보냈다는 이야기는 못 들었다만.",
  ui_story_5051_50511101_113_dialog_content = "성주님은 모르시는 게 당연하죠. 왜냐하면 사절은 확실히 한 명뿐이니까요.",
  ui_story_5051_50511101_114_dialog_content = "전 그냥 수행원일 뿐이에요~ 하지만 수행원도 임무가 있죠!",
  ui_story_5051_50511101_115_dialog_content = "제 임무는 보아즈 님이랑은 별개거든요.\n그래서 성주님과 공작부인을 알현하러 못 갔던 거예요.",
  ui_story_5051_50511101_116_dialog_content = "호오? 그렇다면 그대의 임무는 무엇인가?",
  ui_story_5051_50511101_117_dialog_content = "북방에서 여왕 폐하께서 개최하는 연회에 PlayerName 씨를 초대하는 거예요.",
  ui_story_5051_50511101_118_dialog_content = "뭐?!",
  ui_story_5051_50511101_119_dialog_content = "저쪽은 모르는 눈치다만.",
  ui_story_5051_50511101_120_dialog_content = "크흠, 모르는 게 당연하죠. 왜냐하면 이제 겨우 만났으니까요~",
  ui_story_5051_50511101_121_dialog_content = "PlayerName 씨, 어때요? 가실 건가요?",
  ui_story_5051_50511101_122_dialog_content = "<size=30>크흠, 빨리 대답해 줘요!</size>",
  ui_story_5051_50511101_123_dialog_content = "어? 아...",
  ui_story_5051_50511101_124_dialog_content = "여왕 폐하의 초대라면 당연히 거절할 리가 없지!",
  ui_story_5051_50511101_125_dialog_content = "그런가요? 그거 다행이네요~",
  ui_story_5051_50511101_126_dialog_content = "이걸로 스승님의 임무도 끝났고, 제 임무도 끝났네요.",
  ui_story_5051_50511101_127_dialog_content = "그럼 여러분! 다 함께 즐겁게 북방으로 돌아가요~",
  ui_story_5051_50511101_128_dialog_content = "(쟈키니 너 정말 천재구나!)",
  ui_story_5051_50511101_129_dialog_content = "(그럼 이제 젊은 성주님도 우릴 보내주겠지?)",
  ui_story_5051_50511101_130_dialog_content = "......",
  ui_story_5051_50511101_131_dialog_content = "(근데... 왜 늙은 성주님은 계속 신경을 곤두세우고 계시는 거지?)",
  ui_story_5051_50511101_132_dialog_content = "(설마 나랑 쟈키니가 상황을 너무 쉽게 생각했나?)",
  ui_story_5051_50511101_133_dialog_content = "그랬군.",
  ui_story_5051_50511101_134_dialog_content = "(착각인가? 젊은 성주님... 방금 코웃음을 치신 것 같은데...)",
  ui_story_5051_50511101_135_dialog_content = "나는 북방의 여왕에게는 늘 경의를 표하고 있다.\n여왕의 손님이라면 곧 나의 손님이기도 하지.",
  ui_story_5051_50511101_136_dialog_content = "미안하군, 그대들의 앞에서 백야성의 추태를 보이고 말았다.",
  ui_story_5051_50511101_137_dialog_content = "대신 내가 보장하지. 이러한 혼란은 결코 오래 가지 않을 것이다.",
  ui_story_5051_50511101_138_dialog_content = "지금부터는 모두 내 뒤를 따르도록.",
  ui_story_5051_50511101_139_dialog_content = "그대들의 안전은 내가 지키겠다!",
  ui_story_5051_50511101_140_dialog_content = "<size=30>아까랑... 태도가 확 달라졌잖아...?</size>",
  ui_story_5051_50511101_141_dialog_content = "<size=30>PlayerName, 만약 체스말이 그대의 수중에 스스로 들어온다면,\n그대는 이를 쓰지 않을 것인가?</size>",
  ui_story_5051_50511101_142_dialog_content = "<size=30>체스말이요?</size>",
  ui_story_5051_50511101_143_dialog_content = "(무슨 뜻이지? 우리가 젊은 성주님의 체스말이 되었다는 건가?)",
  ui_story_5051_50511101_144_dialog_content = "(근데 우리가 저분한테 뭐 도움이 될 게 있나?)",
  ui_story_5051_50511101_145_dialog_content = "(게다가... 늙은 성주님이 방금처럼 말한 건...)",
  ui_story_5051_50511101_146_dialog_content = "(설마... 솔라드 씨가 과거에 저런 식으로 남들을 체스말로 삼았던 건가?)",
  ui_story_5051_50511101_147_dialog_content = "<size=30>PlayerName, 체스는 결코 가벼운 놀이가 아니다. 이제는 그대도 깨달았겠지.</size>",
  ui_story_5051_50511101_148_dialog_content = "아버님!",
  ui_story_5051_50511101_149_dialog_content = "이 목소리는...",
  ui_story_5051_50511101_150_dialog_content = "아버님!!",
  ui_story_5051_50511101_151_dialog_content = "카...",
  ui_story_5051_50511101_152_dialog_content = "카렌, 네가 왜 여기 있는 것이냐?",
  ui_story_5051_50511101_153_dialog_content = "내가 데리고 왔어요.",
  ui_story_5051_50511101_154_dialog_content = "......",
  ui_story_5051_50511101_155_dialog_content = "왜 돌아온 거야? 이어서 올 암귀들도 이미 처리한 건가?",
  ui_story_5051_50511101_156_dialog_content = "「이어서 올 암귀」?",
  ui_story_5051_50511101_157_dialog_content = "음... 다른 곳에서도 암귀가 나타나지 않을까 염려가 돼서 말이야.",
  ui_story_5051_50511101_158_dialog_content = "확신할 수는 없지만, 그렇다 해서 벌써 방심해선 안 돼.",
  ui_story_5051_50511101_159_dialog_content = "...미즈 로트는 왜 곁에 없지?\n내 명은 그대들을 지키며 대피하라는 것이었는데, 어째서 직무를 저버린 거지?",
  ui_story_5051_50511101_160_dialog_content = "저버리지 않았어요. 우리보다 주변의 백성들이 더 도움이 필요했으니까요.",
  ui_story_5051_50511101_161_dialog_content = "조슈아, 그렇게 제멋대로...",
  ui_story_5051_50511101_162_dialog_content = "다니엘, 당신 나랑 하루 이틀 본 사이도 아니잖아요.",
  ui_story_5051_50511101_163_dialog_content = "내 검술이 당신 못지않다는 건 언제쯤 기억해 줄 거죠?",
  ui_story_5051_50511101_164_dialog_content = "그리고 여기도 도움이 필요한 친구분들이 많이 있는 것 같네요...",
  ui_story_5051_50511101_165_dialog_content = "난 당신 짐을 덜어주고 싶어요, 다니엘.",
  ui_story_5051_50511101_166_dialog_content = "조슈아!",
  ui_story_5051_50511101_167_dialog_content = "콜록... 콜록콜록콜록...",
  ui_story_5051_50511101_168_dialog_content = "어머? 괜찮으신가요?",
  ui_story_5051_50511101_169_dialog_content = "...왠지 낯이 익은 분이시네요.",
  ui_story_5051_50511101_170_dialog_content = "그러한가, 우리가 처음 만났을 때도 그대는 그렇게 말했었지.",
  ui_story_5051_50511101_171_dialog_content = "우리가... 전에 어디서 만난 적이 있나요?",
  ui_story_5051_50511101_172_dialog_content = "(이 세계와 얽히면 안 된다고 그렇게 경고하셨던 분은 어딜 가셨나...)",
  ui_story_5051_50511101_173_dialog_content = "크, 크흠, 아버지, 전에 공작부인님이랑 만난 적 있으세요?",
  ui_story_5051_50511101_174_dialog_content = "...미안하군, 사람을 잘못 본 모양이오.",
  ui_story_5051_50511101_175_dialog_content = "아, PlayerName의 아버님이셨군요. 어쩐지 뭔가 낯이 익다 했네요~",
  ui_story_5051_50511101_176_dialog_content = "으아악──!",
  ui_story_5051_50511101_177_dialog_content = "암귀다... 어째서 또 암귀가 잔뜩 나타난 거야?!",
  ui_story_5051_50511101_178_dialog_content = "아까 성주님이 말씀하신 대로네요! 진짜로 암귀가 또 나타났는데요?!",
  ui_story_5051_50511101_179_dialog_content = "설마 성주님도 점 칠 줄 아세요? 저보다 더 잘 맞는 점술인가요?!",
  ui_story_5051_50511101_180_dialog_content = "......",
  ui_story_5051_50511101_181_dialog_content = "다니엘!",
  ui_story_5051_50511101_182_dialog_content = "주변을 경계하고 암귀를 막아라!",
  ui_story_5051_50511101_183_dialog_content = "<color=#e8d9bb>터벅, 터벅, 터벅, 터벅──</color>",
  ui_story_5051_50511101_184_dialog_content = "질서 있는 발소리...?",
  ui_story_5051_50511101_185_dialog_content = "암귀가 아냐!",
  ui_story_5051_50511101_186_dialog_content = "다행이에요!",
  ui_story_5051_50511101_187_dialog_content = "지원군이 왔네요!",
  ui_story_5051_50511101_188_dialog_content = "기다려라.",
  ui_story_5051_50511101_189_dialog_content = "저 병사들은 아무래도 우리를 지원하러 온 것이 아닌 듯하군.",
  ui_story_5051_50511101_190_dialog_content = "네?",
  ui_story_5051_50511101_191_dialog_content = "돌격하라!",
  ui_story_5051_50511101_192_dialog_content = "으아앗──!",
  ui_story_5051_50511101_193_dialog_content = "이 사람들 왜 우리한테 무기를 겨누는 거죠?!",
  ui_story_5051_50511102_1_dialog_content = "쟈키니! 왼쪽 대각선!",
  ui_story_5051_50511102_2_dialog_content = "가, 가까이 오지 마!",
  ui_story_5051_50511102_3_dialog_content = "으윽...",
  ui_story_5051_50511102_4_dialog_content = "어? PlayerName 씨가 도와줬어요?",
  ui_story_5051_50511102_5_dialog_content = "아, 아닌데?",
  ui_story_5051_50511102_6_dialog_content = "야, 이 돌괴물들아. 조심해서 다녀야지.",
  ui_story_5051_50511102_7_dialog_content = "제자가 다치면 내 술은 누가 사 주냐고!",
  ui_story_5051_50511102_8_dialog_content = "...드디어 제가 아는 그 강하고 무서운 게 없는 보아즈 님으로 돌아왔군요!",
  ui_story_5051_50511102_9_dialog_content = "아, 머리가 띵하네. 방금 힘을 너무 썼나?",
  ui_story_5051_50511102_10_dialog_content = "야, 나머지는 너한테 맡길게. 난 이제 안 되겠어...",
  ui_story_5051_50511102_11_dialog_content = "잠깐만요──! 저랑 아직 제정신으로 이야기도 못 나눴잖아요!",
  ui_story_5051_50511102_12_dialog_content = "...정말, 어떻게 이럴 때 잠이 들 수가 있어요? 앞에 했던 말은 취소예요!",
  ui_story_5051_50511102_13_dialog_content = "PlayerName, 그대는 두 사람을 데리고 오른쪽 틈으로 포위를 돌파하라!\n내가 엄호하겠다!",
  ui_story_5051_50511102_14_dialog_content = "우리 그럼... 다른 사람들을 놔두고 도망가는 건가요?",
  ui_story_5051_50511102_15_dialog_content = "우물쭈물대지 마라! <color=#FFB400>반란</color>은 이미 시작되었다.\n여기 있는 매 순간이 지극히 위험하단 말이다!",
  ui_story_5051_50511102_16_dialog_content = "반란...이라고요?",
  ui_story_5051_50511102_17_dialog_content = "저, 전 왜 기억이 안 나죠...? 이 당시의 전 이 일을 알고 있었나요?",
  ui_story_5051_50511102_18_dialog_content = "미아, 무리해서 떠올리지 마!",
  ui_story_5051_50511102_19_dialog_content = "<color=#e8d9bb>휘이익──!</color>",
  ui_story_5051_50511102_20_dialog_content = "뭐지?",
  ui_story_5051_50511102_21_dialog_content = "하늘에서 내려오는 것 같은데요?\n목표를 노리고 일직선으로 내려오는 것 같아요...",
  ui_story_5051_50511102_22_dialog_content = "목표라니... 설마 <color=#FFB400>젊은 성주님</color>?!",
  ui_story_5051_50511102_23_dialog_content = "젊은 성주님은 지금 적한테 둘러싸여 있어요!\n위쪽에서 오는 건 신경을 못 쓰시는 것 같은데요?",
  ui_story_5051_50511102_24_dialog_content = "그럴 리가... 지금의 성주님이라도 눈치챘을 만한 수준이잖아!",
  ui_story_5051_50511102_25_dialog_content = "......",
  ui_story_5051_50511102_26_dialog_content = "다니엘! 위험해요!",
  ui_story_5051_50511102_27_dialog_content = "하아압──!",
  ui_story_5051_50511102_28_dialog_content = "크윽...",
  ui_story_5051_50511102_29_dialog_content = "으아아앗! 엄청 아파 보여요!",
  ui_story_5051_50511102_30_dialog_content = "어깨를 찔린 건가?!",
  ui_story_5051_50511102_31_dialog_content = "지금이다! 주의가 분산된 틈에 여길 떠나야 한다!",
  ui_story_5051_50511102_32_dialog_content = "하, 하지만...",
  ui_story_5051_50511102_33_dialog_content = "아버님!",
  ui_story_5051_50511102_34_dialog_content = "카렌이 아버님을 도울 거예요!",
  ui_story_5051_50511102_35_dialog_content = "그렇습니까?",
  ui_story_5051_50511102_36_dialog_content = "「카렌」...",
  ui_story_5051_50511102_37_dialog_content = "이런! 숨어 있던 카렌이 반란군한테 들켰어!",
  ui_story_5051_50511102_38_dialog_content = "...뭐라?",
  ui_story_5051_50511102_39_dialog_content = "너, 너도 악당이야?",
  ui_story_5051_50511102_40_dialog_content = "꼬마 공주님, 안녕하십니까.",
  ui_story_5051_50511102_41_dialog_content = "카, 카렌은 무서워하지 않아!",
  ui_story_5051_50511102_42_dialog_content = "내 검술은 대단해! 경비병도 많이 이겼다고!",
  ui_story_5051_50511102_43_dialog_content = "안타깝지만 전 그 경비병들처럼 봐드리지 않을 겁니다.",
  ui_story_5051_50511102_44_dialog_content = "으앗...",
  ui_story_5051_50511102_45_dialog_content = "하하하, 아직 전력을 다하지도 않았는데 벌써 넘어지신 겁니까?",
  ui_story_5051_50511102_46_dialog_content = "무리해서 일어서실 필요는 없습니다. 어차피 또 넘어지실 테니까요.",
  ui_story_5051_50511102_47_dialog_content = "으아아앗──!",
  ui_story_5051_50511102_48_dialog_content = "「지배자의 칼날!」",
  ui_story_5051_50511102_49_dialog_content = "어...어떻게...",
  ui_story_5051_50511102_50_dialog_content = "(성주님도 말로는 도망치자고 하면서 역시 못 참고 카렌을 구하시는구나...)",
  ui_story_5051_50511102_51_dialog_content = "카렌... 살았어? 아, 아버님인가요...?",
  ui_story_5051_50511102_52_dialog_content = "......",
  ui_story_5051_50511102_53_dialog_content = "카렌!!!",
  ui_story_5051_50511102_54_dialog_content = "카렌, 어디 다친 데 없는지 엄마가 볼게.",
  ui_story_5051_50511102_55_dialog_content = "어머님, 걱정하지 마세요. 카렌은... 안 다쳤어요.",
  ui_story_5051_50511102_56_dialog_content = "얘도 참, 이럴 때도 큰소리니...",
  ui_story_5051_50511102_57_dialog_content = "...그저 놀랐을 뿐일 것이오.",
  ui_story_5051_50511102_58_dialog_content = "PlayerName 아버님, 카렌을 구해주셔서 정말 감사드려요!",
  ui_story_5051_50511102_59_dialog_content = "그럴 필요는 없소. 내가 마땅히 해야 할 일이니.",
  ui_story_5051_50511102_60_dialog_content = "불쌍한 우리 딸...",
  ui_story_5051_50511102_61_dialog_content = "어머님, 아버님은... 아버님은 괜찮으신가요?",
  ui_story_5051_50511102_62_dialog_content = "너희 아버지는...",
  ui_story_5051_50511102_63_dialog_content = "걱정할 필요 없어. 아버지가 곧 나쁜 사람들을 잡아주실 거야.",
  ui_story_5051_50511102_64_dialog_content = "어머님, 얼른 아버님을 도우러 가세요! 카렌은... 괜찮아요!",
  ui_story_5051_50511102_65_dialog_content = "이 바보야...",
  ui_story_5051_50511102_66_dialog_content = "흐아압!",
  ui_story_5051_50511102_67_dialog_content = "큭...",
  ui_story_5051_50511102_68_dialog_content = "다니엘!",
  ui_story_5051_50511102_69_dialog_content = "걱정할 필요 없소. 저 정도는 혼자서도 충분히 상대할 테니 말이오.",
  ui_story_5051_50511102_70_dialog_content = "하지만 이미 다쳤잖아요... 아무래도 역시...",
  ui_story_5051_50511102_71_dialog_content = "그렇다면 「그대의 부군」은 내가 돕도록 하지. 그대는 여기에 남으시오.",
  ui_story_5051_50511102_72_dialog_content = "네? 위험을 무릅쓰고 그런 일을 하실 필요는 없어요...",
  ui_story_5051_50511102_73_dialog_content = "반란군의 목표는 여러분이 아니라 우리 가족들이니까요.",
  ui_story_5051_50511102_74_dialog_content = "지금 같은 상황에서 그러한 구분이 무슨 의미가 있겠소.",
  ui_story_5051_50511102_75_dialog_content = "기다리고 있으시오.",
  ui_story_5051_50511102_76_dialog_content = "PlayerName, 그대도 쟈키니, 미아와 함께 여기 남아라.",
  ui_story_5051_50511102_77_dialog_content = "금방 돌아오도록 하지.",
  ui_story_5051_50511102_78_dialog_content = "잠깐만요!",
  ui_story_5051_50511102_79_dialog_content = "저, 저도 갈게요.",
  ui_story_5051_50511102_80_dialog_content = "......",
  ui_story_5051_50511102_81_dialog_content = "너는 왼쪽을 맡아라. 나는 오른쪽을 맡으마. 가라!",
  ui_story_5051_50511102_82_dialog_content = "...아, 알겠어요!",
  ui_story_5051_50511102_83_dialog_content = "(착각이겠지...?)",
  ui_story_5051_50511102_84_dialog_content = "(PlayerName 아버님에게서 다니엘의 모습이 보여...)",
  ui_story_5051_50511102_85_dialog_content = "크윽...",
  ui_story_5051_50511102_86_dialog_content = "한참을 기다렸다.",
  ui_story_5051_50511102_87_dialog_content = "뭐라고?",
  ui_story_5051_50511102_88_dialog_content = "훗, 상처는 생각보다 더 가볍군.",
  ui_story_5051_50511102_89_dialog_content = "...처음부터 알고 있었나.",
  ui_story_5051_50511102_90_dialog_content = "쓸데없는 소리는 됐다. 속전속결이다.",
  ui_story_5051_50511102_91_dialog_content = "저, 저도 도울게요!",
  ui_story_5051_50511102_92_dialog_content = "퇴각하라!",
  ui_story_5051_50511102_93_dialog_content = "전원, 조속히 퇴각한다!",
  ui_story_5051_50511102_94_dialog_content = "내게 이런 기회를 준 것에 감사하도록 하지...",
  ui_story_5051_50511102_95_dialog_content = "「빛의 아래에서, 만물은 빛난다!」",
  ui_story_5051_50511102_96_dialog_content = "크아악!",
  ui_story_5051_50511102_97_dialog_content = "내가 말했을 텐데...",
  ui_story_5051_50511102_98_dialog_content = "백야성의 성주 자리는 겉치레가 아니다.",
  ui_story_5051_50511201_1_dialog_content = "허억... 헉... 헉...",
  ui_story_5051_50511201_2_dialog_content = "외숙부님, 괜찮으십니까?",
  ui_story_5051_50511201_3_dialog_content = "시로나?!",
  ui_story_5051_50511201_4_dialog_content = "반나절간 쉬고 오라고 했을 텐데, 어째서 여기 있는 것이냐?",
  ui_story_5051_50511201_5_dialog_content = "아침에 베로니카 공주님의 친구분이 사람을 찾는 걸 도와주겠다고 하셨잖아요?\n저도 같이 도와드릴 수 있을까 해서요...",
  ui_story_5051_50511201_6_dialog_content = "외숙부님 말씀에 따르지 않은 건 죄송합니다.",
  ui_story_5051_50511201_7_dialog_content = "하지만 지금 성안에 갑자기 암귀가 나타났습니다.\n예비 기사로서 전 사람들을 지켜야 마땅하다고 생각합니다!",
  ui_story_5051_50511201_8_dialog_content = "그리고 성을 순찰하는 카르티마 가문 사람들과... 외숙부님도 걱정이 되었습니다.",
  ui_story_5051_50511201_9_dialog_content = "휴, 알겠다.",
  ui_story_5051_50511201_10_dialog_content = "그럼 잘 들어라.\n너는 지금 즉시 돌아가서, 네 외숙모와 동생들을 데리고 백야성을 떠나라!",
  ui_story_5051_50511201_11_dialog_content = "화원에 세워 둔 비공정을 타고 가라.",
  ui_story_5051_50511201_12_dialog_content = "외, 외숙부님... 왜 그러시는 거죠?",
  ui_story_5051_50511201_13_dialog_content = "이유는 묻지 말고 시키는 대로 해라!",
  ui_story_5051_50511201_14_dialog_content = "외숙부님, 거리에 출현한 암귀들을 보니, 왠지 저나 외숙부님을\n먼저 공격할 생각이 없어 보였습니다.",
  ui_story_5051_50511201_15_dialog_content = "어쩌면... 우리 카르티마 가문의 혈통은 암귀의 천적일지도 모릅니다.",
  ui_story_5051_50511201_16_dialog_content = "만약 이번에 가문의 전력을 대거 동원해서 백야성의 암귀를 소탕한다면...",
  ui_story_5051_50511201_17_dialog_content = "성주님께도 중용되어 카르티마 가문의 영광을 되찾을 수 있을 겁니다!",
  ui_story_5051_50511201_18_dialog_content = "모처럼의 기회인데 왜 가족들을 데리고 도망치라고 하시는 겁니까...?",
  ui_story_5051_50511201_19_dialog_content = "네 덕에 하나 더 생각이 났다.\n어쩌면 너희가 백야성을 떠난 후에 다른 암귀를 만날지도 모르지...",
  ui_story_5051_50511201_20_dialog_content = "내 서재에는 카르티마 가문에 대대로 전승되어 온 태도 「화람」이 놓여 있다.",
  ui_story_5051_50511201_21_dialog_content = "그것도 반드시 가져가라!",
  ui_story_5051_50511201_22_dialog_content = "외숙부님, 전 도저히 모르겠어요...",
  ui_story_5051_50511201_23_dialog_content = "어쩌면 그 예언은 옳았을지도 모르겠군.\n그저 내가 믿으려 하지 않았을 뿐이지.",
  ui_story_5051_50511201_24_dialog_content = "카르티마 가문을 구할 수 있는 건... 너다.",
  ui_story_5051_50511201_25_dialog_content = "나는 아니었던 것이다.",
  ui_story_5051_50511201_26_dialog_content = "......",
  ui_story_5051_50511201_27_dialog_content = "지금 일들도... 그때랑 똑같나요?",
  ui_story_5051_50511201_28_dialog_content = "크게 다르지 않다.",
  ui_story_5051_50511201_29_dialog_content = "다만 당시 카렌의 상처는 조금 더 깊었다.\n게다가 나도 그 자리에서 카렌을 지켜줄 수 없었지.",
  ui_story_5051_50511201_30_dialog_content = "그래서 카렌 목소리가 들렸을 때 자기도 모르게 달려가셨던 거군요.",
  ui_story_5051_50511201_31_dialog_content = "그때 후회하셨던 일을 바로잡고 싶으신 건가요?",
  ui_story_5051_50511201_32_dialog_content = "후회하지 않는다고 한다면 분명히 거짓말일 것이다.",
  ui_story_5051_50511201_33_dialog_content = "카렌은 어때?",
  ui_story_5051_50511201_34_dialog_content = "크게 안 다쳤어요. 손발이 조금 까진 정도예요.",
  ui_story_5051_50511201_35_dialog_content = "그것보다 당신... 어깨에서 피가 나잖아요.",
  ui_story_5051_50511201_36_dialog_content = "이까짓 상처는 모기에 물린 거나 다름없어.",
  ui_story_5051_50511201_37_dialog_content = "같이 검술 훈련을 안 한 지도 꽤 오래됐네요.",
  ui_story_5051_50511201_38_dialog_content = "옛날 같으면 아까 정도의 기습으로 다칠 일은 절대 없었을 텐데요...",
  ui_story_5051_50511201_39_dialog_content = "일이 갑자기 벌어진 탓에 조금 흐트러진 것이겠지.",
  ui_story_5051_50511201_40_dialog_content = "「솔라드 가문의 날」을 축하하는 자리에 암귀를 데려와 성을 기습하더니,\n곧바로 사병을 동원해 암살을 시도하다니...",
  ui_story_5051_50511201_41_dialog_content = "누가 우리에게 이렇게 큰 원한을 품고 있는 거죠?",
  ui_story_5051_50511201_42_dialog_content = "성주 전하, 공작부인 전하.",
  ui_story_5051_50511201_43_dialog_content = "늦어서 죄송합니다.",
  ui_story_5051_50511201_44_dialog_content = "저와 부대원들의 실책으로 전하와 공주님을 다치게 만들고 말았습니다...",
  ui_story_5051_50511201_45_dialog_content = "미즈 로트, 당신 잘못이 아니야.",
  ui_story_5051_50511201_46_dialog_content = "당신은 백성들의 안전을 지켰어. 그것이야말로 당신들의 책무야.",
  ui_story_5051_50511201_47_dialog_content = "...감사합니다, 공작부인 전하.",
  ui_story_5051_50511201_48_dialog_content = "다른 보고할 내용이 있나?",
  ui_story_5051_50511201_49_dialog_content = "네, 성주 전하.",
  ui_story_5051_50511201_50_dialog_content = "조금 전 근처 일대를 수색한 끝에 반란군의 일원 몇 명을 생포했습니다.",
  ui_story_5051_50511201_51_dialog_content = "좋다. 뭘 알아냈지? 말해 보도록.",
  ui_story_5051_50511201_52_dialog_content = "그들이 지니고 있는 무기에서 특수한 문양을 확인했습니다.",
  ui_story_5051_50511201_53_dialog_content = "그리고 그 문양은 카르티마 가문의 문장이었습니다.",
  ui_story_5051_50511201_54_dialog_content = "카르티마 가문이라고?",
  ui_story_5051_50511201_55_dialog_content = "며칠 전 마임 씨의 부인과 만찬에서 즐겁게 담소도 나눴는걸...",
  ui_story_5051_50511201_56_dialog_content = "두 아이도 카렌의 또래였고...",
  ui_story_5051_50511201_57_dialog_content = "아니야... 너무 이상해.",
  ui_story_5051_50511201_58_dialog_content = "반란군이 왜 자기 정체를 폭로할 무기를 몸에 지니고 있었을까?",
  ui_story_5051_50511201_59_dialog_content = "오만한 자일수록 단순하기 마련이야.",
  ui_story_5051_50511201_60_dialog_content = "분명히 오늘 날 없애고 「솔라드 가문」의 통치를 끝낼 수 있으리라 생각했겠지.",
  ui_story_5051_50511201_61_dialog_content = "미즈 로트.",
  ui_story_5051_50511201_62_dialog_content = "네, 성주 전하.",
  ui_story_5051_50511201_63_dialog_content = "심판소에 알려라.\n카르티마 가문은 반란을 기도했고, 그 증거 또한 명백하다.",
  ui_story_5051_50511201_64_dialog_content = "반드시 카르티마 가문 <color=#FFB400>전원</color>을 지금 즉시 체포해야 한다.",
  ui_story_5051_50511201_65_dialog_content = "심판소는 긴급 체포령을 작성하고, 우리의 체포 임무 수행에 협조하라.",
  ui_story_5051_50511201_66_dialog_content = "수배자가 저항할 경우 현장에서 즉결 처분하도록.",
  ui_story_5051_50511201_67_dialog_content = "알겠습니다, 성주 전하.",
  ui_story_5051_50511201_68_dialog_content = "「카르티마 가문 전원」이라고요? 다니엘, 지금 그게 무슨...",
  ui_story_5051_50511201_69_dialog_content = "올해는 이미 이런 일들이 너무 많았어요.",
  ui_story_5051_50511201_70_dialog_content = "피로스, 고티에 가문... 그 많은 피를 보고도 부족한가요?",
  ui_story_5051_50511201_71_dialog_content = "조슈아...",
  ui_story_5051_50511201_72_dialog_content = "카렌은 지금 휴식을 취해야 해. 데리고 먼저 돌아가 있어.",
  ui_story_5051_50511201_73_dialog_content = "......",
  ui_story_5051_50511201_74_dialog_content = "마침 잘 됐군, 조슈아... 부인, 나도 내 아이를 데리고 떠나려던 참이오.",
  ui_story_5051_50511201_75_dialog_content = "내가 가는 길을 바래다주겠소.",
  ui_story_5051_50511201_76_dialog_content = "호의는 고마워요.",
  ui_story_5051_50511201_77_dialog_content = "하지만 성안의 암귀는 이미 다 쓰러졌으니,\n저 혼자 아이를 데리고 돌아갈 수 있을 거예요.",
  ui_story_5051_50511201_78_dialog_content = "내 기억이 맞다면, 「스카이워커」 선생이라고 했던가?",
  ui_story_5051_50511201_79_dialog_content = "그렇소.",
  ui_story_5051_50511201_80_dialog_content = "아까 귀하에게 의심을 품은 점은 사과하도록 하지.",
  ui_story_5051_50511201_81_dialog_content = "암귀를 상대하는 귀하의 능력을 보니,\n확실히 귀하의 말처럼 적지 않은 경험이 있겠더군.",
  ui_story_5051_50511201_82_dialog_content = "그토록 뛰어난 능력을 가진 이가 이름 없이 묻혀 있어서는 안 되는 법이다.",
  ui_story_5051_50511201_83_dialog_content = "오늘 대접에는 부족함이 많았으니, 일이 마무리되고 나면\n다시 이야기를 나눌 수 있길 기대하지.",
  ui_story_5051_50511201_84_dialog_content = "나는 평범한 늙은이에 불과하네.",
  ui_story_5051_50511201_85_dialog_content = "그저 내 아이가 무사히 집에 돌아가는 것을 바랄 뿐일세.",
  ui_story_5051_50511201_86_dialog_content = "안타깝군, 난 우리가 말이 잘 통할 줄 알았는데.",
  ui_story_5051_50511201_87_dialog_content = "너무 닮은 사람끼리는 친구로 적합하지 않을지도 모르는 법이지.",
  ui_story_5051_50511201_88_dialog_content = "하, 그러한가?",
  ui_story_5051_50511201_89_dialog_content = "베로니카, 이제 가자.",
  ui_story_5051_50511201_90_dialog_content = "저? 저요?",
  ui_story_5051_50511201_91_dialog_content = "여기 베로니카라는 사람이 또 있기라도 한 것이냐?",
  ui_story_5051_50511201_92_dialog_content = "그럼 이제 어딜 가는 건가요?",
  ui_story_5051_50511201_93_dialog_content = "반란군 카르티마 가문의 잔당을 체포하러 간다.",
  ui_story_5051_50511201_94_dialog_content = "오늘부터 너는 나와 함께 싸우는 법을 배우는 게 좋겠구나.",
  ui_story_5051_50511201_95_dialog_content = "아, 아버님은 제가 그럴 자격이 있다고 생각하시는 건가요...?",
  ui_story_5051_50511201_96_dialog_content = "베로니카 공주의 실력은 이미 모두가 친히 보았지 않은가.",
  ui_story_5051_50511201_97_dialog_content = "허나 아직 나이가 어리고, 오늘은 이미 많은 체력을 썼겠지.",
  ui_story_5051_50511201_98_dialog_content = "그러니 일찍 쉬게 하는 게 좋지 않겠나.",
  ui_story_5051_50511201_99_dialog_content = "스카이워커 선생, PlayerName에게는 휴식이 필요할지도 모르지만,\n베로니카는 내 딸이다.",
  ui_story_5051_50511201_100_dialog_content = "각자 자기 자식만 잘 돌보면 될 일이다.",
  ui_story_5051_50511201_101_dialog_content = "<size=30>아, 저기...</size>",
  ui_story_5051_50511201_102_dialog_content = "공주는 지금 휴식이 필요하네.",
  ui_story_5051_50511201_103_dialog_content = "베로니카에게 필요한 건 배움이다.",
  ui_story_5051_50511201_104_dialog_content = "<size=45>잠깐만요!</size>",
  ui_story_5051_50511201_105_dialog_content = "흐음?",
  ui_story_5051_50511201_106_dialog_content = "저, 전...",
  ui_story_5051_50511201_107_dialog_content = "같이 가고 싶어요!",
  ui_story_5051_50511201_108_dialog_content = "?!",
  ui_story_5051_50511201_109_dialog_content = "아버님께서 이렇게 제 능력을 인정해 주신 건 처음이에요...",
  ui_story_5051_50511201_110_dialog_content = "저, 전 다시는 아버님이 실망하시게 만들고 싶지 않아요!",
  ui_story_5051_50511201_111_dialog_content = "<size=30>그리고... 확인하고 싶어요.\n제가 경험하지 못한 이 역사가 대체 어떤 것이었을지 말이에요.</size>",
  ui_story_5051_50511201_112_dialog_content = "......",
  ui_story_5051_50511201_113_dialog_content = "베로니카, 가자!",
  ui_story_5051_50511201_114_dialog_content = "네, 네!",
  ui_story_5051_50511201_115_dialog_content = "그럼 저도 같이 갈게요!",
  ui_story_5051_50511201_116_dialog_content = "...참으로 제멋대로로군.",
  ui_story_5051_50511201_117_dialog_content = "저기, 늙은 성주님, 보아즈 님도 지금 너무 깊이 잠든 게 어딘가 이상해요...",
  ui_story_5051_50511201_118_dialog_content = "공작부인님이 데려가서 치료해 준다고 하셨거든요.\n그, 그래서 저도 같이 가 봐야 할 것 같아요.",
  ui_story_5051_50511201_119_dialog_content = "혹시 다른 데 가실 일이 있으면 꼭 몸조심하세요.",
  ui_story_5051_50511201_120_dialog_content = "그리고 꼭 오늘 하루가 끝나기 전에 돌아오셔야 돼요.\n안 그러면 우린 영원히 이 안에 갇혀버릴지도 몰라요...",
  ui_story_5051_50511201_121_dialog_content = "...알겠다.",
  ui_story_5051_50511201_122_dialog_content = "그런데 방금 날 뭐라고 불렀지?",
  ui_story_5051_50511201_123_dialog_content = "앗... 실수했네요.",
  ui_story_5051_50511201_124_dialog_content = "아무튼 빨리 돌아오세요!",
  ui_story_5051_50511201_125_dialog_content = "<color=#e8d9bb>아우토의 저택</color>",
  ui_story_5051_50511201_126_dialog_content = "트로이 공작, 그대는 이 일을 이미 알고 있었겠지?",
  ui_story_5051_50511201_127_dialog_content = "으음? 하메스 공작, 어느 일 말씀이신지?",
  ui_story_5051_50511201_128_dialog_content = "지금 바깥이 대혼란인 상황에서 내게 시치미를 뗄 필요는 없지 않겠나.",
  ui_story_5051_50511201_129_dialog_content = "아! 누군가가 암귀로 혼란을 일으키고, 그 틈에 성주님을 암살하려 한 일 말입니까?",
  ui_story_5051_50511201_130_dialog_content = "그렇네!",
  ui_story_5051_50511201_131_dialog_content = "아무리 솔라드의 방식이 마음에 들지 않는다 해도,\n그런 비열한 수단은 우리 가문의 이름만 더럽힐 뿐입니다만.",
  ui_story_5051_50511201_132_dialog_content = "그럼 정말 몰랐는가?",
  ui_story_5051_50511201_133_dialog_content = "맙소사, 하메스 공작.\n꼭 그렇게 온종일 의심을 품고, 누구든 다 의심해 봐야 하는 겁니까?",
  ui_story_5051_50511201_134_dialog_content = "트로이 공작을 의심하는 건 아닐세.",
  ui_story_5051_50511201_135_dialog_content = "게다가... 그대도 알고 있겠지.\n하메스 가문의 자식들은 모두 이미 기사단에 소속되어 있네.",
  ui_story_5051_50511201_136_dialog_content = "솔라드는 지금 기사단을 내세워 움브라톤을 지원하려 하고 있네.\n나는 그 결정에 줄곧 반대해 왔고 말이야!",
  ui_story_5051_50511201_137_dialog_content = "애초에 땅에서 설치는 그 암귀 놈은 우리 백야성에 해가 되지 못한다.",
  ui_story_5051_50511201_138_dialog_content = "그런데 왜 굳이 우리가 제 발로 죽으러 가야 하냔 말이다.",
  ui_story_5051_50511201_139_dialog_content = "이렇게 생각하는 사람이 나 혼자는 아니지 않겠나?",
  ui_story_5051_50511201_140_dialog_content = "하메스 공작, 성주님도 다 생각이 있으시지 않겠습니까.",
  ui_story_5051_50511201_141_dialog_content = "움브라톤을 지켜내면 움브라톤에 대한 우리의 지배권을 공고히 할 수 있지 않습니까.",
  ui_story_5051_50511201_142_dialog_content = "그 정도 이치를 하메스 공작이 모를 리는 없을 텐데요.",
  ui_story_5051_50511201_143_dialog_content = "흥, 그런 미미한 이익조차 때가 되면 솔라드 혼자만의 것이 될 게 뻔하지 않은가.",
  ui_story_5051_50511201_144_dialog_content = "그러고도 「솔라드 가문의 날」을 축하하니 마니 참으로 염치도 없군.",
  ui_story_5051_50511201_145_dialog_content = "백야성이 오늘까지 온 것은 하메스와 트로이 양대 가문의 공 덕분이거늘!",
  ui_story_5051_50511201_146_dialog_content = "어찌 그 과실은 전부 솔라드 가문이 차지한단 말인가.",
  ui_story_5051_50511201_147_dialog_content = "카르티마 가문이 미리 계획을 밝히고 우리 가문들이 연합했더라면...",
  ui_story_5051_50511201_148_dialog_content = "솔라드를 두려워할 필요가 있었겠나?",
  ui_story_5051_50511201_149_dialog_content = "하메스 공작, 말씀을 좀 가려서 하시지요...",
  ui_story_5051_50511201_150_dialog_content = "방금 알게 된 소식입니다만, 성주님은 이미 카르티마 가문 전원을\n체포하라는 명을 내리셨습니다.",
  ui_story_5051_50511201_151_dialog_content = "저들에게 어떤 말로가 있을지 상상하는 건 어렵지 않을 겁니다.",
  ui_story_5051_50511201_152_dialog_content = "기껏해야 또 피로스와 고티에 가문 같은 꼴이 되지 않겠나?",
  ui_story_5051_50511201_153_dialog_content = "휴, 아직도 모르겠습니까? 그게 바로 문제입니다.",
  ui_story_5051_50511201_154_dialog_content = "음? 그 말인즉슨...",
  ui_story_5051_50511201_155_dialog_content = "잠깐, 알겠네. 이걸로 전부 이어지는군!",
  ui_story_5051_50511201_156_dialog_content = "이 어리석은 카르티마가!",
  ui_story_5051_50511201_157_dialog_content = "저들의 모반은 오히려 솔라드의 권위를 높일 기회만 주고 말았네...",
  ui_story_5051_50511201_158_dialog_content = "솔라드는 이 기회에 기사단뿐만 아니라 사병을 가진 모든 가문을\n움브라톤으로 보내버릴 수 있겠지.",
  ui_story_5051_50511201_159_dialog_content = "마임 카르티마! 이 사지만 멀쩡한 아둔한 녀석!",
  ui_story_5051_50511201_160_dialog_content = "하메스 공작, 이렇게 된 이상 말을 아끼시는 게 현명할 겁니다.",
  ui_story_5051_50511201_161_dialog_content = "방금 전 이야기는 졸다가 못 들은 것으로 하지요.",
  ui_story_5051_50511201_162_dialog_content = "...고맙네, 트로이 공작. 그럼 나도 이만 실례하지.",
  ui_story_5051_50511201_163_dialog_content = "여봐라.",
  ui_story_5051_50511201_164_dialog_content = "예.",
  ui_story_5051_50511201_165_dialog_content = "카르티마 가문과 주고받은 서신을 모두 깨끗이 처리해라.",
  ui_story_5051_50511201_166_dialog_content = "<color=#e8d9bb>콰당!</color>",
  ui_story_5051_50511201_167_dialog_content = "무슨 일이냐?!",
  ui_story_5051_50511201_168_dialog_content = "확인해 보겠습니다.",
  ui_story_5051_50511201_169_dialog_content = "누구였는지 보았나?",
  ui_story_5051_50511201_170_dialog_content = "루시 아가씨였습니다. 공작님께서 저녁 식사 전에 만나기로 하셨었습니다.",
  ui_story_5051_50511201_171_dialog_content = "아가씨는 계속 밖에서 기다리고 계셨습니다.",
  ui_story_5051_50511201_172_dialog_content = "그런데 조금 전 당황하면서 달려가시더군요.",
  ui_story_5051_50511201_173_dialog_content = "정말 하나같이 신경을 쓰게 만드는군...",
  ui_story_5051_50511301_1_dialog_content = "성주 전하, 카르티마 가문의 이 저택에서는 아무것도 찾을 수 없었습니다.",
  ui_story_5051_50511301_2_dialog_content = "현재 카르티마 가문이 하이가든에 소유한 부동산은 모두 압류했습니다.\n하인 외에 다른 무장 인원은 없었습니다.",
  ui_story_5051_50511301_3_dialog_content = "경고에도 멋대로 백야성을 떠난 비공정 한 척을 제외하면...",
  ui_story_5051_50511301_4_dialog_content = "나머지 사람들은 아마 아직도 전부 백야성 안에 숨어 있을 겁니다.",
  ui_story_5051_50511301_5_dialog_content = "미드가든과 다운타운 쪽 상황은?",
  ui_story_5051_50511301_6_dialog_content = "이미 사람을 보내 조사하고 있습니다만,\n상황을 확인하려면 조금 더 시간이 필요합니다.",
  ui_story_5051_50511301_7_dialog_content = "도망치지 않고 백야성 안에 숨어 있다라...",
  ui_story_5051_50511301_8_dialog_content = "아무래도 아직 반격의 기회를 기다리는 모양이군.",
  ui_story_5051_50511301_9_dialog_content = "카르티마 가문은 수도 많고, 최근에는 저들에게 가세한 이들도 많았습니다.",
  ui_story_5051_50511301_10_dialog_content = "아무래도 지금 상황은 생각보다 더 위험해 보입니다...",
  ui_story_5051_50511301_11_dialog_content = "이대로 가만히 당할 순 없지.",
  ui_story_5051_50511301_12_dialog_content = "계속해서 미드가든을 수색하라.",
  ui_story_5051_50511301_13_dialog_content = "잠깐 기다리게.",
  ui_story_5051_50511301_14_dialog_content = "오, 오셨군요!",
  ui_story_5051_50511301_15_dialog_content = "......",
  ui_story_5051_50511301_16_dialog_content = "<size=30>미아, 무서워하지 마라. 너를 데려가기 위해 온 것이 아니다.</size>",
  ui_story_5051_50511301_17_dialog_content = "<size=30>나도 생각해 보았다. 너는 이 역사를 알 권리가 있다.</size>",
  ui_story_5051_50511301_18_dialog_content = "호오? 스카이워커 선생, 역시 곧 다시 만나게 되리라 생각했다.",
  ui_story_5051_50511301_19_dialog_content = "다만 이렇게 빠를 줄은 몰랐는데 말이야.",
  ui_story_5051_50511301_20_dialog_content = "귀하에게 필요한 단서를 내가 알고 있을지도 모른다는 생각이 갑자기 들더군.",
  ui_story_5051_50511301_21_dialog_content = "시간을 끌지 않았으면 좋겠다만.",
  ui_story_5051_50511301_22_dialog_content = "물론 그래야지.\n나도 내 반항적인 아이가 한시라도 빨리 나와 함께 돌아가길 바랄 뿐이네.",
  ui_story_5051_50511301_23_dialog_content = "그 전에, 정보의 출처는 추궁하지 않겠다고 약조해 주었으면 좋겠군.",
  ui_story_5051_50511301_24_dialog_content = "좋다. 정보의 출처는 묻지 않도록 하지.\n그럼 어떤 단서인지 어디 들어보도록 할까.",
  ui_story_5051_50511301_25_dialog_content = "다운타운 구역의 미개척 황야에 최근 사병들이 주둔한 듯한 흔적이 있다.",
  ui_story_5051_50511301_26_dialog_content = "미즈 로트, 이에 대해 아는 바가 있나?",
  ui_story_5051_50511301_27_dialog_content = "성밖과 가까운 황야라면...",
  ui_story_5051_50511301_28_dialog_content = "혹시 저 암석 구릉 지대 말씀이실까요?",
  ui_story_5051_50511301_29_dialog_content = "확실히 그 땅에서는 가끔 기괴한 동물의 울음소리가 들리고,\n주변에는 인기척이 없다고 들었습니다만...",
  ui_story_5051_50511301_30_dialog_content = "스카이워커 선생, 지금 그 말은 카르티마 가문의 일원이\n그곳에 숨어 있을 가능성이 높다는 뜻인가?",
  ui_story_5051_50511301_31_dialog_content = "반드시 그곳에 있네.",
  ui_story_5051_50511301_32_dialog_content = "어째서 그렇게까지 단언할 수 있는 거지? 대체 어디서 입수한 정보인가?",
  ui_story_5051_50511301_33_dialog_content = "출처는 추궁하지 않겠다고 약조했을 터인데.",
  ui_story_5051_50511301_34_dialog_content = "대신 약속하지. 그것이 거짓 정보라면 그 어떠한 처벌도 감수하겠네.",
  ui_story_5051_50511301_35_dialog_content = "좋다. 미즈 로트, 우선 그 황야로 가도록 하지.",
  ui_story_5051_50511301_36_dialog_content = "성주 전하, 정말 믿어도 될까요?",
  ui_story_5051_50511301_37_dialog_content = "카르티마 가문은 조만간 투항한다.",
  ui_story_5051_50511301_38_dialog_content = "한 번쯤 믿어보더라도 우리에겐 해가 되지 않을 것이다.",
  ui_story_5051_50511301_39_dialog_content = "물론, 다른 지역의 수색을 멈춰서는 안 된다.",
  ui_story_5051_50511301_40_dialog_content = "알겠습니다, 성주 전하.",
  ui_story_5051_50511301_41_dialog_content = "음...",
  ui_story_5051_50511301_42_dialog_content = "뭔가 말하고 싶은 모양이군.",
  ui_story_5051_50511301_43_dialog_content = "아까 그 단서는 당시에 누가 성주님한테 알려줬던 건가요?",
  ui_story_5051_50511301_44_dialog_content = "아니다. 그때 우리는 성안에서 유용한 정보를 찾아내지 못했었지.",
  ui_story_5051_50511301_45_dialog_content = "그러다 밤이 되어서야 황야의 수상한 움직임을 눈치챘고,\n반란군의 거센 공격을 받게 되었다.",
  ui_story_5051_50511301_46_dialog_content = "허나 저들은 끝내 패배의 운명을 피할 수 없었다.",
  ui_story_5051_50511301_47_dialog_content = "그럼 우리가 조금이라도 빨리 돌아갈 수 있게 역사를 앞당긴 건가요?",
  ui_story_5051_50511301_48_dialog_content = "때로는 그런 생각이 들더군.\n만약 그때 내가 반란군을 한시라도 더 빨리 찾아냈다면...",
  ui_story_5051_50511301_49_dialog_content = "여러 해 동안 나를 따랐던 그 병사들도 지금쯤 저들을\n근심케 할 자녀를 여럿 두고 있었겠지.",
  ui_story_5051_50511301_50_dialog_content = "솔라드 씨는 계속 우리가 이 세계를 바꿔버릴까 무서워하셨잖아요?",
  ui_story_5051_50511301_51_dialog_content = "이미 많은 영향을 끼쳤다. 지금에 와서 하나 더 늘어난들 마찬가지가 아닌가.",
  ui_story_5051_50511301_52_dialog_content = "왠지... 제가 아는 성주님이랑은 다르게 보이시네요.",
  ui_story_5051_50511301_53_dialog_content = "그러한가. 확실히 성주라는 신분을 내려놓고 보니\n스스로도 어딘가 다르다는 생각이 드는군.",
  ui_story_5051_50511301_54_dialog_content = "특히 과거의 나와 만난 뒤로 말이지...",
  ui_story_5051_50511301_55_dialog_content = "여기인가?",
  ui_story_5051_50511301_56_dialog_content = "정찰병의 보고에 따르면 확실히 카르티마 가문 사람들이\n전방의 언덕에 모여 있다고 합니다.",
  ui_story_5051_50511301_57_dialog_content = "구릉지에 배수진을 치고 끝까지 저항하려는 것 같습니다!",
  ui_story_5051_50511301_58_dialog_content = "베로니카, 말해봐라.",
  ui_story_5051_50511301_59_dialog_content = "지금과 같은 상황에서 네가 지휘관이라면, 어떻게 할 것이냐.",
  ui_story_5051_50511301_60_dialog_content = "저라면...",
  ui_story_5051_50511301_61_dialog_content = "사절을 보내서 감정을 자극하고, 이치로 깨닫게 할 거예요.",
  ui_story_5051_50511301_62_dialog_content = "저들이 스스로 잘못을 인정하고, 앞으로의 공으로 과를 만회할 수 있도록요.",
  ui_story_5051_50511301_63_dialog_content = "틀렸다, 베로니카.",
  ui_story_5051_50511301_64_dialog_content = "네가 더 큰 책임을 짊어지는 자가 되길 원한다면,\n반드시 <color=#FFB400>수단을 가리지 않고</color> 승리를 쟁취해야 한다.",
  ui_story_5051_50511301_65_dialog_content = "수단을 가리지 않고... 승리를 쟁취...",
  ui_story_5051_50511301_66_dialog_content = "위로는 하이가든, 아래로는 움브라톤까지,\n수많은 눈이 이 싸움의 향방을 주시하고 있다.",
  ui_story_5051_50511301_67_dialog_content = "모두 우리가 승패를 가르기를 기다리고 있는 것이다.\n저들은 오직 승자에게만 찬사를 보낸다. 그 승자가 누구인지는 무관하지.",
  ui_story_5051_50511301_68_dialog_content = "전장에서 승자는 왕이 되고, 패자는 도적이 되는 것이다.",
  ui_story_5051_50511301_69_dialog_content = "백야성의 역사는 지금부터 바뀔지도 모른다.",
  ui_story_5051_50511301_70_dialog_content = "베로니카, 네가 배워야 할 것들은 아직 너무나도 많다.",
  ui_story_5051_50511301_71_dialog_content = "수단을 가리지 않는다... 저 가치관은 조금... 찬성하기 힘든데요.",
  ui_story_5051_50511301_72_dialog_content = "그러한가.",
  ui_story_5051_50511301_73_dialog_content = "(아, 생각 못 했네... 과거의 솔라드 씨를 비판하는 건\n지금의 솔라드 씨를 비판하는 셈이잖아?!)",
  ui_story_5051_50511301_74_dialog_content = "아, 저기... 성주님을 뭐라고 하려던 건 아니었어요...",
  ui_story_5051_50511301_75_dialog_content = "높은 곳에 서면 어떤 일들은 자기 뜻대로 되지 않는 법이다...\n비록 책임을 회피하는 변명처럼 들리겠지만 말이지.",
  ui_story_5051_50511301_76_dialog_content = "지금의 나는 자신이 그 어떤 결점도 없는 위인이라고\n주저 없이 말하지는 않을 것이다.",
  ui_story_5051_50511301_77_dialog_content = "그저...",
  ui_story_5051_50511301_78_dialog_content = "그대가 미래에 성장하는 과정에서 새로운 길을 개척하여,\n자신만의 길을 나아가길 빌어줄 뿐이다.",
  ui_story_5051_50511301_79_dialog_content = "...네!",
  ui_story_5051_50511301_80_dialog_content = "나이가 들었을 때 젊은 시절의 자신을 후회하는 일이 없었으면 좋겠네요.",
  ui_story_5051_50511301_81_dialog_content = "아... 서, 성주님을 놀리려는 뜻은 아니었어요!",
  ui_story_5051_50511301_82_dialog_content = "하하하하!",
  ui_story_5051_50511301_83_dialog_content = "(솔라드 씨가 저렇게 통쾌하게 웃는 건 처음 보는 것 같아.)",
  ui_story_5051_50511301_84_dialog_content = "(이제 알겠어... 어쩌면 지금 눈앞의 나이 든 성주님과 젊은 성주님 외에도...)",
  ui_story_5051_50511301_85_dialog_content = "(더 옛날까지 거슬러 올라간 세계에는 아직 세상 물정 모르는,\n마음껏 소리 내서 웃을 수 있는... 다니엘 씨가 있었겠지.)",
  ui_story_5051_50511301_86_dialog_content = "앞에 무언가 움직임이 보이는군.",
  ui_story_5051_50511301_87_dialog_content = "...매복 중인 반란군입니다!",
  ui_story_5051_50511302_1_dialog_content = "(중요한 방들은 전부 찾아봤어.)",
  ui_story_5051_50511302_2_dialog_content = "(그런데 왜 없는 거지?!)",
  ui_story_5051_50511302_3_dialog_content = "(설마 솔라드 녀석, 남이 모르는 밀실이라도 만든 건가?)",
  ui_story_5051_50511302_4_dialog_content = "(분명히 그렇겠지.)",
  ui_story_5051_50511302_5_dialog_content = "(그 녀석의 성격이라면, 분명히 누나에게 숨긴 비밀이 많을 테니까.)",
  ui_story_5051_50511302_6_dialog_content = "(밀실 입구는... 솔라드의 서재 안에 있나?)",
  ui_story_5051_50511302_7_dialog_content = "(음? 책장 위에 저건 설마...)",
  ui_story_5051_50511302_8_dialog_content = "(「영원한 기억의 수정」?!)",
  ui_story_5051_50511302_9_dialog_content = "(틀림없어, 「영원한 기억의 수정」이야!)",
  ui_story_5051_50511302_10_dialog_content = "(가장 위험한 곳이야말로 가장 안전한 곳이라 이건가...)",
  ui_story_5051_50511302_11_dialog_content = "(하하하하하...)",
  ui_story_5051_50511302_12_dialog_content = "(솔라드 녀석, 이런 귀한 물건을 이렇게 아무렇게나 놔둘 줄이야.)",
  ui_story_5051_50511302_13_dialog_content = "(마치 내 소중한 누나를 경시한 것처럼...)",
  ui_story_5051_50511302_14_dialog_content = "(공작부인 전하, 돌아오셨습니까!)",
  ui_story_5051_50511302_15_dialog_content = "(누나다...)",
  ui_story_5051_50511302_16_dialog_content = "많이 당황한 것 같은데, 무슨 일일까?",
  ui_story_5051_50511302_17_dialog_content = "...제 무능함을 용서해 주십시오!",
  ui_story_5051_50511302_18_dialog_content = "오늘 오후에 경비병 한 명이 누군가의 손에 기절했고,\n지금도 병실에 누워 있습니다...",
  ui_story_5051_50511302_19_dialog_content = "하지만 온 저택을 수색했음에도 침입자를 찾지 못했습니다...",
  ui_story_5051_50511302_20_dialog_content = "또 카르티마 가문 사람일까?",
  ui_story_5051_50511302_21_dialog_content = "알겠어.",
  ui_story_5051_50511302_22_dialog_content = "오늘 밤은 손님도 계시니까, 밖에서 신경 써서 지켜봐 줘.",
  ui_story_5051_50511302_23_dialog_content = "알겠습니다, 공작부인 전하!",
  ui_story_5051_50511302_24_dialog_content = "그리고 부상당한 경비병에겐 안심하고 요양하라고 말해 줘.",
  ui_story_5051_50511302_25_dialog_content = "치료비는 내가 부담할게.",
  ui_story_5051_50511302_26_dialog_content = "감사합니다, 공작부인 전하!",
  ui_story_5051_50511302_27_dialog_content = "카르티마 가문...",
  ui_story_5051_50511302_28_dialog_content = "너도 카르티마 가문에 아는 사람이 있니?",
  ui_story_5051_50511302_29_dialog_content = "네... 근데 그 사람도 반란군의 일당인지는 모르겠어요.",
  ui_story_5051_50511302_30_dialog_content = "하지만 분명히 무척 착하고 정직한 사람처럼 보였어요...",
  ui_story_5051_50511302_31_dialog_content = "나중에 꼭 위엄 있는 기사장이 되고 싶다고도 했거든요!",
  ui_story_5051_50511302_32_dialog_content = "어쩌면 네 친구는 사정을 잘 몰랐을지도 모르겠네.",
  ui_story_5051_50511302_33_dialog_content = "붙잡히면... 어떻게 될까요?",
  ui_story_5051_50511302_34_dialog_content = "지금은 아직 모르겠어.",
  ui_story_5051_50511302_35_dialog_content = "그래도 안심해. 무고한 사람은 내가 최선을 다해서 지켜줄 테니까.",
  ui_story_5051_50511302_36_dialog_content = "그 사람 가문이 공작부인님과 가족을 암살하려고 했는데도요?",
  ui_story_5051_50511302_37_dialog_content = "죄가 있는 자는 벌을 받아야 마땅해.",
  ui_story_5051_50511302_38_dialog_content = "하지만 혈연이라는 이유만으로 무고한 사람까지 연루돼서는 안 돼...",
  ui_story_5051_50511302_39_dialog_content = "이 이야기는 일단 그만하자.",
  ui_story_5051_50511302_40_dialog_content = "난 우선 저녁 식사와 보아즈 씨의 해장 요리를 준비할게.",
  ui_story_5051_50511302_41_dialog_content = "...성주님이 걱정되진 않으세요?",
  ui_story_5051_50511302_42_dialog_content = "후훗, 물론 걱정되지~",
  ui_story_5051_50511302_43_dialog_content = "하지만 난 다니엘을 믿고 싶어. 분명히 무사할 거야.",
  ui_story_5051_50511302_44_dialog_content = "그러니까 저녁을 준비하고 돌아오길 기다려야지~",
  ui_story_5051_50511302_45_dialog_content = "공작부인님... 벌써부터 공작부인님이 그리워질 것 같아요!",
  ui_story_5051_50511302_46_dialog_content = "그럼 쟈키니도 앞으로는 언제든지 백야성에 놀러 오렴~",
  ui_story_5051_50511302_47_dialog_content = "베로니카랑 카렌도 너 같은 친구를 무척 좋아할 거야.",
  ui_story_5051_50511302_48_dialog_content = "흐아앙!",
  ui_story_5051_50511302_49_dialog_content = "쉿──",
  ui_story_5051_50511302_50_dialog_content = "보아즈 씨랑 카렌이 아직 자고 있으니까, 깨우지 않게 조심해야지~",
  ui_story_5051_50511401_1_dialog_content = "(암귀를 이용해 혼란을 일으키면 쉽게 솔라드를 잡을 수 있을 거라 생각했건만.)",
  ui_story_5051_50511401_2_dialog_content = "(역시 내가 솔라드의 실력을 우습게 봤던 모양이군.)",
  ui_story_5051_50511401_3_dialog_content = "(몸이 좋지 않다고 대외적으로 발표했던 것은... 의도였던 것인가.)",
  ui_story_5051_50511401_4_dialog_content = "(아무래도 진작부터 내 계획을 눈치채고 있었던 것이겠지.)",
  ui_story_5051_50511401_5_dialog_content = "(이 백야성에서 교활함으로 솔라드에 비할 자는 없을 것이다.)",
  ui_story_5051_50511401_6_dialog_content = "(하, 이 오랜 세월 동안 나도 충분히 교활해진 줄 알았는데 말이야...)",
  ui_story_5051_50511401_7_dialog_content = "......",
  ui_story_5051_50511401_8_dialog_content = "어째서... 마임, 어째서 네가 <color=#FFB400>용의 혈맥</color>을 각성한 거니?",
  ui_story_5051_50511401_9_dialog_content = "이건 카르티마 가문에서는 용서받을 수 없는 일이야!",
  ui_story_5051_50511401_10_dialog_content = "일부러 이런 게 아냐! 엄마... 도와줘!",
  ui_story_5051_50511401_11_dialog_content = "얘야, 이 일은 절대 아무에게도 말해선 안 돼.",
  ui_story_5051_50511401_12_dialog_content = "하, 하지만 나 머리가 깨질 것처럼 아파...",
  ui_story_5051_50511401_13_dialog_content = "참아야 해, 마임! 너라면 그 힘을 억제할 수 있다고 말해!",
  ui_story_5051_50511401_14_dialog_content = "카르티마 가문의 가주가 될 사람은 반드시 너여야만 해!",
  ui_story_5051_50511401_15_dialog_content = "아파... 아파... 나 못 하겠어!",
  ui_story_5051_50511401_16_dialog_content = "넌 반드시 해야만 해!",
  ui_story_5051_50511401_17_dialog_content = "어디 다시 한번 말해봐라.",
  ui_story_5051_50511401_18_dialog_content = "설령 날 이 쓰러질 듯한 탑에 가둬둔다 해도... 콜록콜록...",
  ui_story_5051_50511401_19_dialog_content = "내가 해줄 말은 똑같다!",
  ui_story_5051_50511401_20_dialog_content = "마임, 넌 카르티마 가문을 구할 수 없다.",
  ui_story_5051_50511401_21_dialog_content = "카르티마 가문의 가주는 네가 아니야!",
  ui_story_5051_50511401_22_dialog_content = "그래, 확실히 난 용의 혈맥을 각성했다. 허나 그게 뭐가 문제란 말이냐.",
  ui_story_5051_50511401_23_dialog_content = "나는 이미 카르티마 가문의 가주다. 그것은 이미 틀림없는 사실이다.",
  ui_story_5051_50511401_X23_dialog_content = "용의 혈맥을 각성했다고?!",
  ui_story_5051_50511401_X24_dialog_content = "「용의 혈맥」을 죄악으로 간주하는 가문 사람들을 끝까지 속이다니...\n인내심 하나는 무서울 지경이군.",
  ui_story_5051_50511401_X25_dialog_content = "허나 내가 해줄 말은 같다. 카르티마 가문을 구할 수 있는 건 네가 아니다.",
  ui_story_5051_50511401_X26_dialog_content = "그건 네가 용의 혈맥을 각성했는지와는 상관없는 일이다.",
  ui_story_5051_50511401_X27_dialog_content = "안타깝지만 당신 예언을 믿는 사람은 없다.",
  ui_story_5051_50511401_24_dialog_content = "하하하하하하... 콜록...",
  ui_story_5051_50511401_25_dialog_content = "두려워해라! 카르티마를 구할 소녀가 곧 네 곁에 나타날 것이다!",
  ui_story_5051_50511401_26_dialog_content = "이미 완전히 미쳤군.",
  ui_story_5051_50511401_27_dialog_content = "...가문 사람들은 모두 이 아이를 싫어해서, 아무도 거두어 주려는 사람이 없습니다.",
  ui_story_5051_50511401_28_dialog_content = "가주님, 안녕하세요.",
  ui_story_5051_50511401_29_dialog_content = "전... 시로나입니다.",
  ui_story_5051_50511401_30_dialog_content = "!!!",
  ui_story_5051_50511401_31_dialog_content = "설마 장로가 말했던 게 너냐?",
  ui_story_5051_50511401_32_dialog_content = "절대 폐를 끼치지 않겠습니다.",
  ui_story_5051_50511401_33_dialog_content = "이 아이는 내가 맡도록 하지.",
  ui_story_5051_50511401_34_dialog_content = "가, 감사합니다. 가주님!",
  ui_story_5051_50511401_35_dialog_content = "기억해라. 여기 있는 한 네가 두각을 나타낼 날은 영원히 오지 않는다.",
  ui_story_5051_50511401_36_dialog_content = "아...",
  ui_story_5051_50511401_37_dialog_content = "가주님, 가주님...!",
  ui_story_5051_50511401_38_dialog_content = "무슨 일이냐.",
  ui_story_5051_50511401_39_dialog_content = "카르티마 가문의 병사와 모든 일원이 집결을 마쳤습니다.",
  ui_story_5051_50511401_40_dialog_content = "결국 모두를 끌어들이고 말았군...",
  ui_story_5051_50511401_41_dialog_content = "가주님, 그렇지 않습니다!",
  ui_story_5051_50511401_42_dialog_content = "솔라드는 줄곧 우리 카르티마 가문이 가진 권력을 약화시켜 왔습니다.",
  ui_story_5051_50511401_43_dialog_content = "가주님이 계시지 않았다면 카르티마 가문은 진작에 솔라드에게 버려졌을 것입니다.",
  ui_story_5051_50511401_44_dialog_content = "그만, 그 이야기는 됐다.",
  ui_story_5051_50511401_45_dialog_content = "안 됩니다! 저흰 꼭 말씀드려야겠습니다!",
  ui_story_5051_50511401_46_dialog_content = "지금까지 가주님께서 가문을 위해 헌신하신 것은 모두가 잘 알고 있습니다.",
  ui_story_5051_50511401_47_dialog_content = "저희는 모두 스스로 원해서 가주님을 따라온 겁니다.\n어떤 원망도 하지 않습니다!",
  ui_story_5051_50511401_48_dialog_content = "하지만 솔라드는 모든 유력 귀족들이 움브라톤 파병을 반대하는 걸 알면서도...",
  ui_story_5051_50511401_49_dialog_content = "오늘 의식에서 자신과 함께 움브라톤을 지원하겠다고 가주님이 선언하게 만들려고 했습니다.",
  ui_story_5051_50511401_50_dialog_content = "그렇게 우리 카르티마 가문을 다른 가문들의 비난의 대상으로 세우고,\n공적은 모두 자신의 것으로 돌리려는 생각이지 않습니까!",
  ui_story_5051_50511401_51_dialog_content = "놈의 이익을 위해 암귀의 먹이가 될 바에야...",
  ui_story_5051_50511401_52_dialog_content = "카르티마 가문을 위해 목숨을 바치겠습니다!",
  ui_story_5051_50511401_53_dialog_content = "<size=45>카르티마를 위하여! 카르티마를 위하여!\n카르티마를 위하여!</size>",
  ui_story_5051_50511401_54_dialog_content = "하하하, 좋다! 그러나 한 가지는 동의할 수 없다.",
  ui_story_5051_50511401_55_dialog_content = "이 싸움은... 아직 승부가 나지 않았다!",
  ui_story_5051_50511401_56_dialog_content = "가주님... 옳으신 말씀입니다!",
  ui_story_5051_50511401_57_dialog_content = "저희는 가주님을 따라 카르티마 가문이 잃은 영광을 모두 되찾을 것입니다!",
  ui_story_5051_50511401_58_dialog_content = "모든 준비는 끝났습니다. 이제 가주님의 명령만 기다리고 있습니다.",
  ui_story_5051_50511401_59_dialog_content = "모두 목숨을 걸고 카르티마 가문의 영광을 지키겠습니다!",
  ui_story_5051_50511401_60_dialog_content = "<size=45>카르티마 가문의 영광을 위하여!</size>",
  ui_story_5051_50511401_61_dialog_content = "좋다!",
  ui_story_5051_50511401_62_dialog_content = "그렇다면 이제 우리의 마지막 조력자를 내가 초대하도록 하지.",
  ui_story_5051_50511401_63_dialog_content = "조력자요...?",
  ui_story_5051_50511401_64_dialog_content = "「비상하는 하늘의 용이여, 카르티마의 영원한 반려자여.」",
  ui_story_5051_50511401_65_dialog_content = "「그 두 날개를 펼쳐, 끝없이 이어지는 어둠의 밤을 가르고...」",
  ui_story_5051_50511401_66_dialog_content = "「내 곁으로 오라.」",
  ui_story_5051_50511401_67_dialog_content = "「우리의 곁으로 오라.」",
  ui_story_5051_50511401_68_dialog_content = "「카르티마 가문은 결코 우리의 서약을 잊지 않으리라.」",
  ui_story_5051_50511401_69_dialog_content = "<anim type=Shake><size=45>캬아아아악!</size></anim>",
  ui_story_5051_50511401_70_dialog_content = "이 소리는...",
  ui_story_5051_50511401_71_dialog_content = "가주님... 설마 <color=#FFB400>드래곤</color>을 소환하신 겁니까?!",
  ui_story_5051_50511401_72_dialog_content = "드래곤은 언제나 카르티마 가문의 가장 충직한 벗이었다.",
  ui_story_5051_50511401_73_dialog_content = "그러나 누군가는 카르티마의 힘을 두려워했고,\n우리의 선조들이 용의 혈맥을 불길한 상징이라고 믿게 만들었다.",
  ui_story_5051_50511401_74_dialog_content = "설마 그게 솔라드 가문입니까...?",
  ui_story_5051_50511401_75_dialog_content = "<size=45>오라, 가논이여! 친구와 가족들의 곁으로 오라!</size>",
  ui_story_5051_50511401_76_dialog_content = "<anim type=Shake><size=45>그오오오──!</size></anim>",
  ui_story_5051_50511401_77_dialog_content = "우리는 이제 더는 잘못된 시선을 두려워할 필요가 없다.",
  ui_story_5051_50511401_78_dialog_content = "<anim type=Shake><size=45>크아아아아──!</size></anim>",
  ui_story_5051_50511401_79_dialog_content = "카르티마의 일족들이여!",
  ui_story_5051_50511401_80_dialog_content = "이제 드래곤이 우리의 곁으로 돌아왔다!",
  ui_story_5051_50511401_81_dialog_content = "드래곤은 우리를 돕고, 우리는 백야성의 지배자가 될 것이다!",
  ui_story_5051_50511401_82_dialog_content = "드래곤 만세!",
  ui_story_5051_50511401_83_dialog_content = "<anim type=Shake><size=45>캬아아아악!</size></anim>",
  ui_story_5051_50511401_84_dialog_content = "<color=#e8d9bb>같은 시간, 움브라톤</color>",
  ui_story_5051_50511401_85_dialog_content = "방금 무슨 소리 못 들었어?",
  ui_story_5051_50511401_86_dialog_content = "난 내 귀에 이명이 생긴 줄 알았어!",
  ui_story_5051_50511401_87_dialog_content = "설마 암귀가 벌써 쳐들어온 건 아니겠지?!",
  ui_story_5051_50511401_88_dialog_content = "바보 같은 소리 하지 말고... 얼른 돌아가자!",
  ui_story_5051_50511401_89_dialog_content = "그러자고. 죽을 거면 이왕이면 집에서 죽어야지.",
  ui_story_5051_50511401_90_dialog_content = "(움브라톤... 내가 기억하던 것보다 더 침침하네.)",
  ui_story_5051_50511401_91_dialog_content = "(여기서 바라보는 백야성은...)",
  ui_story_5051_50511401_92_dialog_content = "(역시 무척 달라.)",
  ui_story_5051_50511401_93_dialog_content = "(백야성의 밤은 여기보다 더 추웠던 것 같은데.)",
  ui_story_5051_50511401_94_dialog_content = "방금 그 울음소리는... 암귀일까요?",
  ui_story_5051_50511401_95_dialog_content = "아니, 암귀가 아니다.",
  ui_story_5051_50511401_96_dialog_content = "암귀가 아니면 뭐죠?",
  ui_story_5051_50511401_97_dialog_content = "봐라, 놈이 왔다.",
  ui_story_5051_50511401_98_dialog_content = "<anim type=Shake><size=45>그오오오!</size></anim>",
  ui_story_5051_50511401_99_dialog_content = "...드래곤인가?",
  ui_story_5051_50511401_100_dialog_content = "훗, 역시 악룡의 원한에 두 눈이 멀고 만 것이냐.",
  ui_story_5051_50511401_101_dialog_content = "아무래도 저 가문의 혈통은 몸을 팔아버린 그 오랜 시간의 계약에서\n영원히 벗어날 수 없는 모양이군.",
  ui_story_5051_50511401_102_dialog_content = "드래곤이 다가와요!",
  ui_story_5051_50511401_103_dialog_content = "베로니카, 일단 물러서라!",
  ui_story_5051_50511401_104_dialog_content = "어디 먼저 보도록 할까. 드래곤이 과연 어떤 힘이 있는지 말이야.",
  ui_story_5051_50511401_105_dialog_content = "저 드래곤은 몸집이 거대하고, 작열하는 불길을 뿜어내지.",
  ui_story_5051_50511401_106_dialog_content = "큰 부상을 입고 싶지 않다면, 되도록 첫 공격으로 놈의 약점을 찌르는 게 좋네.",
  ui_story_5051_50511401_107_dialog_content = "놈의 약점은...",
  ui_story_5051_50511401_108_dialog_content = "물론 알고 있다.",
  ui_story_5051_50511401_109_dialog_content = "어라, 안 듣고 그냥 가시는데요?",
  ui_story_5051_50511401_110_dialog_content = "아무래도 이 싸움은 시간이 조금 걸릴 것 같군.",
  ui_story_5051_50511401_111_dialog_content = "저 때 당시엔 드래곤의 약점을 모르셨나요?",
  ui_story_5051_50511401_112_dialog_content = "아니면... 첫 공격으로 약점을 못 찌르신 건가요?",
  ui_story_5051_50511401_113_dialog_content = "......",
  ui_story_5051_50511401_114_dialog_content = "<color=#e8d9bb>휘이잉── 휘잉──</color>",
  ui_story_5051_50511401_115_dialog_content = "바람이 부는군. 이 점은 확실히 그때와는 다르다.",
  ui_story_5051_50511401_116_dialog_content = "(방금 질문은 일부러 무시하신 건가...)",
  ui_story_5051_50511401_117_dialog_content = "바람...? 만약 풍향을 이용할 수 있다면, 어쩌면...",
  ui_story_5051_50511401_118_dialog_content = "그렇게 되면 이 싸움은 금방 끝이 나겠지.",
  ui_story_5051_50511401_119_dialog_content = "그어어어!",
  ui_story_5051_50511401_120_dialog_content = "「백야의 빛이여!」",
  ui_story_5051_50511401_121_dialog_content = "<anim type=Shake>크어어어!</anim>",
  ui_story_5051_50511401_122_dialog_content = "(젊은 성주님이 공격을 드래곤의 목구멍에 명중시켰어...\n그래서 당장은 불꽃을 토할 수 없게 된 건가?)",
  ui_story_5051_50511401_123_dialog_content = "(설마 목이 드래곤의 약점?)",
  ui_story_5051_50511401_124_dialog_content = "(...잘 보이지는 않지만, 드래곤의 등에... 누군가 있는 것 같아.)",
  ui_story_5051_50511401_125_dialog_content = "마임 카르티마!",
  ui_story_5051_50511401_126_dialog_content = "(어? 성에 들어올 때 만났던 그 기사장...?)",
  ui_story_5051_50511401_127_dialog_content = "하하, 드래곤의 공격이란 고작 이 정도인 것인가?",
  ui_story_5051_50511401_128_dialog_content = "전력을 다할 필요도 없겠군.",
  ui_story_5051_50511401_129_dialog_content = "한 번 공격을 막아낸 건 네 요행이다.",
  ui_story_5051_50511401_130_dialog_content = "고귀하신 성주 전하, 운도 실력이라고 절대로 생각하지 않는 게 좋을 것이다.",
  ui_story_5051_50511401_131_dialog_content = "넌 그저 우연히 가논의 불길을 피했을 뿐...\n성주의 자리에도 운 좋게 앉은 것처럼 말이다.",
  ui_story_5051_50511401_132_dialog_content = "가논? 드래곤에게 이름도 지어준 건가?",
  ui_story_5051_50511401_133_dialog_content = "어리석은 짓을 했구나, 마임.",
  ui_story_5051_50511401_134_dialog_content = "놈이 목숨을 잃을 때 분명히 마음이 아프겠군.",
  ui_story_5051_50511401_135_dialog_content = "쓸데없는 말이 너무 많다!",
  ui_story_5051_50511401_136_dialog_content = "가논이여, 가라!",
  ui_story_5051_50511401_137_dialog_content = "눈앞의 사내에게 가장 맹렬한 불길을 맛보여 줘라!",
  ui_story_5051_50511401_138_dialog_content = "그대의 「선물」이라면 이미 내 어깨에 받았다만, 그 이상은 사양하도록 하지.",
  ui_story_5051_50511401_139_dialog_content = "이번엔 내가 「답례」를 보낼 차례다!",
  ui_story_5051_50511401_140_dialog_content = "「어두운 밤을 밝혀라, 영원한 태양이여!」",
  ui_story_5051_50511401_141_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5051_50511401_142_dialog_content = "돌격하라!",
  ui_story_5051_50511401_143_dialog_content = "반란군도 공격을 시작했어요...!",
  ui_story_5051_50511401_144_dialog_content = "모두 들어라!",
  ui_story_5051_50511401_145_dialog_content = "전투 준비!",
  ui_story_5051_50511401_146_dialog_content = "......",
  ui_story_5051_50511401_147_dialog_content = "미아, 너도 갈 거야?",
  ui_story_5051_50511401_148_dialog_content = "할 수만 있다면... 내 무기를 동포의 피로 물들이고 싶진 않아...",
  ui_story_5051_50511401_149_dialog_content = "아버님, 왜 당시에 우리는 이렇게 해야만 했던 거죠?",
  ui_story_5051_50511401_150_dialog_content = "놈들이 저들의 무기를 우리의 피로 물들이려 했기 때문이다.",
  ui_story_5051_50511402_1_dialog_content = "<anim type=Shake>그어어어어...</anim>",
  ui_story_5051_50511402_2_dialog_content = "가논! 안 돼──!",
  ui_story_5051_50511402_3_dialog_content = "이건 말도 안 돼...",
  ui_story_5051_50511402_4_dialog_content = "이럴 리가 없단 말이다!",
  ui_story_5051_50511402_5_dialog_content = "(역시나, 젊은 성주님은 풍향을 이용해서 드래곤을 쓰러트렸어...)",
  ui_story_5051_50511402_6_dialog_content = "(이 싸움, 상상했던 것보다 훨씬 빨리 끝났잖아.)",
  ui_story_5051_50511402_7_dialog_content = "마임 카르티마!",
  ui_story_5051_50511402_8_dialog_content = "그대는 백야성의 기사장으로서 백야성을 수호하는 견고한 힘이 되었어야 마땅하다.",
  ui_story_5051_50511402_9_dialog_content = "허나 그대는 백야성을 배반하고, 기사로서의 신앙을 배반했다.",
  ui_story_5051_50511402_10_dialog_content = "또한 백성들에게 돌이킬 수 없는 경제적 손실과 정신적 고통을 안겨주었다.",
  ui_story_5051_50511402_11_dialog_content = "만물은 백야 아래에!",
  ui_story_5051_50511402_12_dialog_content = "그대의 행위는 이미 모반죄에 해당한다.",
  ui_story_5051_50511402_13_dialog_content = "이 순간부터 그대의 작위와 직위를 영원히 박탈하는 바다.",
  ui_story_5051_50511402_14_dialog_content = "감옥에서 심판소의 최종 심판을 기다리도록 해라.",
  ui_story_5051_50511402_15_dialog_content = "하하, 뭘 기다리라는 거냐...",
  ui_story_5051_50511402_16_dialog_content = "솔라드여, 차라리 여기서 바로 날 죽여라!",
  ui_story_5051_50511402_17_dialog_content = "일족들을 만나고 싶지 않은 건가?",
  ui_story_5051_50511402_18_dialog_content = "...네 이놈!",
  ui_story_5051_50511402_19_dialog_content = "이 일은 전부 내 과오다. 가문 사람들과는 무관하다!",
  ui_story_5051_50511402_20_dialog_content = "내가 저들을 위협하여 병사를 동원한 것이다...",
  ui_story_5051_50511402_21_dialog_content = "네게 아직 일말의 정의라도 남아 있다면, 아이와 노인들에겐 손대지 마라!",
  ui_story_5051_50511402_22_dialog_content = "일이 이렇게 된 이상, 나 한 사람의 의견으로 정할 수 있는 게 아니다.",
  ui_story_5051_50511402_23_dialog_content = "네 그 간청은 남겨 두었다가 심판소에서 말하도록 해라.",
  ui_story_5051_50511402_24_dialog_content = "심판소가 네게 공정한 판결을 내릴 것이다.",
  ui_story_5051_50511402_25_dialog_content = "하하...",
  ui_story_5051_50511402_26_dialog_content = "<anim type=Shake><size=45>하하하하하하!</size></anim>",
  ui_story_5051_50511402_27_dialog_content = "카르티마를 구할 수 있는 건 역시 내가 아니었던 것인가...",
  ui_story_5051_50511402_28_dialog_content = "장로의 말이 사실이라면, 녀석은 반드시 내가 못다 한 사명을 이룰 것이다!",
  ui_story_5051_50511402_29_dialog_content = "카르티마 가문은 그대 손으로 멸망시킨 것이다.",
  ui_story_5051_50511402_30_dialog_content = "만약 그대가 약속한 대로 오늘 백성들 앞에서\n나와 함께 움브라톤을 도우러 가겠다고 선언했더라면...",
  ui_story_5051_50511402_31_dialog_content = "결말은 달랐을지도 모르지.",
  ui_story_5051_50511402_32_dialog_content = "네 이놈...",
  ui_story_5051_50511402_33_dialog_content = "웃기지 마라!",
  ui_story_5051_50511402_34_dialog_content = "위험해요!",
  ui_story_5051_50511402_35_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5051_50511402_36_dialog_content = "크윽...",
  ui_story_5051_50511402_37_dialog_content = "(더는 전세를 뒤집을 수 없는 걸 알면서도, 마지막 힘을 다해 반격한 건가...)",
  ui_story_5051_50511402_38_dialog_content = "그대의 용기에는 탄복했다, 마임 카르티마.",
  ui_story_5051_50511402_39_dialog_content = "미즈 로트, 나머지 일은 맡기도록 하지.",
  ui_story_5051_50511402_40_dialog_content = "나는 카렌의 상태를 보러 갈 테니, 의사당에서 기다리도록.",
  ui_story_5051_50511402_41_dialog_content = "네.",
  ui_story_5051_50511501_1_dialog_content = "조슈아, 돌아왔어.",
  ui_story_5051_50511501_2_dialog_content = "다니엘...",
  ui_story_5051_50511501_3_dialog_content = "얼른 이리 와요. 상처가 벌어지진 않았나요? 또 다친 곳은 없나요?",
  ui_story_5051_50511501_4_dialog_content = "안심해, 조슈아. 걱정시키지 않겠다고 했잖아.",
  ui_story_5051_50511501_5_dialog_content = "그것보다 카렌의 상태는 어떻지?",
  ui_story_5051_50511501_6_dialog_content = "의사가 보고 갔어요. 큰 문제는 없고, 며칠 쉬면 괜찮아질 거예요.",
  ui_story_5051_50511501_7_dialog_content = "다행이네.",
  ui_story_5051_50511501_8_dialog_content = "저녁 준비 다 했어요. 조금이라도 먹어둬요.",
  ui_story_5051_50511501_9_dialog_content = "아니, 난 가서 처리할 일이 또 있어.",
  ui_story_5051_50511501_10_dialog_content = "그대는 일찍 쉬도록 해.",
  ui_story_5051_50511501_11_dialog_content = "다니엘, 당신은 오늘 하루 종일 바빴잖아요. 쉬어야 할 건 당신이에요.",
  ui_story_5051_50511501_12_dialog_content = "카르티마 가문 문제는 원로원, 그리고 심판소 쪽과 서둘러 협의해야만 해.",
  ui_story_5051_50511501_13_dialog_content = "미안해, 조슈아.",
  ui_story_5051_50511501_14_dialog_content = "이번 일이 정리되고 나면, 가족 넷이 제대로 모여서 식사를 하자.",
  ui_story_5051_50511501_15_dialog_content = "다니엘... 카르티마 가문은 어떻게 처분할 건지 말해줄 수 있나요?",
  ui_story_5051_50511501_16_dialog_content = "그 문제도 그대가 염려할 일이 아니야.\n카르티마 가문은 반드시 응분의 대가를 치르게 될 테니까.",
  ui_story_5051_50511501_17_dialog_content = "아무것도 몰랐던 사람들은요?",
  ui_story_5051_50511501_18_dialog_content = "그 사람들까지 말려들게 되는 건가요?",
  ui_story_5051_50511501_19_dialog_content = "조슈아, 잊으면 안 돼.",
  ui_story_5051_50511501_20_dialog_content = "오늘 카르티마 일족은 그 싸늘한 칼날을 우리에게,\n그리고 우리가 사랑하는 딸들에게 겨누었어.",
  ui_story_5051_50511501_21_dialog_content = "저들은 우리를 배반하면서, 우리의 딸들도 무고하다는 생각 따윈 하지 않았어!",
  ui_story_5051_50511501_22_dialog_content = "하지만...",
  ui_story_5051_50511501_23_dialog_content = "다니엘, 한 가지 묻고 싶은 게 있어요.",
  ui_story_5051_50511501_24_dialog_content = "당신, 카르티마 가문이 모반을 꾀한다는 소식을 진작부터 알고 있었죠...?",
  ui_story_5051_50511501_25_dialog_content = "누가 그런 말을 해준 거지?",
  ui_story_5051_50511501_26_dialog_content = "당신이에요, 다니엘. 당신 요즘 행동이 이상했으니까요.",
  ui_story_5051_50511501_27_dialog_content = "이상한 생각은 그만하면 안 될까?",
  ui_story_5051_50511501_28_dialog_content = "그럼 오늘 암귀의 습격이 두 번 있으리라는 건 어떻게 알았죠?",
  ui_story_5051_50511501_29_dialog_content = "그리고 또 생각해 봤어요...",
  ui_story_5051_50511501_30_dialog_content = "나랑 검술 연습할 때 당신은 오십 미터 밖의 작은 움직임도 느낄 수 있었죠.",
  ui_story_5051_50511501_31_dialog_content = "하지만 왜 오늘은 빤히 보이는 암살자의 공격에도 미처 반응하지 못했나요?",
  ui_story_5051_50511501_32_dialog_content = "당신... <color=#FFB400>일부러</color> 그런 건가요?",
  ui_story_5051_50511501_33_dialog_content = "하지만 아무리 생각해도 당신이 왜 그랬는지 모르겠어요.",
  ui_story_5051_50511501_34_dialog_content = "당신이 다치면 사람들의 동정을 얻을 수 있고,\n카르티마 가문의 죄를 명확히 할 수 있기 때문인가요?",
  ui_story_5051_50511501_35_dialog_content = "그대가 생각하는 그런 게 아니야.",
  ui_story_5051_50511501_36_dialog_content = "내가 저들의 계획을 알았다면, 어떻게 그대와 아이들을 데려갔겠어?",
  ui_story_5051_50511501_37_dialog_content = "!!!",
  ui_story_5051_50511501_38_dialog_content = "나랑 카렌이 곁에 있으면...\n반란군은 의심하지 않고 저들의 계획대로 일을 진행하겠죠.",
  ui_story_5051_50511501_39_dialog_content = "당신, 우릴 <color=#FFB400>체스말</color>로 쓴 건가요?",
  ui_story_5051_50511501_40_dialog_content = "......",
  ui_story_5051_50511501_41_dialog_content = "나는 백야성의 성주고, 이 부유섬의 미래는 내 어깨에 달려 있어.",
  ui_story_5051_50511501_42_dialog_content = "목적을 달성하기 위해서라면, 나 자신을 체스말로 쓸 수도 있다고.",
  ui_story_5051_50511501_43_dialog_content = "그게 우리가 짊어진 책임이야, 조슈아.",
  ui_story_5051_50511501_44_dialog_content = "당신이 하는 모든 일이 암귀에 맞설 힘을 얻기 위해서라는 건 알고 있어요.",
  ui_story_5051_50511501_45_dialog_content = "하지만 왜 내겐 똑바로 말해주질 않는 거죠?",
  ui_story_5051_50511501_46_dialog_content = "둘이 함께라면 더 좋은 방법을 찾을 수 있을지도 모르잖아요.",
  ui_story_5051_50511501_47_dialog_content = "...날 체스말로 삼아도 좋아요. 어떤 불평도 하지 않을 거예요.",
  ui_story_5051_50511501_48_dialog_content = "하지만 정말 당신은 저 어린 우리 아이들까지 당신 체스판의 말로 쓸 수 있는 건가요?",
  ui_story_5051_50511501_49_dialog_content = "만에 하나 오늘 카렌이 정말로...",
  ui_story_5051_50511501_50_dialog_content = "그런 일이 벌어지게 만들진 않아.",
  ui_story_5051_50511501_51_dialog_content = "실제로는 카렌도 지금 무사하잖아.",
  ui_story_5051_50511501_52_dialog_content = "이번엔 운이 좋았을 뿐이지만, 잘못됐다면요?",
  ui_story_5051_50511501_53_dialog_content = "만약 다음에도 이런 일이 또 생긴다면...\n나한테도 미리 말해주겠다고 약속할 수 있겠어요?",
  ui_story_5051_50511501_54_dialog_content = "진짜 정치는 책에 적혀 있는 것들보다 훨씬 복잡해.",
  ui_story_5051_50511501_55_dialog_content = "조슈아, 난 그대를 사랑해...",
  ui_story_5051_50511501_56_dialog_content = "그렇기 때문에 그대까지 이 더러운 소용돌이 속으로 끌어들이고 싶지 않아.",
  ui_story_5051_50511501_57_dialog_content = "우리가 같이 공부하던 시절엔 그런 말 한 적 없었죠.",
  ui_story_5051_50511501_58_dialog_content = "당신은 우리가 함께 백야성을 바꿀 거라고 했어요.",
  ui_story_5051_50511501_59_dialog_content = "하지만 이제 당신은 날 믿고 싶지 않은 거군요.",
  ui_story_5051_50511501_60_dialog_content = "한순간도 그대를 믿지 않은 적 없어.\n우리의 가족을 안심하고 그대에게 맡기고 있잖아.",
  ui_story_5051_50511501_61_dialog_content = "마찬가지로 그대도 내 정치적 판단을 믿어줘야 해.",
  ui_story_5051_50511501_62_dialog_content = "다른 가문을 통째로 희생시켜 자신의 통치를 위한 길을 여는 것 말인가요.",
  ui_story_5051_50511501_63_dialog_content = "그게 당신이 심사숙고한 끝에 내린 결론이라면...",
  ui_story_5051_50511501_64_dialog_content = "당신... 내가 아는 다니엘이 맞는지 잘 모르겠어요.",
  ui_story_5051_50511501_65_dialog_content = "성주의 자리를 지키기 위해, 당신은 이미 수단을 가리지 않기 시작했어요.",
  ui_story_5051_50511501_66_dialog_content = "아니, 수단만 가리지 않는 게 아니죠.",
  ui_story_5051_50511501_67_dialog_content = "당신 마음은 저 북방의 산마루를 덮은 얼음과 눈보다도 차가워졌어요!",
  ui_story_5051_50511501_68_dialog_content = "베로니카는 당신 때문에 사람들한테 괴물 취급을 받고...",
  ui_story_5051_50511501_69_dialog_content = "카렌도 조만간 당신 때문에 목숨을 잃겠죠...",
  ui_story_5051_50511501_70_dialog_content = "그리고 나도... 당신 곁을 떠나 이 세상에서 완전히 사라져 버리겠죠...",
  ui_story_5051_50511501_71_dialog_content = "조슈아... 조슈아!",
  ui_story_5051_50511501_72_dialog_content = "조슈아!",
  ui_story_5051_50511501_73_dialog_content = "어째서...",
  ui_story_5051_50511501_74_dialog_content = "<size=45>왜 날 떠나는 거야?!</size>",
  ui_story_5051_50511501_75_dialog_content = "<anim type=Shake>헉... 허억... 허억...</anim>",
  ui_story_5051_50511501_76_dialog_content = "어디 불편하신가요?",
  ui_story_5051_50511501_77_dialog_content = "조슈아!",
  ui_story_5051_50511501_78_dialog_content = "어머, 스카이워커 씨, 왜 이러시는 건가요...?",
  ui_story_5051_50511501_79_dialog_content = "「아버지」! 그러다 공작부인님 손이 다치겠어요...",
  ui_story_5051_50511501_80_dialog_content = "아... 추태를 보였소.",
  ui_story_5051_50511501_X80_dialog_content = "왜인지 자주 꾸던 악몽을 떠올리고 말았소.",
  ui_story_5051_50511501_81_dialog_content = "나이가 들어서인지, 휴식이 좀 필요한 모양이오.",
  ui_story_5051_50511501_82_dialog_content = "그럼 푹 쉬세요. 이따가 같이 식사해요.",
  ui_story_5051_50511501_83_dialog_content = "조슈아, 손님들 대접하느라 고생 많았어.",
  ui_story_5051_50511501_84_dialog_content = "저녁 식사가 곧 준비될 거예요. 다 같이 식당으로 가요.",
  ui_story_5051_50511501_85_dialog_content = "아니, 가서 처리할 일이 더 있어.",
  ui_story_5051_50511501_86_dialog_content = "손님들과 식사를 마치고 일찍 쉬도록 해.",
  ui_story_5051_50511501_87_dialog_content = "다니엘, 당신은 오늘 하루 종일 바빴잖아요. 쉬어야 할 건 당신이에요.",
  ui_story_5051_50511501_88_dialog_content = "......",
  ui_story_5051_50511501_89_dialog_content = "<size=30>PlayerName, 어떻게 해서든 모두의 주의를 끌어라!</size>",
  ui_story_5051_50511501_90_dialog_content = "<size=30>어? 왜요?</size>",
  ui_story_5051_50511501_91_dialog_content = "<size=30>지금 막지 못하면, 내가 다시는 보고 싶지 않은 말다툼이 시작되고 만단 말이다...</size>",
  ui_story_5051_50511501_92_dialog_content = "카르티마 가문 문제는 원로원, 그리고 심판소 쪽과 서둘러 협의해야만 해.",
  ui_story_5051_50511501_93_dialog_content = "미안해, 조슈아.",
  ui_story_5051_50511501_94_dialog_content = "이번 일이 정리되고 나면, 가족 넷이 제대로 모여서 식사를 하자.",
  ui_story_5051_50511501_95_dialog_content = "좋아요! 대찬성이에요!",
  ui_story_5051_50511501_96_dialog_content = "응?",
  ui_story_5051_50511501_97_dialog_content = "일이 안 끝난 사람은 가서 일하고, 쉬어야 할 사람은 남아서 쉬어야죠.",
  ui_story_5051_50511501_98_dialog_content = "그렇게 하면... 모두에게 좋을 거라 생각해요.",
  ui_story_5051_50511501_99_dialog_content = "그렇지. 오늘 하루 동안 나도, 아이들도 식사 한 번 제대로 하지 못했네.",
  ui_story_5051_50511501_100_dialog_content = "그렇다면 오늘은 푹 쉬고 다음에 다시 이야기하기로 하지, 스카이워커 선생,",
  ui_story_5051_50511501_101_dialog_content = "그럼.",
  ui_story_5051_50511501_102_dialog_content = "......",
  ui_story_5051_50511501_103_dialog_content = "정말 그렇게 멋대로 가버리겠다는 건가요.",
  ui_story_5051_50511501_104_dialog_content = "스카이워커 씨, 미안해요. 다들 조금만 더 기다려 주세요.",
  ui_story_5051_50511501_105_dialog_content = "저녁 준비는 금방 끝날 거예요.",
  ui_story_5051_50511501_106_dialog_content = "...고맙네.",
  ui_story_5051_50511501_107_dialog_content = "저렇게 상냥한 조슈아 부인님이랑 말싸움을 하셨다고요?\n도저히 상상이 안 되는데요.",
  ui_story_5051_50511501_108_dialog_content = "아버님과 어머님... 과거의 이날에 말다툼을 하신 건가요?",
  ui_story_5051_50511501_109_dialog_content = "......",
  ui_story_5051_50511501_110_dialog_content = "자신이 한 짓도 차마 인정하지 못하시는 겁니까?",
  ui_story_5051_50511501_111_dialog_content = "칼렙 씨?! 어디서 튀어나온 거예요?",
  ui_story_5051_50511501_112_dialog_content = "외...외삼촌?",
  ui_story_5051_50511501_113_dialog_content = "칼렙, 쟈키니를 두고 혼자 가버렸다고 들었다.\n그대는 언제쯤 조금이나마 진중해질 셈이지?",
  ui_story_5051_50511501_114_dialog_content = "말 돌리지 마세요, 성주님.",
  ui_story_5051_50511501_115_dialog_content = "자신이 한 짓을 끝내 인정하지 않으시겠다면...",
  ui_story_5051_50511501_116_dialog_content = "제가 생각나게 해드리죠.",
  ui_story_5051_50511501_117_dialog_content = "그때 말다툼 때문에 누나는 어린 카렌을 데리고 궁전을 떠났습니다.",
  ui_story_5051_50511501_118_dialog_content = "그 이후로 당신들은 다시는 말을 나누지도 못했고,\n따뜻한 가족 식사 자리도 갖지 못했습니다.",
  ui_story_5051_50511501_119_dialog_content = "누나가 전장에서 죽어가던 베로니카를 데려오기 전까지 말입니다.",
  ui_story_5051_50511501_120_dialog_content = "당신은 암귀와의 전쟁에 몰두하고 있는 척했지만,\n사실은 그저 누나를 대하는 게 두려웠을 뿐이었겠죠...",
  ui_story_5051_50511501_121_dialog_content = "그 뒤엔 부상당한 베로니카를 또 자신의 정치적 목적을 위해\n일루미나의 실험실로 보냈습니다.",
  ui_story_5051_50511501_122_dialog_content = "하지만 그 실험실이 미치광이의 손에 통제되는 아수라장이었다는 것은 전혀 몰랐죠.",
  ui_story_5051_50511501_123_dialog_content = "누나는 또다시 베로니카를 위험에서 구해냈지만,\n그 때문에 중병에 걸려 일어나지 못하게 되었습니다...",
  ui_story_5051_50511501_124_dialog_content = "제 말이 틀렸습니까? 「매형」.",
  ui_story_5051_50511501_125_dialog_content = "<color=#FFB400>일루미나의 실험실</color>... 머, 머리가 아파.",
  ui_story_5051_50511501_126_dialog_content = "미아, 앉아서 쉬어. 무리해서 떠올리지 마.",
  ui_story_5051_50511501_127_dialog_content = "......",
  ui_story_5051_50511501_128_dialog_content = "칼렙 씨, 오늘 대체 어딜 갔던 거예요?",
  ui_story_5051_50511501_129_dialog_content = "하루 종일 사라져서는, 전 칼렙 씨가 여기서 나가기 싫은 줄 알았다니까요!",
  ui_story_5051_50511501_130_dialog_content = "전 계속 여기 있었습니다.\n다만 「그 사람」이 지금 모습의 절 알아보지 못했을 뿐이죠.",
  ui_story_5051_50511501_131_dialog_content = "하지만 제가 다시 눈앞에 나타난다면, 「누나」를 곤란하게 만들 겁니다...",
  ui_story_5051_50511501_132_dialog_content = "그래요. 역시 더는 여기 있으면 안 되겠어요.",
  ui_story_5051_50511501_133_dialog_content = "쟈키니 씨, 빨리 절 데리고 나가주세요!",
  ui_story_5051_50511501_134_dialog_content = "만나자마자 그렇게 요구부터 하는 건가요?",
  ui_story_5051_50511501_135_dialog_content = "이걸로 전부 모였는데, 안 돌아갈 겁니까?",
  ui_story_5051_50511501_136_dialog_content = "당신이 그러지 않았습니까?\n「영원한 기억의 수정」 속은 위험하니까 빨리 나가야 한다고 말이죠.",
  ui_story_5051_50511501_137_dialog_content = "뭐, 그건 맞지만요.",
  ui_story_5051_50511501_138_dialog_content = "그럼 다들 준비되셨나요?",
  ui_story_5051_50511501_139_dialog_content = "「어머님」이 같이 저녁 먹으려고 기다리고 계시는데...",
  ui_story_5051_50511501_140_dialog_content = "아직 시간은 있으니 조금 더 머무르는 게 어떠한가.",
  ui_story_5051_50511501_141_dialog_content = "네? 처음엔 성주님이 여기서 빨리 나가자고 재촉하셨잖아요.",
  ui_story_5051_50511501_142_dialog_content = "그것은 우리가 위험한 상황에 처해 있었기 때문이다.",
  ui_story_5051_50511501_143_dialog_content = "가장 위험한 시간은 이미 지나갔다.",
  ui_story_5051_50511501_144_dialog_content = "게다가...",
  ui_story_5051_50511501_145_dialog_content = "(어쩌면 칼렙의 말이 맞을지도 모르지. 그때의 그 말다툼은 모든 불행의 시작이었다.)",
  ui_story_5051_50511501_146_dialog_content = "(그날 나는 백야성의 모든 귀족의 지지를 얻어냈으나,\n자신이 가장 사랑하는 이의 마음에 크나큰 상처를 입히고 말았다.)",
  ui_story_5051_50511501_147_dialog_content = "아버님?",
  ui_story_5051_50511501_148_dialog_content = "게다가 우리가 지금 떠나면...",
  ui_story_5051_50511501_149_dialog_content = "「조슈아」는 또 그때처럼 홀로 불안한 하룻밤을 보내야만 한다.",
  ui_story_5051_50511501_150_dialog_content = "솔라드, 이제 와서 누구 때문에 그런 마음에도 없는 말을 하는 겁니까?",
  ui_story_5051_50511501_151_dialog_content = "칼렙, 그대가 조슈아의 일로 나를 미워하는 것은 알고 있다.",
  ui_story_5051_50511501_152_dialog_content = "수많은 여한이 시간과 함께 흘러가 버렸고, 더는 바로잡을 없게 되었다.",
  ui_story_5051_50511501_153_dialog_content = "그대의 모든 미움을 받아들이도록 하지.",
  ui_story_5051_50511501_154_dialog_content = "허나 만약 다시 한번 내게 기회가 주어진다면, 나는 반드시 조슈아를...",
  ui_story_5051_50511501_155_dialog_content = "훗, 지금 그런 말을 한다고 무슨 의미가 있죠?",
  ui_story_5051_50511501_156_dialog_content = "애초에 이 세계는 가짜잖아요...",
  ui_story_5051_50511501_157_dialog_content = "당신이 여기서 참회한들 아무것도 변하지 않는단 말입니다!",
  ui_story_5051_50511501_158_dialog_content = "외, 외삼촌...",
  ui_story_5051_50511501_159_dialog_content = "저도 「어머님」과 제대로 작별 인사를 하고 싶어요...",
  ui_story_5051_50511501_160_dialog_content = "이 세계가 진짜가 아닌 건 알아요.\n하지만 모두의 마음까지도 꼭 가짜인 건 아니잖아요.",
  ui_story_5051_50511501_161_dialog_content = "그러니까... 모두에게 마지막으로 조금만 시간을 주세요.",
  ui_story_5051_50511501_162_dialog_content = "저, 저기... 사실 저도 어떤 사람과 인사를 하고 싶었어요.",
  ui_story_5051_50511501_163_dialog_content = "어쨌든 지금은 아직 시간도 있고, 당장 다른 위험도 없으니까...",
  ui_story_5051_50511501_164_dialog_content = "다들 확실하게 인사를 하고 돌아가기로 해요!",
  ui_story_5051_50511501_165_dialog_content = "어차피 다음에 다시 들어왔을 땐 다들 아마 또 우릴 모를 수도 있으니까요.",
  ui_story_5051_50511501_166_dialog_content = "당신들은 정말...!",
  ui_story_5051_50511501_167_dialog_content = "PlayerName, 나와 「조슈아」와의 작별 인사에 동행해 줄 수 있겠나.",
  ui_story_5051_50511501_168_dialog_content = "지금의 「조슈아」에게 있어 나는 그저 한 낯선 사내일 뿐이다.\n그대를 데려가지 않는다면 무례를 범하는 일이 된다.",
  ui_story_5051_50511501_169_dialog_content = "하지만 제 아버지인 신분으로 어떻게 하고 싶은 말씀을 하실 건데요?",
  ui_story_5051_50511501_170_dialog_content = "「조슈아」 부인님이 성주님을 알아볼 수 있다면 좋을 텐데 말이죠...",
  ui_story_5051_50511501_171_dialog_content = "아, 쟈키니! 넌 「영원한 기억의 수정」을 조종할 수 있잖아?",
  ui_story_5051_50511501_172_dialog_content = "그럼 「조슈아」 부인님이 성주님을 알아보게 만들 방법 없어?",
  ui_story_5051_50511501_173_dialog_content = "방법이야 있죠!",
  ui_story_5051_50511501_174_dialog_content = "근데... 써 본 적이 없는 방법이라서 혹시 또 무슨 문제라도 생길까 걱정이에요.",
  ui_story_5051_50511501_175_dialog_content = "괜찮다. 시도해 보도록 하지.",
  ui_story_5051_50511501_176_dialog_content = "성주님... 아직도 절 그렇게 믿어주시는 거예요?",
  ui_story_5051_50511501_177_dialog_content = "그럼 성주님의 여한을 풀 수 있게 저 목숨 걸고 할게요!",
  ui_story_5051_50511501_178_dialog_content = "근데... 에헤헤.",
  ui_story_5051_50511501_179_dialog_content = "일단 책 좀 보고 찾아볼게요!",
  ui_story_5051_50511501_180_dialog_content = "크흠, 성주님, 진짜 괜찮으시겠어요?",
  ui_story_5051_50511501_181_dialog_content = "PlayerName, 나는 이미 십여 년을 도망쳐 왔다...",
  ui_story_5051_50511501_182_dialog_content = "내게 있어 이 세계에 들어온 것은 단순히 우연한 사고가 아닐지도 모른다.",
  ui_story_5051_50511501_183_dialog_content = "어쩌면 빛의 신이 나를 인도해 준 것일지도 모르지.",
  ui_story_5051_50511501_184_dialog_content = "이제 자신의 나약함을 직시할 때가 된 것이다.",
  ui_story_5051_50511501_185_dialog_content = "성주님, 일단 미리 말해둘게요. 이 환술은 잠깐 동안밖에 유지할 수 없어요.",
  ui_story_5051_50511501_186_dialog_content = "꼭 들통나기 전에 돌아오셔야 돼요~",
  ui_story_5051_50511501_187_dialog_content = "준비는 되었다.",
  ui_story_5051_50511501_188_dialog_content = "그럼 시작할게요~!",
  ui_story_5051_50511501_189_dialog_content = "「무타티오~ 무타티오~ 무타티오!」",
  ui_story_5051_50511501_190_dialog_content = "다니엘 드 솔라드를 젊었을 때의 모습으로 되돌려 주세요!",
  ui_story_5051_50511501_191_dialog_content = "「아브라카다브라!」",
  ui_story_5051_50511501_192_dialog_content = "<color=#e8d9bb>퍼엉!</color>",
  ui_story_5051_50511501_193_dialog_content = "하아?!",
  ui_story_5051_50511501_194_dialog_content = "PlayerName, 왜 그러느냐, 어째서 그리 놀라는 것이냐.",
  ui_story_5051_50511501_195_dialog_content = "성주님의 젊은 시절 모습은 역시 늘... 인상 깊단 말이죠.",
  ui_story_5051_50511501_196_dialog_content = "으아앗...",
  ui_story_5051_50511501_197_dialog_content = "으엑, 쟈키니... 왜 성주님을 하급 재판관 씨랑 형제처럼 만든 거야...?",
  ui_story_5051_50511501_198_dialog_content = "하급 재판관이라고?!",
  ui_story_5051_50511501_199_dialog_content = "크흠... 아무래도 방금 너무 흥분해서 성주님 젊은 시절 모습을\n제대로 상상하질 못했나 봐요...",
  ui_story_5051_50511501_200_dialog_content = "쟈키니... 우린 아까까지 젊은 성주님도 다 만났잖아.",
  ui_story_5051_50511501_201_dialog_content = "아, 그렇네요!",
  ui_story_5051_50511501_202_dialog_content = "그럼 이제 됐어요. 다시 한번 해볼게요!",
  ui_story_5051_50511501_203_dialog_content = "「무타티오~ 무타티오~ 무타티오!」",
  ui_story_5051_50511501_204_dialog_content = "다니엘 드 솔라드를 젊었을 때의 모습으로 되돌려 주세요!",
  ui_story_5051_50511501_205_dialog_content = "「아브라카다브라!」",
  ui_story_5051_50511501_206_dialog_content = "<color=#e8d9bb>퍼엉!</color>",
  ui_story_5051_50511501_207_dialog_content = "경비병, 입구에 있니?",
  ui_story_5051_50511501_208_dialog_content = "저녁 식사 준비됐어. 가서 사람들을 좀 불러줄래?",
  ui_story_5051_50511501_209_dialog_content = "......",
  ui_story_5051_50511501_210_dialog_content = "경비병?",
  ui_story_5051_50511501_211_dialog_content = "...당신이었어요?",
  ui_story_5051_50511501_212_dialog_content = "..................",
  ui_story_5051_50511501_213_dialog_content = "<size=30>미안하다.</size>",
  ui_story_5051_50511501_214_dialog_content = "네? 방금 뭐라고 했죠?",
  ui_story_5051_50511501_215_dialog_content = "아무것도 아니야.",
  ui_story_5051_50511501_216_dialog_content = "다니엘, 설마 방금 「미안해」라고 한 건가요?",
  ui_story_5051_50511501_217_dialog_content = "조슈아...",
  ui_story_5051_50511501_218_dialog_content = "좋아요, 돌아왔으면 됐죠.",
  ui_story_5051_50511501_219_dialog_content = "힘들 땐 집에 오면 되는 거예요.",
  ui_story_5051_50511501_220_dialog_content = "괜찮아요. 나도, 아이들도 계속 당신 곁에 있을 테니까요.",
  ui_story_5051_50511501_221_dialog_content = "......",
  ui_story_5051_50511501_222_dialog_content = "먼저 좀 쉬고 있어요. 가서 식기 한 벌 더 준비하라고 할게요.",
  ui_story_5051_50511501_223_dialog_content = "......",
  ui_story_5051_50511501_224_dialog_content = "다니엘, 그렇게 잡고 있으면 내가 어떻게 가요.",
  ui_story_5051_50511501_225_dialog_content = "그대에게 하고 싶은 말이 많다.",
  ui_story_5051_50511501_226_dialog_content = "집에 오면 당신 푸념 들어줄 사람이 있다는 걸 이제서야 떠올린 건가요?",
  ui_story_5051_50511501_227_dialog_content = "무슨 말인데요? 꼭 지금 해야만 하는 건가요?",
  ui_story_5051_50511501_228_dialog_content = "그래.",
  ui_story_5051_50511501_229_dialog_content = "좋아요, 그럼 다들 당신 따라서 조금만 더 배고프라고 해요.",
  ui_story_5051_50511501_230_dialog_content = "우선 당신 이야기부터 들어줄게요~",
  ui_story_5051_50511501_231_dialog_content = "..................",
  ui_story_5051_50511501_232_dialog_content = "그대가... 보고 싶었다.",
  ui_story_5051_50511501_233_dialog_content = "아?",
  ui_story_5051_50511501_234_dialog_content = "<color=#e8d9bb>근처의 한구석</color>",
  ui_story_5051_50511501_235_dialog_content = "쟈키니 씨! 어서요!",
  ui_story_5051_50511501_236_dialog_content = "왜 저한테는 주문이 안 먹히는 겁니까?!",
  ui_story_5051_50511501_237_dialog_content = "아이참, 재촉하지 마시라니까요. 주문의 효력은 감정의 영향도 받는다구요.",
  ui_story_5051_50511501_238_dialog_content = "아니면 아까 그 석고상 머리가 되고 싶어요?!",
  ui_story_5051_50511501_239_dialog_content = "다, 당신 정말...!",
  ui_story_5051_50511501_240_dialog_content = "아버님은... 제대로 말씀하고 계실까?",
  ui_story_5051_50511501_241_dialog_content = "음, 잘 말하신 거 아닐까? 두 사람 분위기도 아주 좋아 보이는데?",
  ui_story_5051_50511501_242_dialog_content = "<size=45>으아아! 솔라드 이 위선자! 우리 누나한테 뭐 하려는 거야?!</size>",
  ui_story_5051_50511501_243_dialog_content = "PlayerName... 갑자기 내 눈은 왜 가리는 거야?",
  ui_story_5051_50511501_244_dialog_content = "어? 미아가 내 눈 가린 거 아니었어?",
  ui_story_5051_50511501_245_dialog_content = "크흠... 당신들 꼬맹이들은...",
  ui_story_5051_50511501_246_dialog_content = "<size=45>더는 훔쳐보면 안 됩니다!</size>",
  ui_story_5051_50511601_1_dialog_content = "휴우우... 후우... Zzz...",
  ui_story_5051_50511601_2_dialog_content = "정말... 해장을 하더니, 이번엔 꿀잠이에요?",
  ui_story_5051_50511601_3_dialog_content = "뭐, 오히려 좋아요! 그럼 저도 마음껏...",
  ui_story_5051_50511601_4_dialog_content = "엄마라고 부를 수 있으니까요...",
  ui_story_5051_50511601_5_dialog_content = "헤헷, 뭐야... 막상 불러보니까 좀 부끄럽네요.",
  ui_story_5051_50511601_6_dialog_content = "십여 년 전에 엄마가 집을 나가서 수행한다고 틀어박힌 뒤로,\n전 계속 엄마를 다시 만날 수 있길 바라왔어요.",
  ui_story_5051_50511601_7_dialog_content = "언젠가는 저도 점술로 엄마가 수행하는 곳을 찾을 수도 있을 거란 상상도 했었죠.",
  ui_story_5051_50511601_8_dialog_content = "그리고 엄마가 옛날 모습 그대로인 건 아닐지도 상상했구요.",
  ui_story_5051_50511601_9_dialog_content = "엄마는 언제나 베일을 쓰고, 혼자 숲속 오두막에 틀어박혀 바쁘게 지냈어요.",
  ui_story_5051_50511601_10_dialog_content = "하지만 어느새 십여 년이 지나버렸어요.\n제 기억 속 엄마의 모습은 이미 희미해져 버렸죠.",
  ui_story_5051_50511601_11_dialog_content = "근데 오늘 백야성에서 젊었을 때의 엄마를 만날 수 있을 줄은 정말 몰랐어요!",
  ui_story_5051_50511601_12_dialog_content = "게다가 젊었을 때의 엄마가 이렇게까지... 못미더운 사람인 줄도 몰랐다구요!",
  ui_story_5051_50511601_13_dialog_content = "그런데 엄마는 제 기억 속 엄마보다 훨씬 더 밝고, 사랑스럽고, 용감했어요...",
  ui_story_5051_50511601_14_dialog_content = "엄마가 떠난 뒤로, 아빠는 절 데리고 북방을 떠나려고 했어요.",
  ui_story_5051_50511601_15_dialog_content = "근데 전 우리가 떠나면 언젠가 엄마가 돌아왔을 때 우릴 못 찾을까 무서웠어요.\n그래서 저 혼자 기다리기 시작했어요.",
  ui_story_5051_50511601_16_dialog_content = "그래도 걱정 마세요. 전 친구가 아주 많거든요!",
  ui_story_5051_50511601_17_dialog_content = "그리고 엄마가 남겨준 점술서로 주문도 배웠어요...\n지금은 아직 미숙해서 사고를 잔뜩 치긴 했지만요.",
  ui_story_5051_50511601_18_dialog_content = "그, 그치만 기다려 주세요!",
  ui_story_5051_50511601_19_dialog_content = "전 반드시 보아즈의 가장 대단한 제자가 돼서\n「영원한 기억의 수정」보다 더 대단한 수정구슬을 만들 거예요!",
  ui_story_5051_50511601_20_dialog_content = "그리고... 헤헷, 지금 엄마가 북방 어디에 숨어있는지도\n점술로 찾아낼 수 있게 될지도 모른다구요.",
  ui_story_5051_50511601_21_dialog_content = "아무튼 다음에 만나면 알게 될 거예요~",
  ui_story_5051_50511601_22_dialog_content = "착하네.",
  ui_story_5051_50511601_23_dialog_content = "으, 으아앗──! 깨, 깨어 있었어요?",
  ui_story_5051_50511601_24_dialog_content = "크흠, 방금 한 건 그냥 헛소리였어요. 신경 쓰지 마세요.",
  ui_story_5051_50511601_25_dialog_content = "뭐, 근데 아마 제가 방금 무슨 말을 했는지 이해 못 하셨을 수도 있겠네요...\n자는 데 깨워서 미안해요. 그저 작별 인사를 하고 싶었거든요.",
  ui_story_5051_50511601_26_dialog_content = "응? 내 이해력이 그렇게 나쁘다는 거야?",
  ui_story_5051_50511601_27_dialog_content = "아니, 그게... 계속 취해 있으시잖아요...",
  ui_story_5051_50511601_28_dialog_content = "어라? 근데 왜 갑자기 진지해지신 건데요? 적응이 안 되잖아요!",
  ui_story_5051_50511601_29_dialog_content = "「영원한 기억의 수정」의 비밀을 푸는 건 지금 네 미숙한 솜씨로는 절대 무리야.",
  ui_story_5051_50511601_30_dialog_content = "수정구슬을 만들어 내는 건 말할 것도 없고.",
  ui_story_5051_50511601_31_dialog_content = "쟈키니, 그게 진짜 네가 하고 싶은 일이야?",
  ui_story_5051_50511601_32_dialog_content = "진짜예요! 절대로 진짜라구요!",
  ui_story_5051_50511601_33_dialog_content = "...어? 제가 엄마 딸 쟈키니라는 거 인정 안 하셨던 거 아니었어요?",
  ui_story_5051_50511601_34_dialog_content = "「너」는 확실히 「나」의 딸 쟈키니가 아냐.",
  ui_story_5051_50511601_35_dialog_content = "하지만 난 알 수 있어. 넌 확실히 쟈키니야.",
  ui_story_5051_50511601_36_dialog_content = "쟈키니 씨, 드디어 왔군요.",
  ui_story_5051_50511601_37_dialog_content = "에헤헤, 미안해요. 저도 모르게 말이 길어져서요.",
  ui_story_5051_50511601_38_dialog_content = "왜 그래? 고민이 잔뜩 있는 것처럼 보이는데?",
  ui_story_5051_50511601_39_dialog_content = "그, 그런가요?",
  ui_story_5051_50511601_40_dialog_content = "참! 칼렙 씨, 다시 시도해 보실래요?\n이번엔 확실히 젊은 모습으로 바꿔드릴 수 있어요!",
  ui_story_5051_50511601_X41_dialog_content = "됐습니다. 다시는 토끼 머리로 변하고 싶진 않으니까요.",
  ui_story_5051_50511601_42_dialog_content = "쉿...",
  ui_story_5051_50511601_43_dialog_content = "아버님과 어머님께 들키면 안 돼요.",
  ui_story_5051_50511601_44_dialog_content = "어라? 성주님 아직도 「조슈아」 부인님이랑 인사하고 있어요?",
  ui_story_5051_50511601_45_dialog_content = "아무래도 좀 더 걸릴 것 같아...",
  ui_story_5051_50511601_46_dialog_content = "어머? 아이들이랑 손님은 왜 안 오죠?",
  ui_story_5051_50511601_47_dialog_content = "다들... 먼저 잠들었다.",
  ui_story_5051_50511601_48_dialog_content = "하긴, 오늘은 많이들 피곤했을 테니까요.\n그래도 식사를 안 하면 몸이 못 버틸 텐데요.",
  ui_story_5051_50511601_49_dialog_content = "방으로 식사를 보내주라고 가서 말해 둘게요...",
  ui_story_5051_50511601_50_dialog_content = "그 일이라면 내가 이미 분부해 두었다. 그대는 염려하지 않아도 된다.",
  ui_story_5051_50511601_51_dialog_content = "어머? 다니엘, 이상하네요.",
  ui_story_5051_50511601_52_dialog_content = "뭔가 찔리는 일이라도 했어요?",
  ui_story_5051_50511601_53_dialog_content = "찔리는 일?",
  ui_story_5051_50511601_54_dialog_content = "그래요. 아니면 평소엔 정무로 바쁘신 우리 성주님이\n오늘은 무슨 일로 부인을 돌볼 시간이 생겼을까요?",
  ui_story_5051_50511601_55_dialog_content = "나는 그저...",
  ui_story_5051_50511601_56_dialog_content = "우리가 이처럼 함께 앉아 식사를 한 것도 정말 오래전이라고 생각했을 뿐이다.",
  ui_story_5051_50511601_57_dialog_content = "그것도 그렇네요. 하지만...\n난 당신이 진작에 이런 일엔 신경 안 쓰게 된 줄 알았는데요.",
  ui_story_5051_50511601_58_dialog_content = "미안하다.",
  ui_story_5051_50511601_59_dialog_content = "자, 그만. 오늘은 왜 계속 사과만 하실까?",
  ui_story_5051_50511601_60_dialog_content = "도대체 무슨 일 때문에 「미안하다」고 하는 건데요?",
  ui_story_5051_50511601_61_dialog_content = "지금은 아직 그대에게 말할 수 없다.",
  ui_story_5051_50511601_62_dialog_content = "다니엘...?",
  ui_story_5051_50511601_63_dialog_content = "카르티마 가문의 일 때문인가요?",
  ui_story_5051_50511601_64_dialog_content = "다니엘, 당신 정말 그 가문의 어느 한 사람도 봐주지 않을 생각인가요?",
  ui_story_5051_50511601_65_dialog_content = "......",
  ui_story_5051_50511601_66_dialog_content = "당연히 아니지.",
  ui_story_5051_50511601_67_dialog_content = "처벌해야 할 것은 진정으로 죄가 있는 자들뿐이다.",
  ui_story_5051_50511601_68_dialog_content = "날 위로하려고 그런 말로 속이는 건 아니고요?",
  ui_story_5051_50511601_69_dialog_content = "그렇지 않아, 조슈아!",
  ui_story_5051_50511601_70_dialog_content = "<color=#e8d9bb>콰지직!</color>",
  ui_story_5051_50511601_71_dialog_content = "음? 조슈아?",
  ui_story_5051_50511601_72_dialog_content = "<anim type=Shake>...거짓말.</anim>",
  ui_story_5051_50511601_73_dialog_content = "조슈아?",
  ui_story_5051_50511601_74_dialog_content = "무슨 일이야? 조슈아!",
  ui_story_5051_50511601_75_dialog_content = "<anim type=Shake>당신은... 날... 속였...어...</anim>",
  ui_story_5051_50511601_76_dialog_content = "조슈아, 내가 그대를 그런 모습으로 만든 것인가?",
  ui_story_5051_50511601_77_dialog_content = "나는 모든 것을 걸고 카르티마 가문을 처리했다...",
  ui_story_5051_50511601_78_dialog_content = "나는 그대의 판단을 믿지 못했고, 그대의 충고를 무시했다...",
  ui_story_5051_50511601_79_dialog_content = "나는 그대의 수고로움을 알아주지도 못했고,\n가정의 책임을 당연하다는 듯이 그대에게 짊어지웠다...",
  ui_story_5051_50511601_80_dialog_content = "나는 그대가 필요할 때 곁에 있어 주지 못했다...",
  ui_story_5051_50511601_81_dialog_content = "...미안하다.",
  ui_story_5051_50511601_82_dialog_content = "<color=#e8d9bb>콰지지직!</color>",
  ui_story_5051_50511601_83_dialog_content = "<anim type=Shake>다니엘...</anim>",
  ui_story_5051_50511601_84_dialog_content = "여기다! 난 여기 있다! 조슈아!",
  ui_story_5051_50511601_85_dialog_content = "<anim type=Shake>다니엘... 베로니카... 카렌...</anim>",
  ui_story_5051_50511601_86_dialog_content = "<anim type=Shake>아아아아아악!</anim>",
  ui_story_5051_50511601_87_dialog_content = "조슈아!!!",
  ui_story_5051_50511601_88_dialog_content = "어머님! 어머님께 무슨 일이 생긴 걸까요?!",
  ui_story_5051_50511601_89_dialog_content = "<color=#e8d9bb>우르릉!</color>",
  ui_story_5051_50511601_90_dialog_content = "<color=#e8d9bb>콰르르릉──!</color>",
  ui_story_5051_50511601_91_dialog_content = "또 그 천둥소리야...",
  ui_story_5051_50511601_92_dialog_content = "지진? 이거 지진인가요?",
  ui_story_5051_50511601_93_dialog_content = "그럴 리가 없어요. 실제 역사 속 이날 밤엔 지진 같은 건 일어나지 않았어요!",
  ui_story_5051_50511601_94_dialog_content = "주변이... 흐릿해진 것 같아.",
  ui_story_5051_50511601_95_dialog_content = "나도! 얼마 안 남은 감응 능력으로 겨우 방향만 알 수 있을 정도야...",
  ui_story_5051_50511601_96_dialog_content = "쟈키니 씨, 시간이 다 된 건 아닙니까?!",
  ui_story_5051_50511601_97_dialog_content = "아직 더 남았어요. 하루가 끝날 때까진 아직 충분히 시간이 남았는걸요...\n아니겠죠...?",
  ui_story_5051_50511601_98_dialog_content = "설마 우리 정말 이 수정이랑 현실 세계의 틈으로 빠져버리는 거야?",
  ui_story_5051_50511601_99_dialog_content = "쟈키니 씨, 뭘 꾸물대고 있는 겁니까?",
  ui_story_5051_50511601_100_dialog_content = "어서 모두 데리고 나가세요!",
  ui_story_5051_50511601_101_dialog_content = "다들 제 곁으로 오세요!",
  ui_story_5051_50511601_102_dialog_content = "하지만 아버님이 아직...",
  ui_story_5051_50511601_103_dialog_content = "저런 가식적인 위인을 기다리다 모두가 여기 갇혀버리게 만들 순 없어요!\n어서요!",
  ui_story_5051_50511601_104_dialog_content = "아무리 그래도 되는 데까지 해보지도 않고 갈 순 없잖아요...!",
  ui_story_5051_50511601_105_dialog_content = "(솔라드를 부른다)",
  ui_story_5051_50511601_106_dialog_content = "성주님! 여기예요!",
  ui_story_5051_50511601_107_dialog_content = "아버님!",
  ui_story_5051_50511601_108_dialog_content = "성주 전하!",
  ui_story_5051_50511601_109_dialog_content = "왜 아무 반응도 없는 거지...",
  ui_story_5051_50511601_110_dialog_content = "[감응한다]",
  ui_story_5051_50511601_111_dialog_content = "제길...",
  ui_story_5051_50511601_112_dialog_content = "「영원한 기억의 수정」 속에선 역시 다른 사람과 감응할 수가 없어!",
  ui_story_5051_50511601_113_dialog_content = "앗...",
  ui_story_5051_50511601_114_dialog_content = "미아, 왜 그래?",
  ui_story_5051_50511601_115_dialog_content = "우리 뒤에 있던 공간이... 조금씪 무너지면서 사라졌어!",
  ui_story_5051_50511601_116_dialog_content = "PlayerName 씨, 서둘러야 해요!",
  ui_story_5051_50511601_117_dialog_content = "다들 같이 가자! 아까 성주님이 있던 곳으로 가는 거야!",
  ui_story_5051_50511601_118_dialog_content = "쟈키니, 만약 정말 마지막까지도 성주님을 못 찾으면...",
  ui_story_5051_50511601_119_dialog_content = "그땐 우리라도 나갈 수밖에 없어!",
  ui_story_5051_50511601_120_dialog_content = "...알겠어요!",
  ui_story_5051_50511601_121_dialog_content = "쳇.",
  ui_story_5051_50511601_122_dialog_content = "<color=#e8d9bb>휘이익──!</color>",
  ui_story_5051_50511601_123_dialog_content = "방금 누가 뛰어가지 않았어?",
  ui_story_5051_50511601_124_dialog_content = "이런 상황에 그렇게 빨리 달릴 수 있는 사람이 있을까?",
  ui_story_5051_50511601_125_dialog_content = "<anim type=Shake><size=30>다니엘... 베로니카... 카렌...</size></anim>",
  ui_story_5051_50511601_126_dialog_content = "어? 누가 내 이름을 부른 것 같아...",
  ui_story_5051_50511601_127_dialog_content = "소리가 너무 작아서 어디서 들린 건지 모르겠어.",
  ui_story_5051_50511601_128_dialog_content = "<anim type=Shake>거기, 있었니?</anim>",
  ui_story_5051_50511601_129_dialog_content = "앗...",
  ui_story_5051_50511601_130_dialog_content = "조심해라!",
  ui_story_5051_50511601_131_dialog_content = "아버님!",
  ui_story_5051_50511601_132_dialog_content = "불청객이 있다. 모두 경계하도록!",
  ui_story_5051_50511601_133_dialog_content = "엄청난 공격이야... 이런 상황에서 대체 누가 우릴 공격하는 거지?",
  ui_story_5051_50511601_134_dialog_content = "이미... 수정과 현실 세계의 틈에 빠지고 만 건가...",
  ui_story_5051_50511601_135_dialog_content = "안 돼... 절대로 안 돼!",
  ui_story_5051_50511601_136_dialog_content = "<anim type=Shake>여기, 있었구나.</anim>",
  ui_story_5051_50511601_137_dialog_content = "으아악! 괴물이다아아!",
  ui_story_5051_50511601_138_dialog_content = "PlayerName, 지금 방향을 분간할 수 있는 것은 그대뿐이다.",
  ui_story_5051_50511601_139_dialog_content = "지휘는 그대에게 맡기겠다!",
  ui_story_5051_50511602_1_dialog_content = "하아... 하아...",
  ui_story_5051_50511602_2_dialog_content = "미아, 잠시 쉬도록 해라!",
  ui_story_5051_50511602_3_dialog_content = "하지만... 안 돼요... 저도 아버님과 모두를... 돕고 싶어요...",
  ui_story_5051_50511602_4_dialog_content = "거기니?",
  ui_story_5051_50511602_5_dialog_content = "「수정이여!」",
  ui_story_5051_50511602_6_dialog_content = "으아아, 제발... 이 괴물 대체 왜 이렇게 끈질기게 공격하는 거죠?!",
  ui_story_5051_50511602_7_dialog_content = "쟈키니, 「영원한 기억의 수정」 속에 왜 저런 괴물이 있어?",
  ui_story_5051_50511602_8_dialog_content = "저, 저도 모르겠는데요...",
  ui_story_5051_50511602_9_dialog_content = "저 괴물 진짜로 당시 백야성에선 없었던 건가요?!",
  ui_story_5051_50511602_10_dialog_content = "......",
  ui_story_5051_50511602_11_dialog_content = "「백야! 비호를!」",
  ui_story_5051_50511602_12_dialog_content = "당시 백야성에는 저런 괴물이 나타난 적은 없었다.",
  ui_story_5051_50511602_13_dialog_content = "허나 낙심하지 마라!",
  ui_story_5051_50511602_14_dialog_content = "아까에 비하면 상대의 힘은 분명히 약해져 있다.\n공격의 간격도 갈수록 길어지고 있다.",
  ui_story_5051_50511602_15_dialog_content = "쟈키니! 다음 공격 후의 틈을 타서 우리를 데리고 나가도록 해라!",
  ui_story_5051_50511602_16_dialog_content = "네, 성주님!",
  ui_story_5051_50511602_17_dialog_content = "<color=#e8d9bb>..................</color>",
  ui_story_5051_50511602_18_dialog_content = "왜 갑자기 가만히 있는 거죠?",
  ui_story_5051_50511602_19_dialog_content = "쉿, 들려?",
  ui_story_5051_50511602_20_dialog_content = "<anim type=Shake><size=30>다니엘... 베로니카... 카렌...</size></anim>",
  ui_story_5051_50511602_21_dialog_content = "지금 저 괴물이... 아버님과 우리 이름을 부른 건가요?",
  ui_story_5051_50511602_22_dialog_content = "<anim type=Shake>다니엘, 베로니카, 카렌.</anim>",
  ui_story_5051_50511602_23_dialog_content = "이 목소리...",
  ui_story_5051_50511602_24_dialog_content = "<anim type=Shake>그리고... 칼렙.</anim>",
  ui_story_5051_50511602_25_dialog_content = "<color=#FFB400>누나</color>?!",
  ui_story_5051_50511602_26_dialog_content = "그럴 리가 없다!",
  ui_story_5051_50511602_27_dialog_content = "아... 누나... 누나인가요?",
  ui_story_5051_50511602_28_dialog_content = "아니야... 그럴 리가 없어! 아니라고! 어째서! 누나는 여기 있을 리가 없어!",
  ui_story_5051_50511602_29_dialog_content = "설마...",
  ui_story_5051_50511602_30_dialog_content = "......",
  ui_story_5051_50511602_31_dialog_content = "왜 갑자기 멈춘 거지?",
  ui_story_5051_50511602_32_dialog_content = "<anim type=Shake>안 돼요!</anim>",
  ui_story_5051_50511602_33_dialog_content = "<anim type=Shake>이래서는 안 돼요!</anim>",
  ui_story_5051_50511602_34_dialog_content = "<anim type=Shake>어째서?</anim>",
  ui_story_5051_50511602_35_dialog_content = "<anim type=Shake>저들은 모든 괴로움의 근원이야.</anim>",
  ui_story_5051_50511602_36_dialog_content = "<anim type=Shake>내 이상의 실현을 막아선 장애물들이라고!</anim>",
  ui_story_5051_50511602_37_dialog_content = "<anim type=Shake>아니, 저들이야말로 내게 가장 중요한 사람들이에요!</anim>",
  ui_story_5051_50511602_38_dialog_content = "<anim type=Shake>저들만 없애면 난 밖으로 나갈 수 있어!</anim>",
  ui_story_5051_50511602_39_dialog_content = "<anim type=Shake>뭘 망설이는 거야? 저들은 이제 더는 못 버텨.</anim>",
  ui_story_5051_50511602_40_dialog_content = "<anim type=Shake>시끄러워요... 시끄럽다고요!</anim>",
  ui_story_5051_50511602_41_dialog_content = "<anim type=Shake>빨리 나가요!</anim>",
  ui_story_5051_50511602_42_dialog_content = "지금 혼잣말하는 거야?",
  ui_story_5051_50511602_X43_dialog_content = "엄청 이상하네요... 꼭 자기랑 싸우는 것 같잖아요.",
  ui_story_5051_50511602_44_dialog_content = "누나... 정말... 정말 누나인가요?",
  ui_story_5051_50511602_45_dialog_content = "어, 어머님...?",
  ui_story_5051_50511602_46_dialog_content = "감히 조슈아를 가장하려 들다니.",
  ui_story_5051_50511602_47_dialog_content = "용서할 수 없다!",
  ui_story_5051_50511602_48_dialog_content = "<anim type=Shake>솔...</anim>",
  ui_story_5051_50511602_49_dialog_content = "「모든 별이여! 흔들려라!」",
  ui_story_5051_50511602_50_dialog_content = "<anim type=Shake>으윽...</anim>",
  ui_story_5051_50511602_51_dialog_content = "<anim type=Shake><size=45>난... 당신을... 증오해...!</size></anim>",
  ui_story_5051_50511602_52_dialog_content = "뭐라?",
  ui_story_5051_50511602_53_dialog_content = "성주님의 공격이 효과가 있었나 봐요!",
  ui_story_5051_50511602_54_dialog_content = "왠지 괴로워 보여... 근데 몸의 고통 때문이 아닌 것 같은데?",
  ui_story_5051_50511602_55_dialog_content = "누나일 리가 없어.... 누나일 리가 없잖아... 만약 누나가 맞다면...",
  ui_story_5051_50511602_56_dialog_content = "쟈키니 씨! 어서 전부 데리고 나가요! 빨리!",
  ui_story_5051_50511602_57_dialog_content = "<color=#e8d9bb>둥!</color>",
  ui_story_5051_50511602_58_dialog_content = "방금 저거 시계 소리야?",
  ui_story_5051_50511602_59_dialog_content = "끄, 끄, 끝장이에요! 열두 시 종이 울려버렸어요!",
  ui_story_5051_50511602_60_dialog_content = "우리... 이제 여기 갇히는 거야?",
  ui_story_5051_50511602_61_dialog_content = "어쨰서... 이제야 겨우 찾았는데...",
  ui_story_5051_50511602_62_dialog_content = "이제 거의 다 됐는데...",
  ui_story_5051_50511602_63_dialog_content = "어째서!",
  ui_story_5051_50511602_64_dialog_content = "어? 칼렙 씨... 손에 든 그거...",
  ui_story_5051_50511602_65_dialog_content = "설마 이 세계에 있던 「영원한 기억의 수정」인가요?!",
  ui_story_5051_50511602_66_dialog_content = "뭐야, 「수정」 속 「수정」?",
  ui_story_5051_50511602_67_dialog_content = "하하... 이제는 찾아낸들 쓸모없게 됐잖아요.",
  ui_story_5051_50511602_68_dialog_content = "<color=#e8d9bb>둥!</color>",
  ui_story_5051_50511602_69_dialog_content = "열두 시의 종소리가 곧 끝날 거야!",
  ui_story_5051_50511602_70_dialog_content = "칼렙, 그대는 왜 수정 속 세계에서 그걸 찾고 있었지?",
  ui_story_5051_50511602_71_dialog_content = "소용없어요... 이제 무슨 말을 한들 아무 의미도 없어요...",
  ui_story_5051_50511602_72_dialog_content = "아니요, 어쩌면 도움이 될지도 몰라요!",
  ui_story_5051_50511602_73_dialog_content = "칼렙 씨! 수정을 저한테 주세요!",
  ui_story_5051_50511602_74_dialog_content = "...자.",
  ui_story_5051_50511602_75_dialog_content = "「엄마」...",
  ui_story_5051_50511602_76_dialog_content = "설마 그때 벌써 이렇게 될 줄 아셨던 건가요?",
  ui_story_5051_50511602_77_dialog_content = "사람들은 다들 점으로 미래를 알고 싶어 해.",
  ui_story_5051_50511602_78_dialog_content = "하지만 그러다가 난 깨달았어.\n우린 늘 자기 기억을 잊어버리는 속도를 너무 과소평가하고 있어.",
  ui_story_5051_50511602_79_dialog_content = "그러니까 어떻게 보면 미래보다 더 「예지」할 수 없는 건 <color=#FFB400>과거</color>일 거야.",
  ui_story_5051_50511602_80_dialog_content = "그게 바로 내가 「영원한 기억의 수정」을 만든 이유야.",
  ui_story_5051_50511602_81_dialog_content = "처음엔 이게 가장 안전하게 과거를 돌아보는 방법이라고 생각했어.",
  ui_story_5051_50511602_82_dialog_content = "하지만 네가 나타난 덕분에 난 「영원한 기억의 수정」에도 예상 밖의 일이\n일어날 수 있다는 걸 알았어.",
  ui_story_5051_50511602_83_dialog_content = "다행히 「영원한 기억의 수정」의 세계에는 긴급 대피 장치가 하나 있어.",
  ui_story_5051_50511602_84_dialog_content = "...「영원한 기억의 수정」 속 「영원한 기억의 수정」.",
  ui_story_5051_50511602_85_dialog_content = "이건 내가 유일하게 점술서에 기록하지 않은 내용이야.",
  ui_story_5051_50511602_86_dialog_content = "앞으로 네가 영원히 이 지식을 쓰는 일이 없길 바랄게.",
  ui_story_5051_50511602_87_dialog_content = "저, 절대로 엄마를 실망시키지 않을게요!",
  ui_story_5051_50511602_88_dialog_content = "「레트로, 레트로, 레트로!」",
  ui_story_5051_50511602_89_dialog_content = "「아드 프라이센스!」",
  ui_story_5051_50511602_90_dialog_content = "시간을 기점으로 되돌려, 우리를 현실 세계로 되돌려 주세요!",
  ui_story_5051_50511602_91_dialog_content = "<size=45>「아브라카다브라!」</size>",
  ui_story_5051_50511602_92_dialog_content = "으앗!",
  ui_story_5051_50511602_93_dialog_content = "또야... 이 공간이 회전하는 느낌...",
  ui_story_5051_50511602_94_dialog_content = "다들 서로 손을 꽉 잡으세요! 놓치면 안 돼요!",
  ui_story_5051_50511602_95_dialog_content = "미아, PlayerName, 어서 내 품으로 와라!",
  ui_story_5051_50511602_96_dialog_content = "으앗... 어떡하죠?! 칼렙 씨가 안 당겨져요!",
  ui_story_5051_50511602_97_dialog_content = "누나, 미안해요... 이제 다시는 곁에 있을 수 없게 됐네요.",
  ui_story_5051_50511602_98_dialog_content = "안 돼... 한 사람도 빠트릴 수 없어!",
  ui_story_5051_50511602_99_dialog_content = "PlayerName?!",
  ui_story_5051_50511602_100_dialog_content = "칼렙 씨!",
  ui_story_5051_50511602_101_dialog_content = "제 손 잡아요!",
  ui_story_5051_50511602_102_dialog_content = "으윽!",
  ui_story_5051_50511602_103_dialog_content = "PlayerName! 계속 밖으로 나가면 아버님도 널 놓치고 말 거야!",
  ui_story_5051_50511602_104_dialog_content = "포기 못 해!",
  ui_story_5051_50511602_105_dialog_content = "PlayerName!!!",
  ui_story_5051_50511602_106_dialog_content = "잡았다! 칼렙 씨! 잡았어요!",
  ui_story_5051_50511602_107_dialog_content = "...PlayerName?",
  ui_story_5051_50511602_108_dialog_content = "<color=#e8d9bb>쨍그랑──</color>",
  ui_story_5051_50511602_109_dialog_content = "(어머? 잔이 깨지는 소리인가요?)",
  ui_story_5051_50511602_110_dialog_content = "(방에 잔은 하나뿐인데...)",
  ui_story_5051_50511602_111_dialog_content = "(결국 좋은 술로도 칼렙 씨를 진정시킬 순 없었던 건가요.)",
  ui_story_5051_50511602_112_dialog_content = "흐음? 「미즈 로트」, 방금 꽤나 큰 소리가 났는데 말이지.",
  ui_story_5051_50511602_113_dialog_content = "어느 「손님」이 성주의 방에서 물건을 깨트릴 만큼 부주의한 건지 모르겠군.",
  ui_story_5051_50511602_114_dialog_content = "아니면... 어느 「손님」이 성주를 노하게 해서,\n뭐라도 던지지 않고는 직성이 안 풀리는 건 아니겠지?",
  ui_story_5051_50511602_115_dialog_content = "공작님의 상상력에는 정말 감탄하지 않을 수가 없네요.",
  ui_story_5051_50511602_116_dialog_content = "다만 성주 전하께서 손님과 어떤 말씀을 나누고, 무엇을 하시는지는\n저희가 짐작해도 될 일이 아니랍니다.",
  ui_story_5051_50511602_117_dialog_content = "흥, 너는 이제 나이트워치의 대장도 아닐 텐데?",
  ui_story_5051_50511602_118_dialog_content = "아직 성주 전하를 위해 일하고 있는 이상, 저도 직무를 게을리해선 안 되겠죠~",
  ui_story_5051_50511602_119_dialog_content = "직무? 기껏해야 임시로 이 연회를 주관할 뿐이잖나.",
  ui_story_5051_50511602_120_dialog_content = "그렇게나 남의 일을 하는 걸 좋아한다면야,\n내 아들 생일 연회 때도 「미즈 로트」에게 부탁해도 되겠나?",
  ui_story_5051_50511602_121_dialog_content = "공작님, 아까는 왠지 설명이 충분하지 않았던 것 같네요.",
  ui_story_5051_50511602_122_dialog_content = "저는 지금 아직 성주 전하를 위해 일하고 있습니다.",
  ui_story_5051_50511602_123_dialog_content = "공작님이 무슨 말씀을 하시든, 성주 전하께서는 오늘 밤 단독으로\n공작님의 아드님을 접견하실 시간은 없으시답니다.",
  ui_story_5051_50511602_124_dialog_content = "하하하, 「미즈 로트」, 내가 그런 요구를 한 적은 전혀 없을 텐데?",
  ui_story_5051_50511602_125_dialog_content = "난 그저 밤도 깊었고 해서 성주에게 미리 인사나 하려던 것뿐이었다만.",
  ui_story_5051_50511602_126_dialog_content = "그런 좁은 도량으로 윗사람의 생각을 짐작하려 들다니...",
  ui_story_5051_50511602_127_dialog_content = "성주 전하의 곁을 모시는 자가 취할 태도가 아니지 않은가.",
  ui_story_5051_50511602_128_dialog_content = "어머나, 역시 방심해선 안 될 일이네요.",
  ui_story_5051_50511602_129_dialog_content = "<color=#e8d9bb>휘이잉──</color>",
